		description = "Mark the shops Asset Manager suggests on the world map. Hover one for what to sell there.",
		section = shopSection,
		position = 6
	)
	default boolean shopMapMarkers()
	{
		return true;
	}

	@ConfigSection(
		name = "Bank & inventory",
		description = "Icons, the price tooltip and keeping items",
		position = 4
