package com.assetmanager;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import lombok.Getter;

/** Item ids Asset Manager currently has a suggestion for, in display order. Immutable. */
@Getter
public class Suggestions
{
	public enum Kind
	{
		COFFER,
		ALCH,
		SHOP,
		GE,
	}

	public static final Suggestions NONE = new Suggestions(Collections.emptyList(), Collections.emptyList(),
		Collections.emptyList(), Collections.emptyList());

	private final Set<Integer> coffer;
	private final Set<Integer> alch;
	private final Set<Integer> shop;
	private final Set<Integer> ge;

	public Suggestions(List<Integer> cofferIds, List<Integer> alchIds, List<Integer> shopIds)
	{
		this(cofferIds, alchIds, shopIds, Collections.emptyList());
	}

	/** An item only gets one suggestion: coffer first, then alch, then shop, then the GE. */
	public Suggestions(List<Integer> cofferIds, List<Integer> alchIds, List<Integer> shopIds, List<Integer> geIds)
	{
		coffer = Collections.unmodifiableSet(new LinkedHashSet<>(cofferIds));
		alch = without(alchIds, coffer);
		shop = without(shopIds, coffer, alch);
		ge = without(geIds, coffer, alch, shop);
	}

	@SafeVarargs
	private static Set<Integer> without(List<Integer> ids, Set<Integer>... earlier)
	{
		Set<Integer> s = new LinkedHashSet<>(ids);
		for (Set<Integer> e : earlier)
		{
			s.removeAll(e);
		}
		return Collections.unmodifiableSet(s);
	}

	/** Which suggestion an item has, or null if none. */
	public Kind getIcon(int canonicalId)
	{
		return coffer.contains(canonicalId) ? Kind.COFFER
			: alch.contains(canonicalId) ? Kind.ALCH
			: shop.contains(canonicalId) ? Kind.SHOP
			: ge.contains(canonicalId) ? Kind.GE
			: null;
	}

	public boolean contains(int canonicalId)
	{
		return getIcon(canonicalId) != null;
	}

	public boolean isEmpty()
	{
		return coffer.isEmpty() && alch.isEmpty() && shop.isEmpty() && ge.isEmpty();
	}
}

package com.assetmanager.bank;

import com.assetmanager.dest.Destination;
import com.assetmanager.dest.Destinations;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.util.Text;

/**
 * Temporary bank views of where Asset Manager suggests spare items go, opened from the side panel: one per
 * destination (Death's coffer, high alching, the GE, each shop, kept items, or everything). Items are laid out most
 * valuable first, and the Everything view leaves a blank row between destinations. Nothing is added to the bank's
 * tab list: each view is a virtual tag that's only on screen while it's open. Opening one with the bank closed shows
 * it the next time the bank opens.
 * <p>
 * Must be used on the client thread.
 */
@Singleton
public class BankViews
{
	private static final int ITEMS_PER_ROW = 8;
	private static final String TAG_PREFIX = "asset manager - ";
	/** The permanent tab older versions added to the tab list. */
	private static final String LEGACY_TAG = "asset manager";

	private final Client client;
	private final TagManager tagManager;
	private final BankTagsService bankTags;
	private final ConfigManager configManager;
	private final ItemManager itemManager;

	private volatile Destinations destinations = Destinations.NONE;
	/** Tags registered so far, by destination key. */
	private final Map<String, String> tags = new HashMap<>();
	/** Asked for while the bank was closed. */
	private String pending;
	private String open;
	private List<Integer> openLayout;

	@Inject
	BankViews(Client client, TagManager tagManager, BankTagsService bankTags, ConfigManager configManager, ItemManager itemManager)
	{
		this.client = client;
		this.tagManager = tagManager;
		this.bankTags = bankTags;
		this.configManager = configManager;
		this.itemManager = itemManager;
	}

	/** Identifies a destination across recalculations. */
	public static String key(Destination d)
	{
		return d.getKind() == Destination.Kind.SHOP ? "shop:" + d.getName() : d.getKind().name();
	}

	public void register()
	{
		removeLegacyTab();
	}

	public void unregister()
	{
		close();
		for (String tag : tags.values())
		{
			tagManager.unregisterTag(tag);
			configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, layoutKey(tag));
		}
		tags.clear();
		pending = null;
	}

	/**
	 * Shows a destination's items in the bank now, or the next time it opens.
	 *
	 * @return whether the bank was open
	 */
	public boolean show(Destination d)
	{
		String key = key(d);
		tags.computeIfAbsent(key, k ->
		{
			String tag = Text.standardize(TAG_PREFIX + d.getName());
			tagManager.registerTag(tag, itemId -> contains(k, itemManager.canonicalize(itemId)));
			return tag;
		});
		if (!isBankOpen())
		{
			pending = key;
			return false;
		}
		open(key);
		return true;
	}

	public void close()
	{
		if (open != null && tags.get(open).equals(bankTags.getActiveTag()))
		{
			bankTags.closeBankTag();
		}
		open = null;
		pending = null;
	}

	/** Opens a view asked for while the bank was closed, and notices when the player leaves one. */
	public void onGameTick()
	{
		if (!isBankOpen())
		{
			return;
		}
		if (pending != null)
		{
			String key = pending;
			pending = null;
			open(key);
		}
		else if (open != null && !tags.get(open).equals(bankTags.getActiveTag()))
		{
			open = null;
		}
	}

	public void update(Destinations destinations)
	{
		this.destinations = destinations;
		// Refresh the open view when its contents change, e.g. after withdrawing everything in a section
		if (open != null && tags.get(open).equals(bankTags.getActiveTag()) && !layout(open).equals(openLayout))
		{
			open(open);
		}
	}

	/** Whether an Asset Manager view is on screen. */
	public boolean isShowing()
	{
		return open != null && isBankOpen() && tags.get(open).equals(bankTags.getActiveTag());
	}

	/** The kind of Asset Manager view on screen, or null if none is. */
	public Destination.Kind showingKind()
	{
		String key = open;
		if (key == null || !isShowing())
		{
			return null;
		}
		return key.startsWith("shop:") ? Destination.Kind.SHOP : Destination.Kind.valueOf(key);
	}

	private void open(String key)
	{
		String tag = tags.get(key);
		List<Integer> layout = layout(key);
		if (layout.isEmpty())
		{
			configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, layoutKey(tag));
		}
		else
		{
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, layoutKey(tag),
				layout.stream().map(String::valueOf).collect(Collectors.joining(",")));
		}
		bankTags.openBankTag(tag, 0);
		open = key;
		openLayout = layout;
	}

	private Destination find(String key)
	{
		for (Destination d : destinations.getList())
		{
			if (key(d).equals(key))
			{
				return d;
			}
		}
		return null;
	}

	private boolean contains(String key, int itemId)
	{
		Destination d = find(key);
		return d != null && d.getItemIds().contains(itemId);
	}

	/** The Everything view is split into destinations; the rest are one list. */
	private List<List<Integer>> sections(String key)
	{
		Destination d = find(key);
		if (d == null)
		{
			return Collections.emptyList();
		}
		if (d.getKind() != Destination.Kind.ALL)
		{
			return Collections.singletonList(d.getItemIds());
		}
		List<List<Integer>> sections = new ArrayList<>();
		for (Destination part : destinations.getList())
		{
			if (part.getKind() != Destination.Kind.ALL && part.getKind() != Destination.Kind.KEPT)
			{
				sections.add(part.getItemIds());
			}
		}
		return sections;
	}

	private List<Integer> layout(String key)
	{
		return buildLayout(sections(key));
	}

	/** Each section's items in order, with the rest of its row and one more row left blank between sections. */
	static List<Integer> buildLayout(List<? extends List<Integer>> sections)
	{
		List<Integer> layout = new ArrayList<>();
		HashSet<Integer> seen = new HashSet<>();
		for (List<Integer> section : sections)
		{
			List<Integer> fresh = section.stream().filter(seen::add).collect(Collectors.toList());
			if (fresh.isEmpty())
			{
				continue;
			}
			if (!layout.isEmpty())
			{
				while (layout.size() % ITEMS_PER_ROW != 0)
				{
					layout.add(-1);
				}
				for (int i = 0; i < ITEMS_PER_ROW; i++)
				{
					layout.add(-1);
				}
			}
			layout.addAll(fresh);
		}
		return layout;
	}

	private boolean isBankOpen()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return items != null && !items.isHidden();
	}

	private static String layoutKey(String tag)
	{
		return BankTagsPlugin.TAG_LAYOUT_PREFIX + Text.standardize(tag);
	}

	/**
	 * Older versions added a permanent "asset manager" tab. Bank Tags only holds tabs in memory while the bank is
	 * open, so the tab list is edited in config directly.
	 */
	private void removeLegacyTab()
	{
		String csv = configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG);
		List<String> tabs = csv == null || csv.isEmpty() ? new ArrayList<>() : new ArrayList<>(Text.fromCSV(csv));
		if (tabs.remove(LEGACY_TAG))
		{
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
		}
		configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + LEGACY_TAG);
		configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_LAYOUT_PREFIX + LEGACY_TAG);
	}
}

package com.assetmanager.coffer;

import com.assetmanager.value.ItemValues;
import lombok.Value;

/** A banked item that could be sacrificed to Death's coffer, compared against its next best use. */
@Value
public class CofferCandidate
{
	ItemValues values;
	int quantity;
	/** Coins added to the coffer per unit sacrificed. */
	long cofferUnit;
	/** Coins per unit from the best alternative (GE sale, alching, ...). */
	long alternativeUnit;
	/** Short label for the alternative, e.g. "GE sell" or "High alch". */
	String alternativeLabel;

	public long getCofferTotal()
	{
		return cofferUnit * quantity;
	}

	/**
	 * How much more (as a fraction) the coffer gives than the best alternative.
	 * Items with no alternative value are treated as infinitely better.
	 */
	public double getGainRatio()
	{
		if (alternativeUnit <= 0)
		{
			return Double.POSITIVE_INFINITY;
		}
		return (double) (cofferUnit - alternativeUnit) / alternativeUnit;
	}
}

package com.assetmanager.coffer;

import java.util.List;
import lombok.Value;

@Value
public class CofferPlan
{
	@Value
	public static class Step
	{
		CofferCandidate candidate;
		int quantity;

		public long getCofferValue()
		{
			return candidate.getCofferUnit() * quantity;
		}
	}

	/** Every banked item worth sacrificing, best first. */
	List<CofferCandidate> candidates;
	/** Items to sacrifice to reach the target, best first. */
	List<Step> steps;
	/** Coins to deposit after sacrificing the planned items. */
	long coinsToDeposit;
	/** Coins still missing after all items and bank coins are used. */
	long remainingShortfall;
	long target;
	long shortfall;
}

package com.assetmanager.coffer;

import com.assetmanager.value.ItemValues;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

/**
 * Decides which banked items are better sacrificed to Death's coffer than sold or alched,
 * and builds a plan to reach a target coffer balance.
 */
public final class CofferPlanner
{
	private CofferPlanner()
	{
	}

	/**
	 * @param bank           banked items (canonical id -> values) with quantities; coins must be excluded
	 * @param quantities     quantity per item id
	 * @param canUseGe       false for ironmen
	 * @param natureRuneCost cost of a nature rune, deducted from alch value
	 * @param minGainPercent only suggest items where the coffer beats the alternative by at least this much
	 */
	public static List<CofferCandidate> findCandidates(Map<Integer, ItemValues> bank, Map<Integer, Integer> quantities,
		boolean canUseGe, int natureRuneCost, int minGainPercent)
	{
		List<CofferCandidate> candidates = new ArrayList<>();
		for (Map.Entry<Integer, ItemValues> e : bank.entrySet())
		{
			ItemValues v = e.getValue();
			int qty = quantities.getOrDefault(e.getKey(), 0);
			long coffer = v.getCofferValue();
			if (qty <= 0 || coffer <= 0)
			{
				continue;
			}

			long alch = v.getHighAlchNet(natureRuneCost);
			long ge = canUseGe ? v.getGeNetSell() : 0;
			CofferCandidate c = ge >= alch
				? new CofferCandidate(v, qty, coffer, ge, "GE sell")
				: new CofferCandidate(v, qty, coffer, alch, "High alch");

			if (c.getGainRatio() * 100 >= minGainPercent)
			{
				candidates.add(c);
			}
		}
		candidates.sort(Comparator.comparingDouble(CofferCandidate::getGainRatio).reversed()
			.thenComparing(Comparator.comparingLong(CofferCandidate::getCofferTotal).reversed()));
		return candidates;
	}

	/**
	 * Greedily picks the most efficient items until the target is met, then falls back to bank coins
	 * (deposited 1:1).
	 */
	public static CofferPlan plan(List<CofferCandidate> candidates, long balance, long target, long bankCoins)
	{
		long shortfall = Math.max(0, target - balance);
		long needed = shortfall;
		List<CofferPlan.Step> steps = new ArrayList<>();
		for (CofferCandidate c : candidates)
		{
			if (needed <= 0)
			{
				break;
			}
			// Round up so the target is actually reached.
			long units = Math.min(c.getQuantity(), (needed + c.getCofferUnit() - 1) / c.getCofferUnit());
			steps.add(new CofferPlan.Step(c, (int) units));
			needed -= units * c.getCofferUnit();
		}
		long coins = Math.min(Math.max(0, needed), bankCoins);
		needed -= coins;
		return new CofferPlan(candidates, steps, coins, Math.max(0, needed), target, shortfall);
	}
}

package com.assetmanager.coffer;

import com.assetmanager.AssetManagerConfig;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Keeps track of the Death's coffer balance. There is no documented variable for it, so it is read from
 * several places and the most recent reading wins:
 * <ul>
 *     <li>the value the server sends with gravestone/coffer interfaces</li>
 *     <li>the "Coffer: ..." line of the Death's coffer window</li>
 *     <li>chat messages that state the coffer balance</li>
 *     <li>a value the player enters manually</li>
 * </ul>
 * The balance is saved per account so it survives restarts.
 */
@Slf4j
@Singleton
public class CofferTracker
{
	private static final String KEY_BALANCE = "cofferBalance";
	private static final String KEY_UPDATED = "cofferUpdated";
	private static final String KEY_SOURCE = "cofferSource";

	private static final Pattern NUMBER = Pattern.compile("(\\d[\\d,]*)");
	private static final Pattern COFFER_LINE = Pattern.compile("coffer\\s*:\\s*(.+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern AMOUNT = Pattern.compile("(\\d+(?:\\.\\d+)?)\\s*([kmb])?");
	private static final Pattern BALANCE_WORDS = Pattern.compile("contains|balance|currently|you have|value of|remaining|left in", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final ConfigManager configManager;

	@Getter
	private long balance = -1;
	@Getter
	private Instant updatedAt;
	@Getter
	private String source;

	private Runnable onChange = () -> {};
	private String lastWindowText;

	@Inject
	CofferTracker(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
	}

	public void setOnChange(Runnable onChange)
	{
		this.onChange = onChange;
	}

	public boolean isKnown()
	{
		return balance >= 0;
	}

	/** Loads the saved balance for the current account. */
	public void load()
	{
		String b = configManager.getRSProfileConfiguration(AssetManagerConfig.GROUP, KEY_BALANCE);
		String u = configManager.getRSProfileConfiguration(AssetManagerConfig.GROUP, KEY_UPDATED);
		source = configManager.getRSProfileConfiguration(AssetManagerConfig.GROUP, KEY_SOURCE);
		try
		{
			balance = b == null ? -1 : Long.parseLong(b);
			updatedAt = u == null ? null : Instant.ofEpochMilli(Long.parseLong(u));
		}
		catch (NumberFormatException e)
		{
			balance = -1;
			updatedAt = null;
		}
		onChange.run();
	}

	public void setBalance(long value, String from)
	{
		log.debug("Coffer balance {} from {}", value, from);
		balance = value;
		updatedAt = Instant.now();
		source = from;
		configManager.setRSProfileConfiguration(AssetManagerConfig.GROUP, KEY_BALANCE, value);
		configManager.setRSProfileConfiguration(AssetManagerConfig.GROUP, KEY_UPDATED, updatedAt.toEpochMilli());
		configManager.setRSProfileConfiguration(AssetManagerConfig.GROUP, KEY_SOURCE, from);
		onChange.run();
	}

	@Subscribe
	public void onVarClientIntChanged(VarClientIntChanged event)
	{
		if (event.getIndex() != VarClientID.GRAVESTONE_TRANSMIT_COFFER)
		{
			return;
		}
		int value = client.getVarcIntValue(VarClientID.GRAVESTONE_TRANSMIT_COFFER);
		log.debug("GRAVESTONE_TRANSMIT_COFFER changed to {}", value);
		if (value >= 0)
		{
			setBalance(value, "game data");
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE
			&& event.getType() != ChatMessageType.MESBOX
			&& event.getType() != ChatMessageType.DIALOG)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		if (!message.toLowerCase().contains("coffer"))
		{
			return;
		}
		// Logged so the exact wording can be confirmed and the parsing tightened up.
		log.debug("Coffer chat message ({}): {}", event.getType(), message);
		Long value = chatBalance(message);
		if (value != null)
		{
			setBalance(value, "chat");
		}
	}

	/**
	 * Reads the balance from the sentence that states it. Messages can mention other amounts first, e.g.
	 * "Death charges you 500,000 x Coins. You have 8,784,598 x Coins left in Death's Coffer."
	 */
	static Long chatBalance(String message)
	{
		for (String sentence : message.split("(?<=[.!?])\\s+"))
		{
			if (BALANCE_WORDS.matcher(sentence).find())
			{
				Long value = firstNumber(sentence);
				if (value != null)
				{
					return value;
				}
			}
		}
		return null;
	}

	/** Reads the balance from the Death's coffer window if it's open. Call once per tick. */
	public void readCofferWindow()
	{
		if (client.getWidget(InterfaceID.DeathCoffer.UNIVERSE) == null)
		{
			lastWindowText = null;
			return;
		}
		List<String> texts = windowTexts();
		String joined = String.join(" | ", texts);
		if (joined.equals(lastWindowText))
		{
			return;
		}
		lastWindowText = joined;
		log.debug("Death's coffer window text: {}", joined);

		Long value = findBalance(texts);
		if (value != null && value != balance)
		{
			setBalance(value, "coffer window");
		}
	}

	/**
	 * Finds the "Coffer: ..." line in the coffer window, e.g. "Coffer: Empty" or "Coffer: 1,234,567 coins".
	 */
	static Long findBalance(List<String> texts)
	{
		for (String text : texts)
		{
			Matcher m = COFFER_LINE.matcher(text.trim());
			if (m.matches())
			{
				Long value = parseAmount(m.group(1));
				if (value != null)
				{
					return value;
				}
			}
		}
		return null;
	}

	/** Parses "Empty", "1,234,567", "1,234 coins", "1.5M" or "250K". */
	static Long parseAmount(String s)
	{
		String t = s.toLowerCase().replace(",", "").replace("coins", "").replace("gp", "").trim();
		if (t.equals("empty") || t.equals("none"))
		{
			return 0L;
		}
		Matcher m = AMOUNT.matcher(t);
		if (!m.matches())
		{
			return null;
		}
		double n = Double.parseDouble(m.group(1));
		String suffix = m.group(2);
		if (suffix != null)
		{
			n *= suffix.equals("k") ? 1e3 : suffix.equals("m") ? 1e6 : 1e9;
		}
		return Math.round(n);
	}

	/** All visible, non-empty texts in the coffer window. */
	private List<String> windowTexts()
	{
		List<String> texts = new ArrayList<>();
		collectTexts(client.getWidget(InterfaceID.DeathCoffer.UNIVERSE), texts);
		return texts;
	}

	private static void collectTexts(Widget w, List<String> out)
	{
		if (w == null || w.isHidden())
		{
			return;
		}
		if (w.getText() != null && !w.getText().isEmpty())
		{
			out.add(Text.removeTags(w.getText()));
		}
		for (Widget[] children : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (children != null)
			{
				for (Widget c : children)
				{
					collectTexts(c, out);
				}
			}
		}
	}

	static Long firstNumber(String text)
	{
		Matcher m = NUMBER.matcher(text);
		if (!m.find())
		{
			return null;
		}
		try
		{
			return Long.parseLong(m.group(1).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.assetmanager.coffer;

import com.assetmanager.value.ItemValues;
import lombok.Value;

/** A GE sell offer that would put more into a short Death's coffer if the items were sacrificed instead. */
@Value
public class GeCofferHint
{
	String name;
	/** How many to sacrifice: the offer's quantity, or fewer if that's enough to fill the coffer. */
	int units;
	int quantity;
	/** Coins the coffer gets for those units. */
	long cofferValue;
	/** Coins this offer gets for those units, after tax. */
	long saleValue;
	long shortfall;

	/**
	 * @param price     the offer's price per item
	 * @param shortfall how far the coffer is below its target; nothing is suggested once it's full, as coins from
	 *                  the sale are worth more than coins locked in the coffer
	 */
	public static GeCofferHint of(ItemValues v, long price, int quantity, long shortfall)
	{
		long cofferUnit = v.getCofferValue();
		long saleUnit = ItemValues.afterTax(price);
		if (cofferUnit <= 0 || quantity <= 0 || price <= 0 || shortfall <= 0 || cofferUnit <= saleUnit)
		{
			return null;
		}
		int units = (int) Math.min(quantity, (shortfall + cofferUnit - 1) / cofferUnit);
		return new GeCofferHint(v.getName(), units, quantity, units * cofferUnit, units * saleUnit, shortfall);
	}

	public long getExtra()
	{
		return cofferValue - saleValue;
	}
}

