import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

/**
 * On the GE's offer screen, while the coffer is short of its target: says when sacrificing the item being sold would
 * add more to Death's coffer than the offer gets. Only informs; the offer isn't blocked.
 */
@Singleton
public class GeCofferOverlay extends Overlay
{
	private static final int GE_SELL = 1;
	private static final Pattern COINS = Pattern.compile("^([\\d,]+) coins?$");
	private static final int PAD = 5;
	private static final Color TITLE = new Color(0x4CAF50);
	private static final Color TEXT = new Color(0xEEEEEE);
	private static final Color MUTED = new Color(0x9E9E9E);

	private final Client client;
	private final ItemValuator itemValuator;
	private final AssetManagerConfig config;

	/** How far the coffer is below its target; 0 when full or the account can't use it. */
	@Setter
	private volatile long shortfall;
	@Setter
	private volatile boolean cofferKnown;

	@Inject
	GeCofferOverlay(Client client, ItemValuator itemValuator, AssetManagerConfig config)
	{
		this.client = client;
		this.itemValuator = itemValuator;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** The hint for the sell offer being set up, or null. */
	GeCofferHint hint()
	{
		if (!config.geCofferHint() || shortfall <= 0)
		{
			return null;
		}
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (setup == null || setup.isHidden() || client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) != GE_SELL)
		{
			return null;
		}
		int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (itemId <= 0)
		{
			return null;
		}
		int quantity = client.getVarbitValue(VarbitID.GE_NEWOFFER_QUANTITY);
		List<Long> amounts = new ArrayList<>();
		coinAmounts(setup, amounts);
		long price = offerPrice(amounts, quantity);
		return price <= 0 ? null : GeCofferHint.of(itemValuator.get(itemId), price, quantity, shortfall);
	}

	/**
	 * The price each, from the "N coins" amounts on the offer screen. RuneLite has no variable for it since GE prices
	 * went past max cash, and the screen shows both the price each and the total, so it's the amount that times the
	 * quantity is also shown. 0 if that can't be told.
	 */
	static long offerPrice(List<Long> amounts, int quantity)
	{
		if (quantity <= 0)
		{
			return 0;
		}
		long best = 0;
		for (long a : amounts)
		{
			if (a > 0 && (best == 0 || a < best) && (quantity == 1 || amounts.contains(a * quantity)))
			{
				best = a;
			}
		}
		return best;
	}

	/** Every "N coins" amount shown under {@code w}. */
	private static void coinAmounts(Widget w, List<Long> amounts)
	{
		if (w == null || w.isHidden())
		{
			return;
		}
		Matcher m = COINS.matcher(Text.removeTags(w.getText() == null ? "" : w.getText()));
		if (m.find())
		{
			try
			{
				amounts.add(Long.parseLong(m.group(1).replace(",", "")));
			}
			catch (NumberFormatException ignored)
			{
			}
		}
		for (Widget[] children : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (children != null)
			{
				for (Widget c : children)
				{
					coinAmounts(c, amounts);
				}
			}
		}
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		GeCofferHint h = hint();
		if (h == null)
		{
			return null;
		}
		List<String> lines = new ArrayList<>();
		List<Color> colors = new ArrayList<>();
		add(lines, colors, "Death's coffer pays more for these", TITLE);
		add(lines, colors, "Sacrificing " + (h.getUnits() == h.getQuantity() ? "them" : QuantityFormatter.formatNumber(h.getUnits()))
			+ " adds " + gp(h.getCofferValue()) + " to your coffer;", TEXT);
		add(lines, colors, "this offer gets " + gp(h.getSaleValue()) + " for "
			+ (h.getUnits() == h.getQuantity() ? "them" : "those") + " after tax (" + gp(h.getExtra()) + " less).", TEXT);
		add(lines, colors, cofferKnown
			? "Your coffer is " + gp(h.getShortfall()) + " short of your target."
			: "Talk to Death to check your coffer's balance.", MUTED);

		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int width = 0;
		for (String l : lines)
		{
			width = Math.max(width, fm.stringWidth(l));
		}
		int lineHeight = fm.getHeight();
		Dimension box = new Dimension(width + PAD * 2, lineHeight * lines.size() + PAD * 2);

		Rectangle ge = outermost(client.getWidget(InterfaceID.GeOffers.SETUP)).getBounds();
		int x = ge.x + (ge.width - box.width) / 2;
		// Above the GE window if there's room, otherwise below it
		int y = ge.y - box.height - 4 >= 0 ? ge.y - box.height - 4 : ge.y + ge.height + 4;
		x = Math.max(0, Math.min(x, client.getCanvasWidth() - box.width));
		y = Math.max(0, Math.min(y, client.getCanvasHeight() - box.height));

		g.setColor(PriceTooltip.SOLID_BACKGROUND);
		g.fillRect(x, y, box.width, box.height);
		g.setColor(TITLE);
		g.setStroke(new BasicStroke(1));
		g.drawRect(x, y, box.width - 1, box.height - 1);
		int baseline = y + PAD + fm.getAscent();
		for (int i = 0; i < lines.size(); i++)
		{
			g.setColor(Color.BLACK);
			g.drawString(lines.get(i), x + PAD + 1, baseline + 1);
			g.setColor(colors.get(i));
			g.drawString(lines.get(i), x + PAD, baseline);
			baseline += lineHeight;
		}
		return null;
	}

	private static void add(List<String> lines, List<Color> colors, String line, Color color)
	{
		lines.add(line);
		colors.add(color);
	}

	private static String gp(long coins)
	{
		return QuantityFormatter.quantityToStackSize(coins) + " gp";
	}

	private static Widget outermost(Widget w)
	{
		while (w.getParent() != null)
		{
			w = w.getParent();
		}
		return w;
	}
}

package com.assetmanager.death;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * Works out which carried items would be kept on death and what reclaiming the rest costs.
 * Pure logic with no client access so it can be unit tested.
 */
public final class DeathCostCalculator
{
	static final long GRAVESTONE_FEE_CAP = 500_000;
	static final long FREE_RECLAIM_THRESHOLD = 100_000;

	private DeathCostCalculator()
	{
	}

	/**
	 * @param items        everything worn and in the inventory
	 * @param keepCount    items kept on death (3 normally, +1 with Protect Item, 0 when skulled)
	 * @param ironDiscount whether the account gets the ironman 50% fee discount
	 * @param scenario     where the death happens
	 */
	public static DeathCostEstimate estimate(List<RiskItem> items, int keepCount, boolean ironDiscount, DeathScenario scenario)
	{
		int[] keptQty = pickKept(items, keepCount);

		List<RiskItem> kept = new ArrayList<>();
		List<RiskItem> lost = new ArrayList<>();
		for (int i = 0; i < items.size(); i++)
		{
			RiskItem item = items.get(i);
			if (keptQty[i] > 0)
			{
				kept.add(withQuantity(item, keptQty[i]));
			}
			int remaining = item.getQuantity() - keptQty[i];
			if (remaining > 0)
			{
				lost.add(withQuantity(item, remaining));
			}
		}

		List<Long> feeItemValues = feeItemValues(lost);
		long valueAtRisk = feeItemValues.stream().mapToLong(Long::longValue).sum();
		long gravestone = gravestoneFee(feeItemValues, ironDiscount);
		long office = deathsOfficeFee(feeItemValues, ironDiscount);

		long scenarioFee;
		switch (scenario.getFeeType())
		{
			case GRAVESTONE:
				scenarioFee = gravestone;
				break;
			case DEATHS_OFFICE:
				scenarioFee = office;
				break;
			case TOA:
				// The wiki only says the fee varies with GE value up to 500k; approximate with the
				// Death's Office rate, capped.
				scenarioFee = Math.min(deathsOfficeFee(feeItemValues, false), scenario.getFee());
				break;
			case FLAT:
			default:
				scenarioFee = lost.isEmpty() ? 0 : scenario.getFee();
				break;
		}

		return new DeathCostEstimate(kept, lost, valueAtRisk, gravestone, office, scenario, scenarioFee, ironDiscount, keepCount);
	}

	/** Returns how many units of each item are kept, choosing the most valuable units first. */
	private static int[] pickKept(List<RiskItem> items, int keepCount)
	{
		int[] keptQty = new int[items.size()];
		if (keepCount <= 0)
		{
			return keptQty;
		}

		// Each unit of a stack counts separately, but no item can contribute more than keepCount units.
		List<long[]> units = new ArrayList<>();
		for (int i = 0; i < items.size(); i++)
		{
			RiskItem item = items.get(i);
			int n = Math.min(item.getQuantity(), keepCount);
			for (int u = 0; u < n; u++)
			{
				units.add(new long[]{i, item.getProtectionValue()});
			}
		}
		units.sort(Comparator.comparingLong((long[] u) -> u[1]).reversed());
		for (int k = 0; k < Math.min(keepCount, units.size()); k++)
		{
			keptQty[(int) units.get(k)[0]]++;
		}
		return keptQty;
	}

	/** Fees are charged per item: a whole stack counts as one item, each non-stacking item separately. */
	private static List<Long> feeItemValues(List<RiskItem> lost)
	{
		List<Long> values = new ArrayList<>();
		for (RiskItem item : lost)
		{
			if (item.isStackable())
			{
				values.add(item.getFeeValue() * item.getQuantity());
			}
			else
			{
				values.addAll(Collections.nCopies(item.getQuantity(), item.getFeeValue()));
			}
		}
		return values;
	}

	static long gravestoneFee(List<Long> itemValues, boolean ironDiscount)
	{
		long total = 0;
		for (long v : itemValues)
		{
			total += gravestoneItemFee(v);
		}
		total = Math.min(total, GRAVESTONE_FEE_CAP);
		return ironDiscount ? total / 2 : total;
	}

	static long gravestoneItemFee(long value)
	{
		if (value >= 10_000_000)
		{
			return 100_000;
		}
		if (value >= 1_000_000)
		{
			return 10_000;
		}
		if (value >= FREE_RECLAIM_THRESHOLD)
		{
			return 1_000;
		}
		return 0;
	}

	static long deathsOfficeFee(List<Long> itemValues, boolean ironDiscount)
	{
		long total = 0;
		for (long v : itemValues)
		{
			if (v >= FREE_RECLAIM_THRESHOLD)
			{
				// 5%, or 2.5% for ironmen
				total += ironDiscount ? v * 25 / 1000 : v * 5 / 100;
			}
		}
		return total;
	}

	private static RiskItem withQuantity(RiskItem item, int quantity)
	{
		return new RiskItem(item.getItemId(), item.getName(), quantity, item.isStackable(),
			item.getProtectionValue(), item.getFeeValue());
	}
}

