package com.assetmanager.dest;

import com.assetmanager.CofferSuggestionMode;
import com.assetmanager.Suggestions;
import com.assetmanager.coffer.CofferCandidate;
import com.assetmanager.coffer.CofferPlan;
import com.assetmanager.keep.Holdings;
import com.assetmanager.shop.Shop;
import com.assetmanager.shop.ShopOffer;
import com.assetmanager.shop.ShopTrip;
import com.assetmanager.value.SaleSuggestion;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.Function;
import java.util.function.IntToLongFunction;
import java.util.function.ToLongFunction;
import java.util.stream.Collectors;
import lombok.Value;

/**
 * Sorts Asset Manager's suggestions into destinations: Death's coffer, high alching, the GE and each shop, with
 * every list ordered from most to least valuable.
 */
@Value
public class Destinations
{
	public static final Destinations NONE = new Destinations(Suggestions.NONE, Collections.emptyList());

	/** Which item goes where, for icons. */
	Suggestions suggestions;
	/** All, coffer, alch, GE, then shops (most gained first), then kept. */
	List<Destination> list;

	public Destination get(Destination.Kind kind)
	{
		return list.stream().filter(d -> d.getKind() == kind).findFirst().orElse(null);
	}

	public List<Destination> getShops()
	{
		return list.stream().filter(d -> d.getKind() == Destination.Kind.SHOP).collect(Collectors.toList());
	}

	/**
	 * @param plan  the coffer plan, or null if there is none
	 * @param sales alch, shop and GE suggestions
	 * @param trips       shop trips, by shop name
	 * @param kept        value of each kept item in the bank, by id
	 * @param outsideBank where items are that are only spare outside the bank
	 */
	public static Destinations build(CofferPlan plan, CofferSuggestionMode cofferMode, List<SaleSuggestion> sales,
		Map<String, ShopTrip> trips, Map<Integer, Long> kept, Map<Integer, Holdings.Place> outsideBank)
	{
		return build(plan, cofferMode, sales, trips, kept, outsideBank, GeOrder.VALUE, id -> -1);
	}

	/**
	 * @param geOrder        how to order the GE items
	 * @param tradesPerHour  about how many of an item trade on the GE an hour, or -1 if unknown; for
	 *                       {@link GeOrder#QUICKEST}
	 */
	public static Destinations build(CofferPlan plan, CofferSuggestionMode cofferMode, List<SaleSuggestion> sales,
		Map<String, ShopTrip> trips, Map<Integer, Long> kept, Map<Integer, Holdings.Place> outsideBank,
		GeOrder geOrder, IntToLongFunction tradesPerHour)
	{
		// Coffer: the planned top-up, or everything worth sacrificing
		Map<Integer, long[]> coffer = new LinkedHashMap<>();
		if (plan != null)
		{
			if (cofferMode == CofferSuggestionMode.ALL)
			{
				for (CofferCandidate c : plan.getCandidates())
				{
					coffer.put(c.getValues().getItemId(), new long[]{c.getCofferTotal(), (c.getCofferUnit() - c.getAlternativeUnit()) * c.getQuantity()});
				}
			}
			else
			{
				for (CofferPlan.Step s : plan.getSteps())
				{
					CofferCandidate c = s.getCandidate();
					coffer.put(c.getValues().getItemId(), new long[]{s.getCofferValue(), (c.getCofferUnit() - c.getAlternativeUnit()) * s.getQuantity()});
				}
			}
		}
		List<Integer> cofferIds = sortedIds(coffer, v -> v[0]);

		List<SaleSuggestion> byValue = new ArrayList<>(sales);
		byValue.sort(Comparator.comparingLong(SaleSuggestion::getTotal).reversed());
		Suggestions s = new Suggestions(cofferIds, ids(byValue, SaleSuggestion.Type.ALCH), ids(byValue, SaleSuggestion.Type.SHOP),
			ids(byValue, SaleSuggestion.Type.GE));

		List<Destination> list = new ArrayList<>();
		long cofferValue = coffer.values().stream().mapToLong(v -> v[0]).sum();
		long cofferGain = coffer.values().stream().mapToLong(v -> Math.max(0, v[1])).sum();
		Function<List<Integer>, Map<Holdings.Place, Integer>> elsewhere = ids ->
		{
			Map<Holdings.Place, Integer> counts = new EnumMap<>(Holdings.Place.class);
			ids.forEach(id -> Optional.ofNullable(outsideBank.get(id)).ifPresent(p -> counts.merge(p, 1, Integer::sum)));
			return counts;
		};
		list.add(simple(Destination.Kind.COFFER, "Death's coffer", new ArrayList<>(s.getCoffer()), cofferValue, cofferGain, elsewhere));
		list.add(fromSales(Destination.Kind.ALCH, "High alch", byValue, SaleSuggestion.Type.ALCH, s.getAlch(), elsewhere));
		List<SaleSuggestion> geSales = byValue;
		if (geOrder == GeOrder.QUICKEST)
		{
			geSales = new ArrayList<>(byValue);
			geSales.sort(quickestFirst(tradesPerHour));
		}
		list.add(fromSales(Destination.Kind.GE, "Grand Exchange", geSales, SaleSuggestion.Type.GE, s.getGe(), elsewhere));

		// One destination per shop, or group of shops paying the same, the most gained first
		Map<String, List<SaleSuggestion>> byShop = new LinkedHashMap<>();
		for (SaleSuggestion x : byValue)
		{
			if (x.getType() == SaleSuggestion.Type.SHOP && s.getShop().contains(x.getValues().getItemId()))
			{
				byShop.computeIfAbsent(x.getShopOffer().getShop().getGroup(), k -> new ArrayList<>()).add(x);
			}
		}
		List<Destination> shops = new ArrayList<>();
		for (List<SaleSuggestion> group : byShop.values())
		{
			Shop shop = group.get(0).getShopOffer().getShop();
			List<Integer> shopIds = ids(group, SaleSuggestion.Type.SHOP);
			ShopTrip trip = trips.get(shop.getGroup());
			shops.add(new Destination(Destination.Kind.SHOP, shop.getGroup(), shopIds,
				group.stream().mapToLong(SaleSuggestion::getTotal).sum(),
				trip != null ? trip.getGain() : group.stream().mapToLong(SaleSuggestion::getGain).sum(),
				shop,
				group.stream().mapToInt(x -> x.getShopOffer().getEqualShops()).max().orElse(0),
				trip != null ? trip.getWorlds() : 1,
				group.stream().map(SaleSuggestion::getShopOffer).anyMatch(ShopOffer::isUsesKaramjaGloves),
				group.stream().map(SaleSuggestion::getShopOffer).anyMatch(ShopOffer::isUsesCharos),
				elsewhere.apply(shopIds)));
		}
		shops.sort(Comparator.comparingLong(Destination::getGain).reversed());
		list.addAll(shops);

		// Everything, in the same order as the rows
		Set<Integer> all = new LinkedHashSet<>();
		long allValue = 0;
		long allGain = 0;
		for (Destination d : list)
		{
			all.addAll(d.getItemIds());
			allValue += d.getValue();
			allGain += d.getGain();
		}
		list.add(0, simple(Destination.Kind.ALL, "Everything", new ArrayList<>(all), allValue, allGain, elsewhere));

		list.add(simple(Destination.Kind.KEPT, "Kept", sortedIds(kept, v -> v), kept.values().stream().mapToLong(Long::longValue).sum(), 0, elsewhere));
		return new Destinations(s, Collections.unmodifiableList(list));
	}

	private static Destination simple(Destination.Kind kind, String name, List<Integer> ids, long value, long gain,
		Function<List<Integer>, Map<Holdings.Place, Integer>> elsewhere)
	{
		return new Destination(kind, name, ids, value, gain, null, 0, 1, false, false, elsewhere.apply(ids));
	}

	private static Destination fromSales(Destination.Kind kind, String name, List<SaleSuggestion> byValue, SaleSuggestion.Type type,
		Set<Integer> ids, Function<List<Integer>, Map<Holdings.Place, Integer>> elsewhere)
	{
		List<SaleSuggestion> here = byValue.stream()
			.filter(x -> x.getType() == type && ids.contains(x.getValues().getItemId()))
			.collect(Collectors.toList());
		return simple(kind, name, here.stream().map(x -> x.getValues().getItemId()).collect(Collectors.toList()),
			here.stream().mapToLong(SaleSuggestion::getTotal).sum(),
			kind == Destination.Kind.GE ? 0 : here.stream().mapToLong(SaleSuggestion::getGain).sum(), elsewhere);
	}

	/**
	 * The stacks that sell soonest first: the fewest hours of normal GE trading to sell the whole quantity. Items that
	 * didn't trade in the last day come after them, then items with unknown volumes; each most valuable first. The
	 * sort is stable, so ties keep their value order.
	 */
	static Comparator<SaleSuggestion> quickestFirst(IntToLongFunction tradesPerHour)
	{
		return Comparator.comparingDouble(x ->
		{
			long perHour = tradesPerHour.applyAsLong(x.getValues().getItemId());
			return perHour < 0 ? Double.MAX_VALUE : perHour == 0 ? Double.MAX_VALUE / 2 : (double) x.getQuantity() / perHour;
		});
	}

	private static List<Integer> ids(List<SaleSuggestion> sales, SaleSuggestion.Type type)
	{
		return sales.stream().filter(x -> x.getType() == type).map(x -> x.getValues().getItemId()).collect(Collectors.toList());
	}

	private static <V> List<Integer> sortedIds(Map<Integer, V> values, ToLongFunction<V> value)
	{
		return values.entrySet().stream()
			.sorted(Comparator.comparingLong((Map.Entry<Integer, V> e) -> value.applyAsLong(e.getValue())).reversed())
			.map(Map.Entry::getKey)
			.collect(Collectors.toList());
	}
}

package com.assetmanager.dest;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** How the Grand Exchange bank view orders its items; picked on the GE row of the side panel. */
@Getter
@RequiredArgsConstructor
public enum GeOrder
{
	/** Most coins first. */
	VALUE("By value", "Most valuable first"),
	/**
	 * The stacks the GE takes off the player's hands soonest first, to free bank spaces: the fewest hours of normal
	 * trading needed to sell the whole spare quantity. Needs live GE prices for trade volumes.
	 */
	QUICKEST("Quickest", "Quickest to sell first");

	/** Short, for the button. */
	private final String label;
	private final String description;

	@Override
	public String toString()
	{
		return description;
	}
}

package com.assetmanager.flip;

import com.assetmanager.shop.Shop;
import com.assetmanager.shop.ShopPerks;
import com.assetmanager.shop.Unlocks;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import lombok.Value;

/**
 * The best shops to buy from, for Death's coffer, to resell on the GE or to alch, out of the shops the player has the
 * requirements for. Each go is one visit: buying everything worth it, a few on each world while the price is low,
 * until the shop runs out, the price rises too far, or the inventory or coins run out.
 */
public final class BestBuys
{
	/** Unstackable items bought per visit: a full inventory. */
	static final int INVENTORY_SIZE = 28;
	/** Most bought per visit of a stackable item a shop never runs out of; it has to stop somewhere. */
	static final int MAX_STACK = 10_000;
	/** Most worlds tried when looking for the quickest go; past this, hopping takes longer than it's worth. */
	private static final long MAX_FAST_WORLDS = 1024;

	private BestBuys()
	{
	}

	public enum Kind
	{
		/** Sacrificed to Death's coffer at 105% of the guide price. */
		COFFER,
		/** Sold on the Grand Exchange, after tax. */
		GE,
		/** Cast High Level Alchemy on, less the nature rune. */
		ALCH
	}

	/** What an item is worth, by id. Gathered on the client thread, so planning can run elsewhere. */
	public interface Prices
	{
		/** Coins added to the coffer per item, or 0 if it isn't accepted. */
		long coffer(int itemId);

		/** Coins from selling one on the GE after tax, or 0 if it can't be. */
		long ge(int itemId);

		/** About how many the GE trades in the time the player will wait, or Long.MAX_VALUE if unknown (live prices off). */
		long geVolume(int itemId);

		/** Coins from alching one, less the nature rune, or 0 if it isn't worth alching. */
		default long alch(int itemId)
		{
			return 0;
		}

		/** How many alchs to plan for. */
		default long alchCasts()
		{
			return Long.MAX_VALUE;
		}

		/** The item's store value, which shop prices are a % of. */
		int storeValue(int itemId);

		boolean stackable(int itemId);

		/** Whether it's a members item, which can't be used on a free-to-play world. */
		default boolean members(int itemId)
		{
			return false;
		}

		/** Hours the player will wait for GE offers to fill. */
		default double geHours()
		{
			return 1;
		}
	}

	@Value
	public static class Deal
	{
		Kind kind;
		Shop shop;
		/** The item's name as the shop data has it (lowercase). */
		String item;
		int itemId;
		ShopFlip flip;
		/** Requirements the plugin couldn't check, which the player should make sure of. */
		List<String> unchecked;
		/** For GE deals, about how many trade in the time the player will wait; Long.MAX_VALUE if unknown or not for the GE. */
		long tradesPerHour;

		/** What one visit gains: every item bought, as the price rises. */
		public long getGain()
		{
			return flip.getProfit();
		}

		/** What the first one bought gains: the coffer value or GE sale, less the shop's price at full stock. */
		public long getProfitEach()
		{
			return flip.getGeUnit() - flip.getFirstPrice();
		}

		/** Profit on the first one bought, as a percentage of what it costs. */
		public double getPercent()
		{
			return flip.getFirstPrice() <= 0 ? 0 : getProfitEach() * 100.0 / flip.getFirstPrice();
		}

		/** Whether the shop's price rises with each one bought. */
		public boolean isPriceRises()
		{
			return flip.getLastPrice() > flip.getFirstPrice();
		}
	}

	/**
	 * A go at each shop worth visiting: everything worth buying there, bought together so every hop and trip serves
	 * them all. Each shop's go shares the coins, the inventory and (for alching) an hour of casts between its items.
	 * Shops where the go would be just the same are merged into the closest. Gos the player can't afford even one item
	 * of are left out.
	 *
	 * @param coins     coins to spend per go
	 * @param maxWorlds the most worlds to hop, or ShopCatalog.NO_WORLD_LIMIT
	 * @param fastest   hop only as many worlds as makes the most an hour, rather than as many as makes the most
	 * @param maxItems  the most different items to sell on the GE in one go (it has 8 offer slots)
	 */
	public static List<FlipRun> runs(Kind kind, List<Shop> shops, Prices prices, Unlocks unlocks, ShopPerks perks,
		long coins, int maxWorlds, boolean fastest, int maxItems)
	{
		List<FlipRun> out = new ArrayList<>();
		for (Shop shop : shops)
		{
			if (perks.isAvoidWilderness() && shop.isWilderness() || shop.getSellMultiplier() <= 0 && !hasOwnRates(shop))
			{
				continue;
			}
			List<Leg> legs = new ArrayList<>();
			shop.getItems().forEach((name, item) ->
			{
				Leg leg = leg(kind, shop, name, item, prices, unlocks, perks);
				if (leg != null && leg.getUnit() - leg.price(0) >= 1 && leg.price(0) <= coins)
				{
					legs.add(leg);
				}
			});
			if (!legs.isEmpty())
			{
				FlipRun run = bestRun(kind, shop, legs, prices, coins, maxWorlds, fastest, kind == Kind.GE ? maxItems : Integer.MAX_VALUE);
				if (run != null)
				{
					out.add(run);
				}
			}
		}
		return Flips.mergeEqual(out, perks.getLocation());
	}

	private static boolean hasOwnRates(Shop shop)
	{
		return shop.getItems().values().stream().anyMatch(i -> i.getSm() != null || i.getSp() != null);
	}

	/** The go at a shop: on as many worlds as allowed, or, if {@code fastest}, as many as make the most an hour. */
	static FlipRun bestRun(Kind kind, Shop shop, List<Leg> legs, Prices prices, long coins, int maxWorlds, boolean fastest,
		int maxItems)
	{
		// Buying by talking is sometimes one per conversation, so hopping isn't suggested; a shop that never runs out
		// has nothing to hop for
		boolean hops = shop.getTalk() == null && legs.stream().anyMatch(l -> l.getNormalStock() >= 0);
		long allowed = !hops ? 1 : maxWorlds <= 0 ? Long.MAX_VALUE : maxWorlds;
		if (!fastest || allowed == 1)
		{
			return plan(kind, shop, legs, prices, coins, allowed, maxItems);
		}
		FlipRun best = null;
		long bestWorlds = 1;
		long top = Math.min(allowed, MAX_FAST_WORLDS);
		for (long w = 1; ; w = Math.min(top, w < 4 ? w + 1 : w * 3 / 2))
		{
			FlipRun run = plan(kind, shop, legs, prices, coins, w, maxItems);
			if (run != null && (best == null || run.getGpPerHour() > best.getGpPerHour()))
			{
				best = run;
				bestWorlds = w;
			}
			if (w == top)
			{
				break;
			}
		}
		if (best == null || bestWorlds >= allowed)
		{
			return best;
		}
		// Stopped short of the player's limit because more hopping would make less an hour
		List<Flip> flips = new ArrayList<>();
		for (Flip f : best.getFlips())
		{
			flips.add(f.getLimit() == ShopFlip.Limit.WORLDS || f.getLimit() == ShopFlip.Limit.STOCK && bestWorlds > 1
				? f.withLimit(ShopFlip.Limit.QUICKER) : f);
		}
		return best.withFlips(flips);
	}

	/** One item's progress while planning a go. */
	private static class Buying
	{
		final Leg leg;
		long bought;
		long cost;
		long first;
		long last;
		long nextPrice;
		ShopFlip.Limit limit;

		Buying(Leg leg)
		{
			this.leg = leg;
		}

		long nextProfit()
		{
			return leg.getUnit() - nextPrice;
		}

		/** Works out the next one's price; false, with the reason, if no more can be bought. */
		boolean advance(long worlds)
		{
			long depth = bought / worlds;
			if (leg.getNormalStock() >= 0 && depth >= leg.getNormalStock())
			{
				// Every world's stock is bought: more worlds would mean more
				limit = worlds == 1 || worlds == Long.MAX_VALUE ? ShopFlip.Limit.STOCK : ShopFlip.Limit.WORLDS;
				return false;
			}
			if (leg.isStackable() && bought >= MAX_STACK)
			{
				limit = ShopFlip.Limit.SPACE;
				return false;
			}
			if (bought >= leg.getCap())
			{
				limit = leg.getCapLimit();
				return false;
			}
			nextPrice = leg.price(depth);
			return true;
		}
	}

	/**
	 * Buying at a shop over {@code worlds} worlds (Long.MAX_VALUE for as many as it takes), a few of each item on each
	 * world, round the worlds in turn. Each step buys whichever item's next one makes the most, until none makes
	 * anything or the coins, inventory or alchs run out, buying no more than {@code maxItems} different items. Null if
	 * nothing's bought.
	 */
	static FlipRun plan(Kind kind, Shop shop, List<Leg> legs, Prices prices, long coins, long worlds, int maxItems)
	{
		PriorityQueue<Buying> next = new PriorityQueue<>(Comparator.comparingLong(Buying::nextProfit).reversed()
			.thenComparing(b -> b.leg.getName()));
		List<Buying> all = new ArrayList<>();
		for (Leg leg : legs)
		{
			Buying b = new Buying(leg);
			all.add(b);
			if (b.advance(worlds))
			{
				next.add(b);
			}
		}
		int slots = INVENTORY_SIZE;
		long left = coins;
		long casts = kind == Kind.ALCH ? prices.alchCasts() : Long.MAX_VALUE;
		long total = 0;
		int items = 0;
		ShopFlip.Limit stopped = ShopFlip.Limit.PRICE;
		while (!next.isEmpty())
		{
			if (total >= casts)
			{
				stopped = ShopFlip.Limit.CASTS;
				break;
			}
			Buying b = next.peek();
			if (b.nextProfit() < 1)
			{
				break;
			}
			next.poll();
			long price = b.nextPrice;
			boolean needsSlot = !b.leg.isStackable() || b.bought == 0;
			if (needsSlot && slots <= 0)
			{
				b.limit = ShopFlip.Limit.SPACE;
				continue;
			}
			if (price > left)
			{
				b.limit = ShopFlip.Limit.COINS;
				continue;
			}
			if (b.bought == 0 && items >= maxItems)
			{
				b.limit = ShopFlip.Limit.GE_SLOTS;
				continue;
			}
			if (b.bought == 0)
			{
				items++;
			}
			if (needsSlot)
			{
				slots--;
			}
			left -= price;
			b.cost += price;
			if (b.bought == 0)
			{
				b.first = price;
			}
			b.last = Math.max(b.last, price);
			b.bought++;
			total++;
			if (b.advance(worlds))
			{
				next.add(b);
			}
		}
		for (Buying b : next)
		{
			b.limit = stopped;
		}

		List<Flip> flips = new ArrayList<>();
		int used = 1;
		long talks = 0;
		long clicks = 0;
		for (Buying b : all)
		{
			if (b.bought == 0)
			{
				continue;
			}
			Leg leg = b.leg;
			int bought = (int) b.bought;
			int onWorlds = (int) Math.min(worlds, b.bought);
			used = Math.max(used, onWorlds);
			talks += (b.bought + leg.getPerTalk() - 1) / leg.getPerTalk();
			clicks += FlipTime.clicks(b.bought, onWorlds);
			ShopFlip f = new ShopFlip(bought, b.cost, leg.getUnit() * bought, b.first, b.last, leg.getUnit(), b.limit, onWorlds);
			flips.add(Flips.fromShop(new Deal(kind, shop, leg.getName(), leg.getItemId(), f, leg.getUnchecked(), leg.getVolume())));
		}
		if (flips.isEmpty())
		{
			return null;
		}
		flips.sort(Comparator.comparingLong(Flip::getProfit).reversed().thenComparing(Flip::getItem));
		double active = FlipTime.TRIP_SECONDS + (shop.getTalk() != null ? talks * FlipTime.TALK_SECONDS
			: (used - 1) * FlipTime.HOP_SECONDS + clicks * FlipTime.CLICK_SECONDS);
		if (kind == Kind.ALCH)
		{
			active += total * FlipTime.ALCH_SECONDS;
		}
		double wait = kind == Kind.GE ? prices.geHours() * 3600 : 0;
		Flip.Dest dest = flips.get(0).getDest();
		return new FlipRun(Flip.Source.SHOP, dest, shop, flips, used, Math.max(active, wait), 0);
	}

	/** An item a shop sells and what it's worth where it's going, ready to plan buying it. */
	@Value
	static class Leg
	{
		String name;
		int itemId;
		/** Store value, or what gives the shop's set price. */
		int value;
		/** What the shop charges at normal stock, in tenths of a percent. */
		int rate;
		int delta;
		/** The shop's normal stock, or -1 if it never runs out. */
		int normalStock;
		/** What one is worth where it's going. */
		long unit;
		boolean stackable;
		/** Most to buy: what the GE trades, alchs in an hour, or Long.MAX_VALUE. */
		long cap;
		ShopFlip.Limit capLimit;
		/** For the GE, about how many trade in the time the player will wait; Long.MAX_VALUE otherwise. */
		long volume;
		/** Bought per conversation, from a trader bought from by talking. */
		int perTalk;
		List<String> unchecked;

		/** What the next one costs once {@code depth} have been bought on a world. */
		long price(long depth)
		{
			return ShopFlipAdvisor.price(value, normalStock < 0 ? rate : (int) Math.min(Integer.MAX_VALUE, rate + delta * depth));
		}
	}

	/** An item to plan buying from a shop, or null if it isn't worth anything where it's going or the player can't. */
	static Leg leg(Kind kind, Shop shop, String name, Shop.Item item, Prices prices, Unlocks unlocks, ShopPerks perks)
	{
		Integer id = item.getId();
		// Only items the shop keeps in stock can be bought
		if (id == null || item.isNs() || item.getS() == 0)
		{
			return null;
		}
		if (!unlocks.isMembers() && prices.members(id))
		{
			return null;
		}
		long unit = kind == Kind.COFFER ? prices.coffer(id) : kind == Kind.ALCH ? prices.alch(id) : prices.ge(id);
		if (unit <= 0)
		{
			return null;
		}
		boolean gloves = shop.getGlovesTier() != null && perks.getGlovesTier() >= shop.getGlovesTier() && item.getGs() != null;
		int rate = gloves ? item.getGs() : item.getSm() != null ? item.getSm() : shop.getSellMultiplier();
		if (rate <= 0)
		{
			return null;
		}
		int delta = item.getD() != null ? item.getD() : shop.getDelta();
		// A set price is turned into the value that gives it at the shop's rate, so it rises with stock like any other
		int value = item.getSp() != null && !gloves ? (int) ((item.getSp() * 1000L + rate - 1) / rate) : prices.storeValue(id);
		if (value <= 0)
		{
			return null;
		}
		Unlocks.Missing missing = unlocks.missing(shop, item);
		if (!missing.isMet())
		{
			return null;
		}
		long volume = kind == Kind.GE ? prices.geVolume(id) : Long.MAX_VALUE;
		long cap;
		ShopFlip.Limit capLimit;
		switch (kind)
		{
			case ALCH:
				cap = prices.alchCasts();
				capLimit = ShopFlip.Limit.CASTS;
				break;
			case GE:
				cap = volume;
				capLimit = ShopFlip.Limit.VOLUME;
				break;
			default:
				cap = Long.MAX_VALUE;
				capLimit = ShopFlip.Limit.VOLUME;
		}
		int[] bundle = item.getB();
		int perTalk = bundle != null && bundle.length == 2 && bundle[0] > 0 ? bundle[0] : 1;
		return new Leg(name, id, value, rate, delta, item.getS() < 0 ? -1 : item.getS(), unit, prices.stackable(id), cap, capLimit,
			volume, perTalk, missing.getUnchecked().isEmpty() ? Collections.emptyList() : new ArrayList<>(missing.getUnchecked()));
	}

	/** One visit's worth of an item from a shop, or null if it isn't worth buying or the player can't. */
	static Deal deal(Kind kind, Shop shop, String name, Shop.Item item, Prices prices, Unlocks unlocks, ShopPerks perks,
		long coins)
	{
		return deal(kind, shop, name, item, prices, unlocks, perks, coins, 1);
	}

	/** As above, hopping up to {@code maxWorlds} worlds (0 for no limit). */
	static Deal deal(Kind kind, Shop shop, String name, Shop.Item item, Prices prices, Unlocks unlocks, ShopPerks perks,
		long coins, int maxWorlds)
	{
		Leg leg = leg(kind, shop, name, item, prices, unlocks, perks);
		if (leg == null)
		{
			return null;
		}
		int space = leg.isStackable() ? MAX_STACK : INVENTORY_SIZE;
		// Bought by talking, sometimes one per conversation: hopping isn't suggested there
		int worlds = shop.getTalk() != null ? 1 : maxWorlds;
		ShopFlip flip = ShopFlipAdvisor.planHopping(leg.getValue(), leg.getNormalStock(), leg.getRate(), leg.getDelta(),
			leg.getUnit(), 1, space, coins, leg.getCap(), leg.getCapLimit(), worlds);
		if (flip == null)
		{
			return null;
		}
		return new Deal(kind, shop, name, leg.getItemId(), flip, leg.getUnchecked(), leg.getVolume());
	}
}

package com.assetmanager.flip;

import com.assetmanager.shop.Shop;
import com.assetmanager.shop.ShopOffer;
import java.util.List;
import lombok.Value;
import lombok.With;

/**
 * Something to buy in one place and cash out in another: from a shop or the GE, to the GE, a shop, Death's coffer or
 * alching.
 */
@Value
public class Flip
{
	public enum Source
	{
		SHOP("Shop"),
		GE("GE");

		private final String label;

		Source(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	/** Where a flip cashes out; the player picks one on the Flipping tab. */
	public enum Dest
	{
		ALCH("Alch", "Alching"),
		GE("GE", "The GE"),
		SHOP("Shop", "Shops"),
		COFFER("Coffer", "Death's coffer");

		private final String label;
		private final String displayName;

		Dest(String label, String displayName)
		{
			this.label = label;
			this.displayName = displayName;
		}

		public String getLabel()
		{
			return label;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	Source source;
	Dest dest;
	/** The item's name, lowercase. */
	String item;
	int itemId;
	/** The shop it's bought from, when bought from a shop. */
	Shop buyShop;
	/** The shop it's sold to, when sold to a shop. */
	ShopOffer sellOffer;
	int quantity;
	/** What buying them all costs. */
	long cost;
	/** What they all fetch: sold, put in the coffer or alched. */
	long revenue;
	/** What the first one costs. */
	long firstCost;
	/** What the first one fetches. */
	long firstValue;
	/** What stopped the quantity going higher. */
	@With
	ShopFlip.Limit limit;
	/** Requirements the plugin couldn't check, which the player should make sure of. */
	List<String> unchecked;
	/** About how many trade on the GE in the time the player will wait; Long.MAX_VALUE if unknown or not used. */
	long geTrades;
	/** A shop's price rises with each one bought. */
	boolean priceRises;
	/** Worlds to buy them from a shop on, a few on each before hopping; 1 if not hopping or not bought from a shop. */
	int buyWorlds;

	/** About how many to buy from the shop on each world. */
	public int getPerWorld()
	{
		return (quantity + buyWorlds - 1) / Math.max(1, buyWorlds);
	}

	public long getProfit()
	{
		return revenue - cost;
	}

	/** What the first one makes. */
	public long getProfitEach()
	{
		return firstValue - firstCost;
	}

	/** Profit on the first one, as a percentage of what it costs. */
	public double getPercent()
	{
		return firstCost <= 0 ? 0 : getProfitEach() * 100.0 / firstCost;
	}

	/** Profit on the whole go, as a percentage of what it all costs. */
	public double getReturnPercent()
	{
		return cost <= 0 ? 0 : getProfit() * 100.0 / cost;
	}

	/** The shop to go to, where it's bought or sold; null if none. */
	public Shop getShop()
	{
		return buyShop != null ? buyShop : sellOffer != null ? sellOffer.getShop() : null;
	}
}

package com.assetmanager.flip;

import com.assetmanager.shop.Shop;
import java.util.List;
import lombok.Value;
import lombok.With;

/**
 * One go at flipping: one or more items bought in one place and cashed out in another. Items bought from, or sold to,
 * the same shop share a go, since every hop and trip serves them all; that's what makes some shops worth visiting.
 */
@Value
public class FlipRun
{
	Flip.Source source;
	Flip.Dest dest;
	/** The shop items are bought from or sold to; null when there's none (GE to alching or the coffer). */
	Shop shop;
	/** What's flipped, most profitable first. */
	@With
	List<Flip> flips;
	/** Worlds to hop over at the shop; 1 if not hopping or there's no shop. */
	int worlds;
	/** About how long the go takes, in seconds. */
	double seconds;
	/** Other shops where the go would be just the same; this one is the closest of them. */
	@With
	int equalShops;

	public long getCost()
	{
		return flips.stream().mapToLong(Flip::getCost).sum();
	}

	public long getRevenue()
	{
		return flips.stream().mapToLong(Flip::getRevenue).sum();
	}

	public long getProfit()
	{
		return getRevenue() - getCost();
	}

	/** Profit as a percentage of what it all costs. */
	public double getReturnPercent()
	{
		long cost = getCost();
		return cost <= 0 ? 0 : getProfit() * 100.0 / cost;
	}

	/** About what it makes an hour, done over and over. */
	public double getGpPerHour()
	{
		return getProfit() * 3600.0 / Math.max(1, seconds);
	}

	public int getQuantity()
	{
		return flips.stream().mapToInt(Flip::getQuantity).sum();
	}

	/** The row's name: the shop, or the item when there's no shop. */
	public String getName()
	{
		return shop != null ? shop.getName() : flips.get(0).getItem();
	}

	/** A run of one flip, with no shop to hop at. */
	static FlipRun single(Flip f, double seconds)
	{
		return new FlipRun(f.getSource(), f.getDest(), f.getShop(), List.of(f), Math.max(1, f.getBuyWorlds()), seconds, 0);
	}
}

package com.assetmanager.flip;

import java.util.Comparator;

/** How the Flipping tab orders flips. */
public enum FlipSort
{
	/**
	 * Most made for the time it takes: hops, trips, conversations, alchs and waiting for the GE. What a big go makes
	 * doesn't matter if it takes all day.
	 */
	GP_PER_HOUR("GP per hour", Comparator.comparingDouble(FlipRun::getGpPerHour)),
	/** Most coins made in one go, however long it takes. */
	PROFIT("Total profit", Comparator.comparingLong(FlipRun::getProfit)),
	/**
	 * Most made for each coin spent: for Death's coffer, where the coins spent are gone, so getting the most out of
	 * them matters more than the total.
	 */
	RETURN("Return (%)", Comparator.comparingDouble(FlipRun::getReturnPercent));

	private final String displayName;
	/** Least good first. */
	private final Comparator<FlipRun> order;

	FlipSort(String displayName, Comparator<FlipRun> order)
	{
		this.displayName = displayName;
		this.order = order;
	}

	/** Best first, then the next measure, then by name so the order is stable. */
	public Comparator<FlipRun> best()
	{
		Comparator<FlipRun> other = (this == GP_PER_HOUR ? PROFIT : GP_PER_HOUR).order;
		return order.reversed().thenComparing(other.reversed()).thenComparing(FlipRun::getName);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.assetmanager.flip;

/**
 * Rough estimates of how long a flip takes, so flips can be compared by what they make an hour. A go's active time is
 * the player's own: getting to the shop and back, hopping, clicking, talking and alching. The GE fills offers while
 * they do the rest, so a go takes whichever is longer: that, or the wait for the GE.
 */
public final class FlipTime
{
	/** Hopping to a fresh world and opening the shop again. */
	static final double HOP_SECONDS = 15;
	/** One conversation with a trader who sells by talking: about 1,000 an hour. */
	static final double TALK_SECONDS = 3.6;
	/** Getting to a shop or Death's coffer and back to a bank, once a go. */
	static final double TRIP_SECONDS = 60;
	/** One Buy or Sell click in a shop's window. */
	static final double CLICK_SECONDS = 1.2;
	/** Most a shop's window buys or sells in one click (Buy 50). */
	static final int PER_CLICK = 50;
	/** One high alch: 5 ticks, 1,200 an hour. */
	static final double ALCH_SECONDS = 3;
	/** The GE's buy limit resets every 4 hours. */
	static final double BUY_LIMIT_HOURS = 4;

	private FlipTime()
	{
	}

	/** Clicks to buy or sell {@code quantity} in a shop's window over {@code worlds} worlds: at least one on each. */
	static long clicks(long quantity, int worlds)
	{
		return Math.max(worlds, (quantity + PER_CLICK - 1) / PER_CLICK);
	}

	/**
	 * Seconds waiting for GE offers to fill: the time the player will wait, or the buy limit's 4 hours when that's what
	 * stopped the buying, since another round can't start sooner.
	 */
	static double geWaitSeconds(double geHours, ShopFlip.Limit limit)
	{
		return (limit == ShopFlip.Limit.BUY_LIMIT ? Math.max(geHours, BUY_LIMIT_HOURS) : geHours) * 3600;
	}

	/** "1h 5m", "12m", "45s". */
	public static String describe(double seconds)
	{
		long s = Math.round(seconds);
		if (s < 60)
		{
			return Math.max(1, s) + "s";
		}
		long m = (s + 30) / 60;
		return m >= 60 ? m / 60 + "h " + m % 60 + "m" : m + "m";
	}
}

package com.assetmanager.flip;

import com.assetmanager.AccountMode;
import com.assetmanager.shop.SellRules;
import com.assetmanager.shop.Shop;
import com.assetmanager.shop.ShopCatalog;
import com.assetmanager.shop.ShopOffer;
import com.assetmanager.shop.ShopPerks;
import com.assetmanager.shop.Unlocks;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import lombok.Value;
import lombok.With;
import net.runelite.api.coords.WorldPoint;

/**
 * The best flips of every kind in one list. Shop-bought ones come from {@link BestBuys}; this adds what's worth buying
 * on the Grand Exchange to sell to a shop, put in Death's coffer or alch.
 * <p>
 * Every flip is one go: a shop visit, or one round of GE offers in the time the player will wait (no more than the buy
 * limit). They're ranked by what that makes, or what it makes an hour (see {@link FlipTime}).
 */
public final class Flips
{
	/** Alchs in an hour: one every 5 ticks. */
	public static final long ALCHS_PER_HOUR = 1200;

	/** Each shop sale only has to beat what the item cost on the GE. */
	private static final SellRules UNLIMITED = new SellRules(1, ShopCatalog.NO_WORLD_LIMIT, 0);

	private Flips()
	{
	}

	/**
	 * Where an account can cash out flips. Ironmen can't use the GE, and the coffer is the only flip that makes sense
	 * for them; ultimate ironmen can't use the coffer, so they alch.
	 */
	public static List<Flip.Dest> destinations(AccountMode mode)
	{
		if (mode.canUseGrandExchange())
		{
			return List.of(Flip.Dest.values());
		}
		return List.of(mode.canUseCoffer() ? Flip.Dest.COFFER : Flip.Dest.ALCH);
	}

	/** The player's choice of where to cash out, if their account can; otherwise the first place it can. */
	public static Flip.Dest destination(AccountMode mode, Flip.Dest chosen)
	{
		List<Flip.Dest> can = destinations(mode);
		return can.contains(chosen) ? chosen : can.get(0);
	}

	/** What items cost on the GE and what they're worth elsewhere. Gathered on the client thread. */
	public interface GeMarket
	{
		/** The items with live GE prices. */
		Collection<Integer> items();

		/** What one costs on the GE, waiting as long as the player will; 0 if its price can't be relied on. */
		long buy(int itemId);

		/** About how many trade in the time the player will wait; -1 if unknown. */
		long trades(int itemId);

		/** The GE buy limit per 4 hours, or 0 if unknown. */
		int buyLimit(int itemId);

		/** The item's name in lowercase, as the shop data has it; null if unknown. */
		String name(int itemId);

		/** The item's store value, which shops pay a % of. */
		int storeValue(int itemId);

		/** Coins added to the coffer per item, or 0 if it isn't accepted. */
		long coffer(int itemId);

		/** Coins from alching one, less the nature rune. */
		long alch(int itemId);

		/** Whether it can be alched; shops won't buy items that can't. */
		boolean alchable(int itemId);

		/** Whether it's a members item, which can't be traded or used on a free-to-play world. */
		default boolean members(int itemId)
		{
			return false;
		}

		/** Hours the player will wait for offers to fill. */
		default double geHours()
		{
			return 1;
		}
	}

	/**
	 * Whatever's worth buying on the GE to cash out at {@code dest}. Selling back on the GE isn't a flip this finds.
	 * Alching and the coffer are a go per item; selling to shops is a go per shop, with everything it pays more for
	 * than the GE charges sold together, on the same hops.
	 *
	 * @param dest      where the player wants to cash out: a shop, the coffer or alching
	 * @param unlocks   what the player has unlocked, for the shops they can sell to
	 * @param maxWorlds the most worlds to hop selling to a shop, or ShopCatalog.NO_WORLD_LIMIT
	 * @param coins     coins to spend
	 * @param alchCasts how many alchs to plan for
	 * @param maxItems  the most different items to buy on the GE for one shop go (it has 8 offer slots)
	 */
	public static List<FlipRun> fromGe(GeMarket m, Flip.Dest dest, ShopCatalog catalog, Unlocks unlocks, ShopPerks perks,
		int maxWorlds, long coins, long alchCasts, int maxItems)
	{
		if (dest == Flip.Dest.GE)
		{
			return Collections.emptyList();
		}
		Map<Shop, Unlocks.Missing> missing = new IdentityHashMap<>();
		for (Shop shop : catalog.getShops())
		{
			missing.put(shop, unlocks.missing(shop, null));
		}
		Predicate<Shop> usable = shop -> missing.get(shop).isMet();
		Predicate<Shop> noted = shop -> missing.get(shop).isMet() && shop.getTalk() == null;
		Predicate<Shop> unnoted = shop -> missing.get(shop).isMet() && shop.getTalk() != null;
		double geHours = m.geHours();
		List<FlipRun> out = new ArrayList<>();
		// What each shop pays more for than the GE charges
		Map<Shop, List<Sale>> sales = new IdentityHashMap<>();
		for (int id : m.items())
		{
			long cost = m.buy(id);
			long trades = m.trades(id);
			// Items that don't trade can't be bought, nor members items on a free-to-play world
			if (cost <= 0 || trades < 1 || !unlocks.isMembers() && m.members(id))
			{
				continue;
			}
			long cap = trades;
			ShopFlip.Limit why = ShopFlip.Limit.VOLUME;
			int limit = m.buyLimit(id);
			if (limit > 0 && limit < cap)
			{
				cap = limit;
				why = ShopFlip.Limit.BUY_LIMIT;
			}
			if (coins / cost < cap)
			{
				cap = coins / cost;
				why = ShopFlip.Limit.COINS;
			}
			if (cap < 1)
			{
				continue;
			}
			double wait = FlipTime.geWaitSeconds(geHours, why);

			long coffer = m.coffer(id);
			if (dest == Flip.Dest.COFFER && coffer > cost)
			{
				out.add(FlipRun.single(flip(Flip.Dest.COFFER, m, id, cap, cost, coffer, why, trades),
					Math.max(FlipTime.TRIP_SECONDS, wait)));
			}

			long alch = m.alch(id);
			if (dest == Flip.Dest.ALCH && alch > cost)
			{
				Flip f = alchCasts < cap
					? flip(Flip.Dest.ALCH, m, id, alchCasts, cost, alch, ShopFlip.Limit.CASTS, trades)
					: flip(Flip.Dest.ALCH, m, id, cap, cost, alch, why, trades);
				out.add(FlipRun.single(f, Math.max(f.getQuantity() * FlipTime.ALCH_SECONDS, wait)));
			}

			String name = m.name(id);
			int value = m.storeValue(id);
			// Shops won't buy items that can't be alched, though some have a store value to protect them on death
			if (dest == Flip.Dest.SHOP && name != null && value > 0 && m.alchable(id))
			{
				// Most items no shop pays more for than the GE charges, which one sale finds out
				ShopOffer probe = catalog.bestOffer(name, value, 1, true, perks, cost, UNLIMITED, usable);
				if (probe == null || probe.getQuantity() == 0)
				{
					continue;
				}
				Sale sale = new Sale(id, name, value, cost, why, trades, null, why);
				addSales(sales, catalog, perks, noted, sale, cap, why, maxWorlds);
				// Traders bought from by talking only take unnoted items, so it's an inventory a trip
				long trip = Math.min(cap, BestBuys.INVENTORY_SIZE);
				addSales(sales, catalog, perks, unnoted, sale, trip, trip < cap ? ShopFlip.Limit.SPACE : why, maxWorlds);
			}
		}
		// In the catalog's order, so the result is the same every time
		for (Shop shop : catalog.getShops())
		{
			List<Sale> list = sales.get(shop);
			FlipRun run = list == null ? null : sellRun(shop, list, catalog, perks, coins, geHours, missing.get(shop), maxItems);
			if (run != null)
			{
				out.add(run);
			}
		}
		return mergeEqual(out, perks.getLocation());
	}

	/** An item bought on the GE to sell to a shop. */
	@Value
	private static class Sale
	{
		int itemId;
		String name;
		int value;
		/** What one costs on the GE. */
		long cost;
		/** What stopped the GE buying going higher. */
		ShopFlip.Limit geLimit;
		long trades;
		/** What the shop pays for the stack; set per shop. */
		@With
		ShopOffer offer;
		/** What stopped the quantity going higher; set per shop. */
		@With
		ShopFlip.Limit limit;
	}

	/**
	 * Adds a sale of up to {@code qty} to each of the {@code usable} shops paying more than the GE charges, hopping no
	 * more than {@code maxWorlds}.
	 */
	private static void addSales(Map<Shop, List<Sale>> sales, ShopCatalog catalog, ShopPerks perks, Predicate<Shop> usable,
		Sale sale, long qty, ShopFlip.Limit why, int maxWorlds)
	{
		int n = (int) Math.min(qty, Integer.MAX_VALUE);
		for (ShopOffer offer : catalog.offers(sale.getName(), sale.getValue(), n, true, perks, sale.getCost(), UNLIMITED, usable))
		{
			if (offer.getQuantity() == 0)
			{
				continue;
			}
			ShopFlip.Limit limit = why;
			if (maxWorlds != ShopCatalog.NO_WORLD_LIMIT && offer.getWorlds() > maxWorlds)
			{
				offer = offerAt(catalog, perks, sale, offer.getShop(), offer.getPerWorld() * maxWorlds);
				limit = ShopFlip.Limit.WORLDS;
			}
			if (offer != null && offer.getQuantity() > 0)
			{
				sales.computeIfAbsent(offer.getShop(), s -> new ArrayList<>()).add(sale.withOffer(offer).withLimit(limit));
			}
		}
	}

	/** What one shop pays for {@code qty}; null if it won't buy them. */
	private static ShopOffer offerAt(ShopCatalog catalog, ShopPerks perks, Sale sale, Shop shop, long qty)
	{
		List<ShopOffer> offers = catalog.offers(sale.getName(), sale.getValue(), (int) Math.min(qty, Integer.MAX_VALUE), true,
			perks, sale.getCost(), UNLIMITED, s -> s == shop);
		return offers.isEmpty() ? null : offers.get(0);
	}

	/**
	 * A go selling to one shop: the {@code maxItems} items making the most that the coins reach, then the best returns
	 * first while the coins last (and, for a trader taking only unnoted items, the inventory). Null if nothing's worth it.
	 */
	private static FlipRun sellRun(Shop shop, List<Sale> sales, ShopCatalog catalog, ShopPerks perks, long coins, double geHours,
		Unlocks.Missing missing, int maxItems)
	{
		// The GE has only so many offer slots, so it's the items making the most
		sales.sort(Comparator.comparingLong(Flips::saleProfit).reversed().thenComparing(Sale::getName));
		List<Sale> chosen = new ArrayList<>();
		for (Sale sale : sales)
		{
			if (chosen.size() >= maxItems)
			{
				break;
			}
			if (sale.getCost() <= coins)
			{
				chosen.add(sale);
			}
		}
		sales = chosen;
		sales.sort(Comparator.comparingDouble(Flips::saleReturn).reversed().thenComparing(Sale::getName));
		boolean talk = shop.getTalk() != null;
		long coinsLeft = coins;
		long slotsLeft = talk ? BestBuys.INVENTORY_SIZE : Long.MAX_VALUE;
		List<Flip> flips = new ArrayList<>();
		int worlds = 1;
		long clicks = 0;
		double wait = 0;
		for (Sale sale : sales)
		{
			ShopOffer offer = sale.getOffer();
			ShopFlip.Limit limit = sale.getLimit();
			long fit = Math.min(offer.getQuantity(), Math.min(coinsLeft / sale.getCost(), slotsLeft));
			if (fit < 1)
			{
				continue;
			}
			if (fit < offer.getQuantity())
			{
				limit = fit == slotsLeft ? ShopFlip.Limit.SPACE : ShopFlip.Limit.COINS;
				offer = offerAt(catalog, perks, sale, shop, fit);
				if (offer == null || offer.getQuantity() == 0)
				{
					continue;
				}
			}
			int qty = offer.getQuantity();
			coinsLeft -= sale.getCost() * qty;
			slotsLeft -= qty;
			worlds = Math.max(worlds, offer.getWorlds());
			clicks += talk ? 1 : FlipTime.clicks(qty, offer.getWorlds());
			wait = Math.max(wait, FlipTime.geWaitSeconds(geHours, sale.getGeLimit()));
			List<String> unchecked = missing.getUnchecked();
			flips.add(new Flip(Flip.Source.GE, Flip.Dest.SHOP, sale.getName(), sale.getItemId(), null, offer, qty, sale.getCost() * qty,
				offer.getTotal(), sale.getCost(), offer.getFirstUnit(), limit,
				unchecked.isEmpty() ? Collections.emptyList() : new ArrayList<>(unchecked), sale.getTrades(), false, 1));
		}
		if (flips.isEmpty())
		{
			return null;
		}
		flips.sort(Comparator.comparingLong(Flip::getProfit).reversed().thenComparing(Flip::getItem));
		double active = FlipTime.TRIP_SECONDS + (worlds - 1) * FlipTime.HOP_SECONDS
			+ clicks * (talk ? FlipTime.TALK_SECONDS : FlipTime.CLICK_SECONDS);
		return new FlipRun(Flip.Source.GE, Flip.Dest.SHOP, shop, flips, worlds, Math.max(active, wait), 0);
	}

	/** What selling the whole stack makes. */
	private static long saleProfit(Sale s)
	{
		return s.getOffer().getTotal() - s.getCost() * s.getOffer().getQuantity();
	}

	/** What selling the whole stack makes for each coin it costs on the GE. */
	private static double saleReturn(Sale s)
	{
		long cost = s.getCost() * s.getOffer().getQuantity();
		return (s.getOffer().getTotal() - cost) / (double) cost;
	}

	/**
	 * Gos that are just the same at different shops (stores sharing a stock and rates, often), as one: the closest
	 * shop's, counting the others.
	 */
	static List<FlipRun> mergeEqual(List<FlipRun> runs, WorldPoint from)
	{
		List<FlipRun> out = new ArrayList<>(runs.size());
		Map<String, FlipRun> best = new LinkedHashMap<>();
		Map<String, Integer> count = new HashMap<>();
		for (FlipRun run : runs)
		{
			if (run.getShop() == null)
			{
				out.add(run);
				continue;
			}
			StringBuilder key = new StringBuilder().append(run.getSource()).append(run.getDest()).append(':').append(run.getProfit())
				.append(':').append(run.getCost()).append(':').append(run.getWorlds()).append(':').append(run.getShop().getTalk() != null);
			for (Flip f : run.getFlips())
			{
				key.append(':').append(f.getItemId()).append('x').append(f.getQuantity());
			}
			String k = key.toString();
			count.merge(k, 1, Integer::sum);
			best.merge(k, run, (a, b) -> b.getShop().distanceTo(from) < a.getShop().distanceTo(from) ? b : a);
		}
		best.forEach((k, run) -> out.add(count.get(k) > 1 ? run.withEqualShops(count.get(k) - 1) : run));
		return out;
	}

	private static Flip flip(Flip.Dest dest, GeMarket m, int id, long qty, long cost, long unit, ShopFlip.Limit why, long trades)
	{
		String name = m.name(id);
		return new Flip(Flip.Source.GE, dest, name == null ? "item " + id : name, id, null, null, (int) Math.min(qty, Integer.MAX_VALUE),
			cost * qty, unit * qty, cost, unit, why, Collections.emptyList(), trades, false, 1);
	}

	/** A shop deal as a flip. */
	public static Flip fromShop(BestBuys.Deal d)
	{
		ShopFlip f = d.getFlip();
		Flip.Dest dest = d.getKind() == BestBuys.Kind.COFFER ? Flip.Dest.COFFER : d.getKind() == BestBuys.Kind.ALCH ? Flip.Dest.ALCH
			: Flip.Dest.GE;
		return new Flip(Flip.Source.SHOP, dest, d.getItem(), d.getItemId(), d.getShop(), null, f.getQuantity(), f.getCost(),
			f.getRevenue(), f.getFirstPrice(), f.getGeUnit(), f.getLimit(), d.getUnchecked(), d.getTradesPerHour(), d.isPriceRises(),
			f.getWorlds());
	}

	/**
	 * The best gos, best first by {@code sort}. Only the best general store is kept: they all buy the same things, so
	 * the rest are worse ways to do the same.
	 *
	 * @param minGain only gos making at least this much
	 * @param limit   at most this many
	 */
	public static List<FlipRun> rank(Collection<FlipRun> runs, long minGain, int limit, FlipSort sort)
	{
		List<FlipRun> sorted = new ArrayList<>(runs);
		sorted.sort(sort.best());
		List<FlipRun> out = new ArrayList<>();
		boolean generalStore = false;
		for (FlipRun r : sorted)
		{
			boolean general = r.getShop() != null && r.getShop().isGeneral();
			if (r.getProfit() < Math.max(1, minGain) || general && generalStore)
			{
				continue;
			}
			generalStore |= general;
			out.add(r);
		}
		return out.size() > limit ? new ArrayList<>(out.subList(0, limit)) : out;
	}
}

package com.assetmanager.flip;

import lombok.Value;

/** How many of a shop's item to buy and sell on (on the GE, to Death's coffer or by alching), and the profit it makes. */
@Value
public class ShopFlip
{
	public enum Limit
	{
		/** The shop ran out. */
		STOCK("shop stock"),
		/** The shop's price rose until it wasn't profitable. */
		PRICE("price rises as stock drops"),
		/** No more room in the inventory. */
		SPACE("inventory space"),
		/** Not enough coins in the inventory. */
		COINS("coins in inventory"),
		/** More than the GE trades in the time the player will wait. */
		VOLUME("what the GE trades in that time"),
		/** As many as can be alched in an hour. */
		CASTS("an hour of alching"),
		/** The GE's buy limit (per 4 hours). */
		BUY_LIMIT("GE buy limit"),
		/** More would take hopping more worlds than the player's limit. */
		WORLDS("worlds you'd hop"),
		/** Hopping more worlds would make more, but less an hour. */
		QUICKER("hopping more makes less an hour"),
		/** Enough to fill Death's coffer to the target. */
		COFFER("room in your coffer"),
		/** As many different items as the player will flip through the GE at once. */
		GE_SLOTS("items per GE flip");

		private final String description;

		Limit(String description)
		{
			this.description = description;
		}

		public String getDescription()
		{
			return description;
		}
	}

	int quantity;
	long cost;
	/** Coins from selling them all on the GE after tax, the coffer value, or what alching them makes. */
	long revenue;
	long firstPrice;
	long lastPrice;
	/** What one is worth where it's going: the GE sale after tax, the coffer value, or alching less the rune. */
	long geUnit;
	/** What stopped the quantity going higher. */
	Limit limit;
	/** Worlds to buy them on, a few on each before hopping (1 if the price doesn't rise or the shop is in front of you). */
	int worlds;

	/** About how many to buy on each world. */
	public int getPerWorld()
	{
		return (quantity + worlds - 1) / Math.max(1, worlds);
	}

	public long getProfit()
	{
		return revenue - cost;
	}
}

package com.assetmanager.flip;

/**
 * Works out how many of a shop's item to buy to resell on the Grand Exchange.
 * <p>
 * A shop charges {@code value * (sellRate + delta * (normalStock - stock))}: its price rises by delta for each
 * item bought below its normal stock. Buying stops when the next one wouldn't make at least the minimum profit,
 * or the shop, inventory space or coins run out.
 */
public final class ShopFlipAdvisor
{
	/** Shops never charge less than 10% of an item's value. */
	private static final int MIN_RATE = 100;

	private ShopFlipAdvisor()
	{
	}

	/**
	 * @param value         the item's store value
	 * @param stock         how many the shop has right now
	 * @param normalStock   the shop's normal stock, or -1 if it never runs out
	 * @param sellRate      what the shop charges at normal stock, in tenths of a percent
	 * @param delta         change in rate per item of stock, in tenths of a percent
	 * @param geUnit        coins from selling one on the GE, after tax
	 * @param minProfitEach only buy while each one makes at least this much
	 * @param maxSpace      how many fit in the inventory
	 * @param coins         coins available to spend
	 * @return the flip, or null if not even one is worth buying
	 */
	public static ShopFlip plan(int value, int stock, int normalStock, int sellRate, int delta, long geUnit,
		int minProfitEach, int maxSpace, long coins)
	{
		return plan(value, stock, normalStock, sellRate, delta, geUnit, minProfitEach, maxSpace, coins, Long.MAX_VALUE);
	}

	/**
	 * As above, buying no more than the GE trades in an hour ({@code geVolume}, Long.MAX_VALUE if unknown), so they
	 * can actually be sold. Items that trade less than once an hour aren't worth buying at all.
	 */
	public static ShopFlip plan(int value, int stock, int normalStock, int sellRate, int delta, long geUnit,
		int minProfitEach, int maxSpace, long coins, long geVolume)
	{
		return plan(value, stock, normalStock, sellRate, delta, geUnit, minProfitEach, maxSpace, coins, geVolume,
			ShopFlip.Limit.VOLUME);
	}

	/**
	 * As above, buying no more than {@code cap} (Long.MAX_VALUE for no cap), which is reported as {@code capLimit}
	 * when it's what stops the buying: what the GE trades, room in the coffer, or alchs in an hour.
	 */
	public static ShopFlip plan(int value, int stock, int normalStock, int sellRate, int delta, long geUnit,
		int minProfitEach, int maxSpace, long coins, long cap, ShopFlip.Limit capLimit)
	{
		boolean infinite = normalStock < 0;
		int bought = 0;
		long cost = 0;
		long first = 0;
		long last = 0;
		ShopFlip.Limit limit;
		while (true)
		{
			if (!infinite && bought >= stock)
			{
				limit = ShopFlip.Limit.STOCK;
				break;
			}
			if (bought >= maxSpace)
			{
				limit = ShopFlip.Limit.SPACE;
				break;
			}
			if (bought >= cap)
			{
				limit = capLimit;
				break;
			}
			long price = price(value, infinite ? sellRate : sellRate + delta * (normalStock - (stock - bought)));
			if (geUnit - price < Math.max(1, minProfitEach))
			{
				limit = ShopFlip.Limit.PRICE;
				break;
			}
			if (cost + price > coins)
			{
				limit = ShopFlip.Limit.COINS;
				break;
			}
			if (bought == 0)
			{
				first = price;
			}
			last = price;
			cost += price;
			bought++;
		}
		if (bought == 0)
		{
			return null;
		}
		return new ShopFlip(bought, cost, geUnit * bought, first, last, geUnit, limit, 1);
	}

	/**
	 * As above, hopping worlds: every world's shop starts at its normal stock, so buying a few on each, while the price
	 * is still low, then hopping beats buying deep on one. Items are bought round the worlds in turn, the cheapest
	 * next one each time, on no more than {@code maxWorlds} (ShopCatalog.NO_WORLD_LIMIT, 0, for no limit).
	 */
	public static ShopFlip planHopping(int value, int normalStock, int sellRate, int delta, long geUnit, int minProfitEach,
		int maxSpace, long coins, long cap, ShopFlip.Limit capLimit, int maxWorlds)
	{
		boolean infinite = normalStock < 0;
		// The price never rises in a shop that never runs out, so there's nothing to hop for
		long worlds = infinite ? 1 : maxWorlds <= 0 ? Long.MAX_VALUE : maxWorlds;
		long bought = 0;
		long cost = 0;
		long first = 0;
		long last = 0;
		ShopFlip.Limit limit;
		while (true)
		{
			// How many have already been bought on the world this one comes from
			long depth = bought / worlds;
			if (!infinite && depth >= normalStock)
			{
				// Every world's stock is bought: more worlds would mean more
				limit = worlds == 1 || worlds == Long.MAX_VALUE ? ShopFlip.Limit.STOCK : ShopFlip.Limit.WORLDS;
				break;
			}
			if (bought >= maxSpace)
			{
				limit = ShopFlip.Limit.SPACE;
				break;
			}
			if (bought >= cap)
			{
				limit = capLimit;
				break;
			}
			long price = price(value, infinite ? sellRate : (int) Math.min(Integer.MAX_VALUE, sellRate + delta * depth));
			if (geUnit - price < Math.max(1, minProfitEach))
			{
				limit = ShopFlip.Limit.PRICE;
				break;
			}
			if (cost + price > coins)
			{
				limit = ShopFlip.Limit.COINS;
				break;
			}
			if (bought == 0)
			{
				first = price;
			}
			last = Math.max(last, price);
			cost += price;
			bought++;
		}
		if (bought == 0)
		{
			return null;
		}
		int used = (int) Math.min(worlds, bought);
		return new ShopFlip((int) bought, cost, geUnit * bought, first, last, geUnit, limit, used);
	}

	static long price(int value, int rate)
	{
		return (long) value * Math.max(MIN_RATE, rate) / 1000;
	}
}

package com.assetmanager.flip;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

/**
 * Marks shop items worth buying with where to take them, a Grand Exchange icon or Death's coffer (whichever makes more),
 * and how many to buy from what the shop holds now.
 */
@Singleton
public class ShopFlipOverlay extends Overlay
{
	private static final int ICON_SIZE = 12;
	private static final Color COUNT = new Color(0x4CAF50);

	private final Client client;
	private final ShopFlipper flipper;
	private volatile Image icon;
	private final Image cofferIcon;

	@Inject
	ShopFlipOverlay(Client client, ShopFlipper flipper, SpriteManager spriteManager)
	{
		this.client = client;
		this.flipper = flipper;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		spriteManager.getSpriteAsync(SpriteID.Mapfunction.GRAND_EXCHANGE, 0,
			img -> icon = img == null ? null : ImageUtil.resizeImage(img, ICON_SIZE, ICON_SIZE));
		// The plugin's icon, as the coffer suggestions elsewhere use
		cofferIcon = ImageUtil.resizeImage(ImageUtil.loadImageResource(getClass(), "/com/assetmanager/icon.png"), ICON_SIZE,
			ICON_SIZE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Map<Integer, ShopFlipper.Buy> flips = flipper.getFlips();
		Image geIcon = icon;
		if (flips.isEmpty())
		{
			return null;
		}
		Widget items = client.getWidget(InterfaceID.Shopmain.ITEMS);
		if (items == null || items.isHidden() || items.getDynamicChildren() == null)
		{
			return null;
		}
		Rectangle visible = items.getBounds();
		for (Widget w : items.getDynamicChildren())
		{
			ShopFlipper.Buy buy = w.isHidden() ? null : flips.get(w.getItemId());
			if (buy == null)
			{
				continue;
			}
			Rectangle b = w.getBounds();
			// Skip items scrolled out of view
			if (!visible.contains(b.x + b.width / 2, b.y + b.height / 2))
			{
				continue;
			}
			Image img = buy.isCofferBest() ? cofferIcon : geIcon;
			if (img != null)
			{
				g.drawImage(img, b.x + b.width - ICON_SIZE, b.y, null);
			}
			String count = "buy " + QuantityFormatter.quantityToStackSize(buy.best().getQuantity());
			g.setFont(FontManager.getRunescapeSmallFont());
			int y = b.y + b.height;
			g.setColor(Color.BLACK);
			g.drawString(count, b.x + 1, y + 1);
			g.setColor(COUNT);
			g.drawString(count, b.x, y);
		}
		return null;
	}
}

package com.assetmanager.flip;

import com.assetmanager.AssetManagerConfig;
import com.assetmanager.shop.Shop;
import com.assetmanager.shop.ShopCatalog;
import com.assetmanager.ui.PriceTooltip;
import com.assetmanager.value.ItemValuator;
import com.assetmanager.value.ItemValues;
import com.assetmanager.value.LivePrices;
import java.awt.Color;
import java.awt.Dimension;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

/**
 * While a shop is open, works out which shop it is, finds the items it sells that could be resold on the
 * Grand Exchange or put in Death's coffer for a profit, and shows how many to buy when one is hovered.
 */
@Slf4j
@Singleton
public class ShopFlipper
{
	private static final Color GOOD = new Color(0x4CAF50);
	private static final Color NORMAL = new Color(0xEEEEEE);
	private static final Color MUTED = new Color(0x9E9E9E);
	private static final int INVENTORY_SIZE = 28;

	private final Client client;
	private final ItemManager itemManager;
	private final ItemValuator itemValuator;
	private final LivePrices livePrices;
	private final TooltipManager tooltipManager;
	private final AssetManagerConfig config;

	@Setter
	private ShopCatalog shops;
	@Setter
	private int glovesTier;
	/** Whether the account can sell on the GE. */
	@Setter
	private volatile boolean canUseGe = true;
	/**
	 * Coins Death's coffer should take: how far it is below the target, Long.MAX_VALUE for no limit, or 0 when it's full
	 * or the account can't use it.
	 */
	@Setter
	private volatile long cofferRoom;

	/** The open shop, if it's in the shop data. */
	@Getter
	private volatile Shop openShop;
	@Getter
	private volatile int openShopGlovesTier;

	/** What's worth buying in the open shop, and where to take it, by item id. */
	@Getter
	private volatile Map<Integer, Buy> flips = Collections.emptyMap();

	/** A shop item worth buying: to sell on the GE, to put in Death's coffer, or both. */
	@Value
	public static class Buy
	{
		/** Selling on the GE, or null if it isn't worth it. */
		ShopFlip ge;
		/** Putting in Death's coffer, or null if it isn't worth it. */
		ShopFlip coffer;

		/** Whichever makes more. */
		public ShopFlip best()
		{
			return isCofferBest() ? coffer : ge;
		}

		public boolean isCofferBest()
		{
			return ge == null || coffer != null && coffer.getProfit() > ge.getProfit();
		}
	}
	private String lastTitle;

	@Inject
	ShopFlipper(Client client, ItemManager itemManager, ItemValuator itemValuator, LivePrices livePrices,
		TooltipManager tooltipManager, AssetManagerConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.itemValuator = itemValuator;
		this.livePrices = livePrices;
		this.tooltipManager = tooltipManager;
		this.config = config;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		Widget items = client.getWidget(InterfaceID.Shopmain.ITEMS);
		if (shops == null || items == null || items.isHidden())
		{
			flips = Collections.emptyMap();
			openShop = null;
			lastTitle = null;
			return;
		}

		String title = shopTitle();
		Shop shop = shops.findByName(title);
		openShop = shop;
		openShopGlovesTier = glovesTier;
		if (!title.equals(lastTitle))
		{
			lastTitle = title;
			log.debug("Shop opened: \"{}\" ({})", title, shop == null ? "not in shop data" : "matched " + shop.getName());
		}
		boolean geFlips = config.shopFlips() && canUseGe;
		long room = config.shopCofferBuys() ? cofferRoom : 0;
		if (!geFlips && room <= 0 || shop == null || items.getDynamicChildren() == null)
		{
			flips = Collections.emptyMap();
			return;
		}

		int freeSlots = INVENTORY_SIZE;
		long coins = 0;
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv != null)
		{
			for (Item i : inv.getItems())
			{
				if (i.getId() > 0)
				{
					freeSlots--;
					if (i.getId() == ItemID.COINS)
					{
						coins += i.getQuantity();
					}
				}
			}
		}
		// With no coins on hand the player will fetch some, so don't limit by them
		long budget = coins > 0 ? coins : Long.MAX_VALUE;

		Map<Integer, Buy> found = new HashMap<>();
		for (Widget w : items.getDynamicChildren())
		{
			int itemId = w.getItemId();
			if (itemId <= 0 || w.isHidden())
			{
				continue;
			}
			ItemValues v = itemValuator.get(itemId);
			Shop.Item entry = shop.getItems().get(v.getName().toLowerCase());
			if (!v.isTradeable() || entry == null || entry.isNs())
			{
				continue;
			}
			boolean gloves = shop.getGlovesTier() != null && glovesTier >= shop.getGlovesTier() && entry.getGs() != null;
			int sellRate = gloves ? entry.getGs() : entry.getSm() != null ? entry.getSm() : shop.getSellMultiplier();
			int delta = entry.getD() != null ? entry.getD() : shop.getDelta();

			boolean stackable = itemManager.getItemComposition(itemId).isStackable();
			int space = stackable ? (freeSlots > 0 || (inv != null && inv.count(itemId) > 0) ? Integer.MAX_VALUE : 0) : freeSlots;

			// Some shops charge a set price rather than their usual % of value
			int value = entry.getSp() != null && !gloves && sellRate > 0
				? (int) ((entry.getSp() * 1000L + sellRate - 1) / sellRate) : v.getStorePrice();
			ShopFlip ge = null;
			if (geFlips)
			{
				// With live prices, don't buy more than the GE trades in an hour
				long perHour = livePrices.tradesPerHour(itemManager.canonicalize(itemId));
				long geVolume = perHour < 0 ? Long.MAX_VALUE : perHour;
				ge = worthIt(ShopFlipAdvisor.plan(value, w.getItemQuantity(), entry.getS(), sellRate, delta,
					v.getGeNetSell(), 1, space, budget, geVolume));
			}
			ShopFlip coffer = null;
			long unit = v.getCofferValue();
			if (room > 0 && unit > 0)
			{
				// Enough to fill the coffer, the last one going a little over
				long need = room == Long.MAX_VALUE ? Long.MAX_VALUE : (room + unit - 1) / unit;
				coffer = worthIt(ShopFlipAdvisor.plan(value, w.getItemQuantity(), entry.getS(), sellRate, delta,
					unit, 1, space, budget, need, ShopFlip.Limit.COFFER));
			}
			if (ge != null || coffer != null)
			{
				found.put(itemId, new Buy(ge, coffer));
			}
		}
		flips = found;
	}

	/** The flip, if it makes at least the player's minimum. */
	private ShopFlip worthIt(ShopFlip flip)
	{
		return flip != null && flip.getProfit() >= config.minFlipProfit() ? flip : null;
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		Map<Integer, Buy> current = flips;
		if (current.isEmpty() || client.isMenuOpen())
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}
		MenuEntry entry = entries[entries.length - 1];
		Widget w = entry.getWidget();
		if (entry.getParam1() != InterfaceID.Shopmain.ITEMS || w == null)
		{
			return;
		}
		Buy buy = current.get(w.getItemId());
		if (buy != null)
		{
			tooltipManager.add(new Tooltip(tooltip(w.getItemId(), buy)));
		}
	}

	private PanelComponent tooltip(int itemId, Buy buy)
	{
		PanelComponent p = new PanelComponent();
		p.setBackgroundColor(PriceTooltip.SOLID_BACKGROUND);
		p.setPreferredSize(new Dimension(180, 0));
		// The better one first
		ShopFlip first = buy.best();
		for (ShopFlip f : new ShopFlip[]{first, first == buy.getGe() ? buy.getCoffer() : buy.getGe()})
		{
			if (f == null)
			{
				continue;
			}
			boolean coffer = f == buy.getCoffer();
			if (p.getChildren().size() > 0)
			{
				p.getChildren().add(LineComponent.builder().left(" ").build());
			}
			p.getChildren().add(TitleComponent.builder().text(coffer ? "Put in Death's coffer" : "Flip on the GE").color(GOOD).build());
			p.getChildren().add(line("Buy", QuantityFormatter.formatNumber(f.getQuantity()), NORMAL));
			String each = f.getFirstPrice() == f.getLastPrice()
				? QuantityFormatter.formatNumber(f.getFirstPrice())
				: QuantityFormatter.formatNumber(f.getFirstPrice()) + " – " + QuantityFormatter.formatNumber(f.getLastPrice());
			p.getChildren().add(line("Shop price each", each, NORMAL));
			p.getChildren().add(line(coffer ? "Coffer adds each" : "GE sells for each", QuantityFormatter.formatNumber(f.getGeUnit()),
				NORMAL));
			p.getChildren().add(line("Profit", QuantityFormatter.formatNumber(f.getProfit()), GOOD));
			p.getChildren().add(LineComponent.builder().left("Limited by " + f.getLimit().getDescription()).leftColor(MUTED).build());
			if (!coffer)
			{
				long perHour = livePrices.tradesPerHour(itemManager.canonicalize(itemId));
				if (perHour >= 0)
				{
					p.getChildren().add(LineComponent.builder()
						.left("Trades on the GE: about " + QuantityFormatter.formatNumber(perHour) + " an hour")
						.leftColor(MUTED)
						.build());
				}
				p.getChildren().add(LineComponent.builder()
					.left("GE: " + itemValuator.getGePriceDescription() + ", after tax")
					.leftColor(MUTED)
					.build());
			}
		}
		return p;
	}

	private static LineComponent line(String left, String right, Color rightColor)
	{
		return LineComponent.builder().left(left).leftColor(NORMAL).right(right).rightColor(rightColor).build();
	}

	/** The shop's name from its window title. */
	private String shopTitle()
	{
		Widget frame = client.getWidget(InterfaceID.Shopmain.FRAME);
		String t = firstText(frame);
		return t == null ? "" : t;
	}

	private static String firstText(Widget w)
	{
		if (w == null)
		{
			return null;
		}
		if (w.getText() != null && !Text.removeTags(w.getText()).trim().isEmpty())
		{
			return Text.removeTags(w.getText()).trim();
		}
		for (Widget[] children : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (children != null)
			{
				for (Widget c : children)
				{
					String t = firstText(c);
					if (t != null)
					{
						return t;
					}
				}
			}
		}
		return null;
	}
}

package com.assetmanager.flip;

import com.assetmanager.shop.Shop;
import lombok.Value;

/** A shop's usual rates, in tenths of a percent of an item's value. */
@Value
public class ShopRates
{
	int sell;
	int buy;
	int delta;
	/** Whether some items have rates of their own. */
	boolean varies;
	/** Whether the rates include the player's Karamja gloves. */
	boolean gloves;

	public static ShopRates of(Shop shop, boolean hasGloves)
	{
		int sell = shop.getSellMultiplier();
		int buy = shop.getBuyMultiplier();
		boolean varies = false;
		Integer glovesSell = null;
		Integer glovesBuy = hasGloves ? shop.getGlovesBuyMultiplier() : null;
		for (Shop.Item item : shop.getItems().values())
		{
			varies |= item.getM() != null || item.getSm() != null || item.getD() != null;
			if (hasGloves)
			{
				if (glovesSell == null && item.getGs() != null)
				{
					glovesSell = item.getGs();
				}
				if (glovesBuy == null && item.getG() != null)
				{
					glovesBuy = item.getG();
				}
			}
		}
		boolean usesGloves = glovesSell != null || glovesBuy != null;
		return new ShopRates(
			glovesSell != null ? glovesSell : sell,
			glovesBuy != null && buy > 0 ? glovesBuy : buy,
			shop.getDelta(), varies, usesGloves);
	}
}

package com.assetmanager.flip;

import com.assetmanager.AssetManagerConfig;
import com.assetmanager.shop.Shop;
import com.assetmanager.shop.ShopStock;
import com.assetmanager.shop.ShopStockTracker;
import com.assetmanager.shop.ShopTimes;
import com.assetmanager.ui.PriceTooltip;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Shows the open shop's rates under its window: what it sells for, what it buys for and how much the price
 * changes per item of stock, as a percentage of each item's value. Also which items are overstocked on this world
 * and how long until they're back to normal.
 */
@Singleton
public class ShopRatesOverlay extends Overlay
{
	private static final Color TITLE = new Color(0xFF9800);
	private static final Color NORMAL = new Color(0xEEEEEE);
	private static final Color MUTED = new Color(0x9E9E9E);
	private static final int WIDTH = 170;

	private final Client client;
	private final ShopFlipper flipper;
	private final AssetManagerConfig config;
	private final ShopStockTracker stockTracker;
	private final PanelComponent panel = new PanelComponent();
	private int lastHeight;

	@Inject
	ShopRatesOverlay(Client client, ShopFlipper flipper, AssetManagerConfig config, ShopStockTracker stockTracker)
	{
		this.stockTracker = stockTracker;
		this.client = client;
		this.flipper = flipper;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panel.setBackgroundColor(PriceTooltip.SOLID_BACKGROUND);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Shop shop = flipper.getOpenShop();
		Widget frame = client.getWidget(InterfaceID.Shopmain.FRAME);
		if (shop == null || frame == null || frame.isHidden())
		{
			return null;
		}
		panel.getChildren().clear();
		Rectangle b = frame.getBounds();
		// As wide as the shop so notes wrap less and the panel stays short
		panel.setPreferredSize(new Dimension(Math.max(WIDTH, b.width), 0));
		if (config.shopRates())
		{
			addRates(shop);
		}
		addRestock(shop);
		if (panel.getChildren().isEmpty())
		{
			return null;
		}

		// Just below the shop window, or above it if there's no room. If neither fits, sit at the bottom of the
		// screen so it only covers the bottom of the shop, never the items at the top.
		int canvasHeight = client.getCanvasHeight();
		int y = b.y + b.height + 4;
		if (y + lastHeight > canvasHeight)
		{
			y = b.y - lastHeight - 4;
			if (y < 0)
			{
				y = Math.max(0, canvasHeight - lastHeight);
			}
		}
		panel.setPreferredLocation(new Point(b.x, y));
		Dimension d = panel.render(g);
		if (d != null)
		{
			lastHeight = d.height;
		}
		return null;
	}

	/** Items overstocked on this world and when they're back to normal, and items others are overstocking everywhere. */
	private void addRestock(Shop shop)
	{
		long now = System.currentTimeMillis();
		ShopStock stock = stockTracker.get();
		boolean titled = false;
		for (ShopStock.Seen s : stock.overstocked(shop.getName(), now))
		{
			if (s.getWorld() == client.getWorld())
			{
				if (!titled)
				{
					panel.getChildren().add(TitleComponent.builder().text("Overstocked on this world").color(TITLE).build());
					titled = true;
				}
				panel.getChildren().add(line(ShopTimes.itemName(s.getItem()) + " +" + s.getOverstock(),
					(s.isExact() ? "" : "up to ") + ShopTimes.duration(s.getNormalAt() - now)));
			}
		}
		if (titled)
		{
			panel.getChildren().add(note("Time until back to normal stock. It's exact once you've seen one restock here."));
		}
		StringBuilder busyItems = new StringBuilder();
		for (ShopStock.Busy busy : stock.busy(now))
		{
			if (busy.getShop().equals(shop.getName()))
			{
				busyItems.append(busyItems.length() == 0 ? "" : ", ")
					.append(ShopTimes.itemName(busy.getItem())).append(" (").append(busy.getWorlds()).append(")");
			}
		}
		if (busyItems.length() > 0)
		{
			panel.getChildren().add(note("Others overstocked on worlds you checked: " + busyItems));
		}
	}

	private void addRates(Shop shop)
	{
		boolean gloves = shop.getGlovesTier() != null && flipper.getOpenShopGlovesTier() >= shop.getGlovesTier();
		ShopRates rates = ShopRates.of(shop, gloves);

		panel.getChildren().add(TitleComponent.builder().text(shop.getName()).color(TITLE).build());
		panel.getChildren().add(line("Sells for", rates.getSell() > 0 ? percent(rates.getSell()) : "doesn't sell"));
		panel.getChildren().add(line("Buys for", rates.getBuy() > 0 ? percent(rates.getBuy()) : "doesn't buy"));
		panel.getChildren().add(line("Change per item", percent(rates.getDelta())));
		if (shop.isGeneral() && rates.getBuy() > 0)
		{
			panel.getChildren().add(note("Buys any tradeable item"));
		}
		if (rates.isVaries())
		{
			panel.getChildren().add(note("Some items have their own rates"));
		}
		if (rates.isGloves())
		{
			panel.getChildren().add(note("With your Karamja gloves"));
		}
		else if (shop.getGlovesTier() != null)
		{
			panel.getChildren().add(note("Better with Karamja gloves " + shop.getGlovesTier() + "+"));
		}
	}

	private static LineComponent line(String left, String right)
	{
		return LineComponent.builder().left(left).leftColor(NORMAL).right(right).rightColor(NORMAL).build();
	}

	private static LineComponent note(String text)
	{
		return LineComponent.builder().left(text).leftColor(MUTED).build();
	}

	/** 1305 tenths of a percent -> "130.5%" (or "130%" when whole). */
	static String percent(int tenths)
	{
		return tenths % 10 == 0 ? (tenths / 10) + "%" : (tenths / 10) + "." + Math.abs(tenths % 10) + "%";
	}
}

package com.assetmanager.keep;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.QuantityFormatter;

/**
 * On the GE's offer screen, when a sell offer's quantity would dip into the items the player is keeping: greys out
 * the Confirm button (its click is blocked by {@link KeepGuard}), outlines the "..." quantity button and says how
 * many to enter.
 */
@Singleton
public class GeKeepOverlay extends Overlay
{
	private static final Color WARN = new Color(0xFF9800);
	private static final Color BLOCKED = new Color(0xF44336);
	private static final String ENTER_QUANTITY = "Enter quantity";

	private final Client client;
	private final KeepGuard guard;

	@Inject
	GeKeepOverlay(Client client, KeepGuard guard)
	{
		this.client = client;
		this.guard = guard;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		KeepGuard.GeSale sale = guard.geSale();
		if (sale == null || !sale.isTooMany())
		{
			return null;
		}
		g.setFont(FontManager.getRunescapeSmallFont());

		Widget confirm = client.getWidget(InterfaceID.GeOffers.SETUP_CONFIRM);
		if (confirm != null && !confirm.isHidden())
		{
			Rectangle b = confirm.getBounds();
			Composite old = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.6f));
			g.setColor(Color.BLACK);
			g.fill(b);
			g.setComposite(old);
			g.setColor(BLOCKED);
			g.setStroke(new BasicStroke(2));
			g.draw(b);
			centered(g, "Keeping " + (sale.getKeep() == KeepRules.KEEP_ALL ? "all" : QuantityFormatter.formatNumber(sale.getKeep())), b, BLOCKED);

			String warning = sale.getCanSell() == 0
				? "You're keeping " + sale.keeping() + "."
				: "You're keeping " + sale.keeping() + ": sell " + QuantityFormatter.formatNumber(sale.getCanSell()) + " at most.";
			label(g, warning, b.x + b.width / 2, b.y - 6, BLOCKED);
		}

		Widget dots = sale.getCanSell() > 0 ? findAction(client.getWidget(InterfaceID.GeOffers.SETUP), ENTER_QUANTITY) : null;
		if (dots != null)
		{
			Rectangle b = dots.getBounds();
			g.setColor(WARN);
			g.setStroke(new BasicStroke(2));
			g.drawRect(b.x - 1, b.y - 1, b.width + 2, b.height + 2);
			label(g, "Enter " + QuantityFormatter.formatNumber(sale.getCanSell()), b.x + b.width / 2, b.y - 4, WARN);
		}
		return null;
	}

	/** The first visible widget under {@code w} with the given menu action. */
	private static Widget findAction(Widget w, String action)
	{
		if (w == null || w.isHidden())
		{
			return null;
		}
		String[] actions = w.getActions();
		if (actions != null)
		{
			for (String a : actions)
			{
				if (a != null && a.equalsIgnoreCase(action))
				{
					return w;
				}
			}
		}
		for (Widget[] children : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (children != null)
			{
				for (Widget c : children)
				{
					Widget found = findAction(c, action);
					if (found != null)
					{
						return found;
					}
				}
			}
		}
		return null;
	}

	private static void centered(Graphics2D g, String text, Rectangle b, Color color)
	{
		FontMetrics fm = g.getFontMetrics();
		shadowed(g, text, b.x + (b.width - fm.stringWidth(text)) / 2, b.y + (b.height + fm.getAscent()) / 2 - 1, color);
	}

	/** Text centered on x with its baseline at y. */
	private static void label(Graphics2D g, String text, int x, int y, Color color)
	{
		shadowed(g, text, x - g.getFontMetrics().stringWidth(text) / 2, y, color);
	}

	private static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.assetmanager.keep;

import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Where the player's items are, by canonical item id, and which of them are spare after their keep rules.
 * <p>
 * Kept items are counted from what's worn first, then the bank and the seed vault, and the inventory last: what the
 * player carries to a shop or the GE is what they mean to sell, so keeping 5 lobsters with 5 in the bank leaves all
 * the carried ones spare. Worn items are never spare. Variants
 * with different doses or charges count together, the fullest kept first.
 */
public class Holdings
{
	@Getter
	@RequiredArgsConstructor
	public enum Place
	{
		WORN("worn"),
		INVENTORY("inventory"),
		BANK("bank"),
		SEED_VAULT("seed vault");

		private final String displayName;
	}

	public static final Holdings NONE = new Holdings();

	/** The order kept items are counted from: the carried ones are the first to be spare. */
	private static final Place[] KEEP_ORDER = {Place.WORN, Place.BANK, Place.SEED_VAULT, Place.INVENTORY};

	private final Map<Place, Map<Integer, Integer>> counts = new EnumMap<>(Place.class);

	/** Adds a place's items; null (not seen yet) adds nothing. */
	public Holdings with(Place place, Map<Integer, Integer> items)
	{
		if (items != null)
		{
			counts.put(place, Collections.unmodifiableMap(new LinkedHashMap<>(items)));
		}
		return this;
	}

	public boolean has(Place place)
	{
		return counts.containsKey(place);
	}

	public int count(Place place, int itemId)
	{
		return counts.getOrDefault(place, Collections.emptyMap()).getOrDefault(itemId, 0);
	}

	/** How many the player has everywhere. */
	public int total(int itemId)
	{
		int n = 0;
		for (Place p : Place.values())
		{
			n += count(p, itemId);
		}
		return n;
	}

	/** Every item held anywhere, worn included. */
	public Set<Integer> allItemIds()
	{
		Set<Integer> ids = new LinkedHashSet<>();
		counts.values().forEach(items -> ids.addAll(items.keySet()));
		return ids;
	}

	/** Every item held anywhere that could be spare (not just worn). */
	public Set<Integer> itemIds()
	{
		Set<Integer> ids = new LinkedHashSet<>();
		counts.forEach((place, items) ->
		{
			if (place != Place.WORN)
			{
				ids.addAll(items.keySet());
			}
		});
		return ids;
	}

	/** How many of an item and its variants the player has everywhere. */
	public int total(int itemId, KeepRules rules)
	{
		int n = 0;
		for (int id : rules.members(itemId))
		{
			n += total(id);
		}
		return n;
	}

	/**
	 * How many at a place are spare. Variants share their rule: the ones with the most doses or charges are kept first,
	 * each from what's worn first, then the bank, the seed vault and the inventory.
	 */
	public int spare(Place place, int itemId, KeepRules rules)
	{
		int keep = rules.get(itemId);
		if (place == Place.WORN || keep == KeepRules.KEEP_ALL)
		{
			return 0;
		}
		int toKeep = keep;
		for (int id : rules.members(itemId))
		{
			for (Place p : KEEP_ORDER)
			{
				int here = count(p, id);
				int kept = Math.min(here, toKeep);
				toKeep -= kept;
				if (id == itemId && p == place)
				{
					return here - kept;
				}
			}
		}
		return count(place, itemId);
	}

	/** Spare quantity of each item, everywhere together. */
	public Map<Integer, Integer> spare(KeepRules rules)
	{
		Map<Integer, Integer> out = new LinkedHashMap<>();
		for (int id : itemIds())
		{
			int n = 0;
			for (Place p : Place.values())
			{
				n += spare(p, id, rules);
			}
			if (n > 0)
			{
				out.put(id, n);
			}
		}
		return out;
	}

	/** Spare items that aren't in the bank, by where they are, for "3 more in your seed vault" notes. */
	public Map<Place, Integer> spareOutsideBank(int itemId, KeepRules rules)
	{
		Map<Place, Integer> out = new EnumMap<>(Place.class);
		for (Place p : new Place[]{Place.INVENTORY, Place.SEED_VAULT})
		{
			int n = spare(p, itemId, rules);
			if (n > 0)
			{
				out.put(p, n);
			}
		}
		return out;
	}
}

package com.assetmanager.keep;

import com.assetmanager.AssetManagerConfig;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import lombok.Value;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.util.Text;

/**
 * Stops the player from alching, selling to a shop or selling on the GE the items they've said to keep.
 * The click is cancelled with a chat message; nothing is sent to the game.
 * <p>
 * On the GE the quantity is chosen after picking the item, so a sell offer's Confirm is blocked while its
 * quantity would dip into the kept ones; {@link GeKeepOverlay} shows why and how many to enter.
 */
@Singleton
public class KeepGuard
{
	private static final Pattern ALCHEMY = Pattern.compile("^(High|Low) Level Alchemy\\b");
	private static final Pattern SHOP_SELL = Pattern.compile("^Sell (\\d+)$");
	/** GE_NEWOFFER_TYPE for a sell offer. */
	private static final int GE_SELL = 1;

	/** A GE sell offer being set up for an item with a keep rule. */
	@Value
	public static class GeSale
	{
		String name;
		/** How many are being kept, or KeepRules.KEEP_ALL. */
		int keep;
		/** The most that can be sold while keeping them. */
		int canSell;
		/** The quantity entered in the offer. */
		int quantity;

		public boolean isTooMany()
		{
			return quantity > canSell;
		}

		public String keeping()
		{
			return keep == KeepRules.KEEP_ALL ? "all your " + name : QuantityFormatter.formatNumber(keep) + " x " + name;
		}
	}

	private final Client client;
	private final ItemManager itemManager;
	private final AssetManagerConfig config;

	@Setter
	private volatile KeepRules rules = new KeepRules();
	/** Where the player's items are; the inventory and equipment are read live. */
	@Setter
	private volatile Holdings holdings = Holdings.NONE;

	@Inject
	KeepGuard(Client client, ItemManager itemManager, AssetManagerConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.protectKept())
		{
			return;
		}
		String option = Text.removeTags(event.getMenuOption());
		String target = Text.removeTags(event.getMenuTarget());
		int component = event.getParam1();
		String verb;
		int removing;
		Matcher sell = SHOP_SELL.matcher(option);
		if ("Cast".equals(option) && ALCHEMY.matcher(target).find() && component == InterfaceID.Inventory.ITEMS)
		{
			verb = "alch";
			removing = 1;
		}
		else if (sell.matches() && component == InterfaceID.Shopside.ITEMS)
		{
			verb = "sell";
			removing = Integer.parseInt(sell.group(1));
		}
		else if ("Offer".equals(option) && component == InterfaceID.GeOffersSide.ITEMS)
		{
			verb = "offer";
			removing = 1;
		}
		else if ("Confirm".equals(option) && component >>> 16 == InterfaceID.GeOffers.SETUP >>> 16)
		{
			GeSale sale = geSale();
			if (sale != null && sale.isTooMany())
			{
				event.consume();
				chat("Blocked: you're keeping " + sale.keeping() + "."
					+ (sale.getCanSell() > 0 ? " Enter " + QuantityFormatter.formatNumber(sale.getCanSell()) + " or fewer." : "")
					+ " Change it with Keep in the bank.");
			}
			return;
		}
		else
		{
			return;
		}

		int itemId = itemId(event);
		if (itemId <= 0)
		{
			return;
		}
		int canonical = itemManager.canonicalize(itemId);
		KeepRules r = rules;
		int keep = r.get(canonical);
		if (keep == 0)
		{
			return;
		}
		removing = Math.min(removing, count(InventoryID.INV, canonical));
		int owned = owned(r, canonical);
		int canPart = r.canPart(canonical, owned);
		String name = name(r, canonical);
		String keeping = keep == KeepRules.KEEP_ALL ? "all your " + name : QuantityFormatter.formatNumber(keep) + " x " + name;

		if (removing > canPart)
		{
			event.consume();
			String allowed = canPart == 0 ? "" : " You can " + verb + " " + QuantityFormatter.formatNumber(canPart) + " more.";
			chat("Blocked: you're keeping " + keeping + "." + allowed + " Change it with Keep in the bank.");
		}
	}

	/** The GE sell offer being set up, if it's for an item with a keep rule; null otherwise. */
	public GeSale geSale()
	{
		if (!config.protectKept())
		{
			return null;
		}
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (setup == null || setup.isHidden() || client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) != GE_SELL)
		{
			return null;
		}
		int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (itemId <= 0)
		{
			return null;
		}
		int canonical = itemManager.canonicalize(itemId);
		KeepRules r = rules;
		int keep = r.get(canonical);
		if (keep == 0)
		{
			return null;
		}
		int owned = owned(r, canonical);
		return new GeSale(name(r, canonical), keep, r.canPart(canonical, owned),
			client.getVarbitValue(VarbitID.GE_NEWOFFER_QUANTITY));
	}

	private int itemId(MenuOptionClicked event)
	{
		if (event.getItemId() > 0)
		{
			return event.getItemId();
		}
		Widget w = event.getWidget();
		return w == null ? -1 : w.getItemId();
	}

	/** The item's name, or the name all its variants share. */
	private String name(KeepRules r, int canonical)
	{
		String name = itemManager.getItemComposition(canonical).getName();
		return r.members(canonical).size() > 1 ? Variants.base(name) : name;
	}

	/** How many of an item and its variants the player has: worn, carried and stored away. */
	private int owned(KeepRules r, int canonical)
	{
		int n = 0;
		for (int id : r.members(canonical))
		{
			n += count(InventoryID.INV, id) + count(InventoryID.WORN, id) + inBank(id);
		}
		return n;
	}

	/** How many are stored away: in the bank and the seed vault. */
	private int inBank(int canonical)
	{
		Holdings h = holdings;
		return h.count(Holdings.Place.BANK, canonical) + h.count(Holdings.Place.SEED_VAULT, canonical);
	}

	private int count(int containerId, int canonical)
	{
		ItemContainer c = client.getItemContainer(containerId);
		if (c == null)
		{
			return 0;
		}
		int n = 0;
		for (Item i : c.getItems())
		{
			if (i.getId() > 0 && itemManager.canonicalize(i.getId()) == canonical)
			{
				n += i.getQuantity();
			}
		}
		return n;
	}

	private void chat(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Asset Manager: ").append(ChatColorType.NORMAL).append(message).build(), null);
	}
}

package com.assetmanager.keep;

import java.math.BigDecimal;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * How many of each item the player wants to hold on to. Asset Manager only suggests doing something
 * with the rest. Keyed by canonical item id.
 * <p>
 * Variants of an item with different doses or charges (see {@link Variants}) share one rule, stored under one of
 * them: keeping 4 prayer potions keeps any 4, the ones with the most doses first.
 */
public class KeepRules
{
	private static final Pattern AMOUNT = Pattern.compile("(\\d+(?:\\.\\d+)?)([kmb])?");

	/** Keep every one of this item: never suggest it. */
	public static final int KEEP_ALL = -1;

	private final Map<Integer, Integer> rules = new LinkedHashMap<>();
	/** Each variant's group, most doses or charges first; items with no variants aren't in it. */
	private Map<Integer, List<Integer>> variants = Collections.emptyMap();

	/** The items sharing a rule with this one, most doses or charges first: just itself if it has no variants. */
	public List<Integer> members(int itemId)
	{
		return variants.getOrDefault(itemId, Collections.singletonList(itemId));
	}

	/** The id an item's rule is stored under. */
	private int ruleId(int itemId)
	{
		for (int id : members(itemId))
		{
			if (rules.containsKey(id))
			{
				return id;
			}
		}
		return itemId;
	}

	/**
	 * Sets which items are variants of each other. Variants that had rules of their own are merged into one, keeping
	 * the most any of them kept.
	 *
	 * @return whether rules were merged
	 */
	public boolean setVariants(Map<Integer, List<Integer>> groups)
	{
		variants = groups;
		boolean merged = false;
		for (List<Integer> group : new HashSet<>(groups.values()))
		{
			int keep = 0;
			int kept = -1;
			for (int id : group)
			{
				Integer k = rules.get(id);
				if (k == null)
				{
					continue;
				}
				if (kept >= 0)
				{
					rules.remove(id);
					merged = true;
				}
				else
				{
					kept = id;
				}
				keep = keep == KEEP_ALL || k == KEEP_ALL ? KEEP_ALL : Math.max(keep, k);
			}
			if (kept >= 0)
			{
				rules.put(kept, keep);
			}
		}
		return merged;
	}

	/** How many to keep, 0 if there's no rule. */
	public int get(int itemId)
	{
		return rules.getOrDefault(ruleId(itemId), 0);
	}

	public boolean has(int itemId)
	{
		return rules.containsKey(ruleId(itemId));
	}

	/** Sets how many to keep; 0 removes the rule. */
	public void set(int itemId, int keep)
	{
		int id = ruleId(itemId);
		if (keep == 0)
		{
			rules.remove(id);
		}
		else
		{
			rules.put(id, keep < 0 ? KEEP_ALL : keep);
		}
	}

	public Map<Integer, Integer> asMap()
	{
		return Collections.unmodifiableMap(rules);
	}

	/** Quantity left over after keeping what the rule says. */
	public int spare(int itemId, int quantity)
	{
		int keep = get(itemId);
		return keep == KEEP_ALL ? 0 : Math.max(0, quantity - keep);
	}

	/**
	 * How many of an item can go while still keeping what the rule says.
	 *
	 * @param owned how many the player has in total, of all its variants
	 */
	public int canPart(int itemId, int owned)
	{
		int keep = get(itemId);
		return keep == KEEP_ALL ? 0 : Math.max(0, owned - keep);
	}

	/** Spare quantities for every item in the map. */
	public Map<Integer, Integer> spare(Map<Integer, Integer> quantities)
	{
		Map<Integer, Integer> out = new LinkedHashMap<>();
		quantities.forEach((id, qty) -> out.put(id, spare(id, qty)));
		return out;
	}

	/** Stored as "id:keep,id:keep", with -1 meaning keep all. */
	public String encode()
	{
		return rules.entrySet().stream().map(e -> e.getKey() + ":" + e.getValue()).collect(Collectors.joining(","));
	}

	public static KeepRules decode(String s)
	{
		KeepRules r = new KeepRules();
		if (s == null || s.isEmpty())
		{
			return r;
		}
		for (String entry : s.split(","))
		{
			String[] parts = entry.split(":");
			if (parts.length != 2)
			{
				continue;
			}
			try
			{
				r.set(Integer.parseInt(parts[0].trim()), Integer.parseInt(parts[1].trim()));
			}
			catch (NumberFormatException ignored)
			{
				// skip a corrupt entry rather than losing the rest
			}
		}
		return r;
	}

	/**
	 * Parses what the player typed: a number, optionally with k, m or b like the game's quantity prompts
	 * ("10k", "1.5m"), or "all". Blank or 0 removes the rule.
	 *
	 * @return the keep amount, or null if it isn't valid
	 */
	public static Integer parseInput(String input)
	{
		String s = input == null ? "" : input.trim().toLowerCase().replace(",", "").replace(" ", "");
		if (s.isEmpty())
		{
			return 0;
		}
		if (s.equals("all") || s.equals("a"))
		{
			return KEEP_ALL;
		}
		Matcher m = AMOUNT.matcher(s);
		if (!m.matches())
		{
			return null;
		}
		BigDecimal n = new BigDecimal(m.group(1));
		if (m.group(2) != null)
		{
			n = n.multiply(BigDecimal.TEN.pow("kmb".indexOf(m.group(2)) * 3 + 3));
		}
		// Whole items only, and no more than a stack can hold
		if (n.stripTrailingZeros().scale() > 0 || n.compareTo(BigDecimal.valueOf(Integer.MAX_VALUE)) > 0)
		{
			return null;
		}
		return n.intValue();
	}
}

package com.assetmanager.keep;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Items that are the same thing with a different number of doses or charges, like Prayer potion(4) to (1), or
 * Amulet of glory(6) to the uncharged Amulet of glory. Trimmed and other lettered versions, like Amulet of glory(t6),
 * are their own group.
 */
public final class Variants
{
	/** "Prayer potion(4)", "Amulet of glory(t6)", "Black mask (10)". */
	private static final Pattern NUMBERED = Pattern.compile("^(.*?)\\s*\\(([a-z]*)(\\d+)\\)$", Pattern.CASE_INSENSITIVE);

	private Variants()
	{
	}

	/** The name shared by every variant: "Prayer potion", "Amulet of glory(t)". */
	public static String base(String name)
	{
		Matcher m = NUMBERED.matcher(name.trim());
		if (!m.matches())
		{
			return name.trim();
		}
		return m.group(2).isEmpty() ? m.group(1) : m.group(1) + "(" + m.group(2) + ")";
	}

	/** Doses or charges, from the name; 0 for none (an uncharged amulet). */
	static int number(String name)
	{
		Matcher m = NUMBERED.matcher(name.trim());
		return m.matches() ? Integer.parseInt(m.group(3)) : 0;
	}

	/**
	 * Groups items by their shared name. Each group lists its items with the most doses or charges first, which are the
	 * ones kept first; items with no other variants aren't included.
	 *
	 * @param names item names by id
	 */
	public static Map<Integer, List<Integer>> group(Map<Integer, String> names)
	{
		Map<String, List<Integer>> byBase = new HashMap<>();
		names.forEach((id, name) -> byBase.computeIfAbsent(base(name).toLowerCase(), k -> new ArrayList<>()).add(id));
		Map<Integer, List<Integer>> out = new HashMap<>();
		for (List<Integer> ids : byBase.values())
		{
			if (ids.size() < 2)
			{
				continue;
			}
			ids.sort(Comparator.comparingInt((Integer id) -> number(names.get(id))).reversed().thenComparing(id -> id));
			List<Integer> members = Collections.unmodifiableList(ids);
			for (int id : ids)
			{
				out.put(id, members);
			}
		}
		return out;
	}
}

package com.assetmanager.shop;

import com.assetmanager.AssetManagerConfig;
import java.util.Map;
import java.util.function.Supplier;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/**
 * Stops the player selling for less than they could because they forgot to put something on: selling to a shop
 * that pays more with Karamja gloves they own but aren't wearing, or talking to Baraek or Fritz with furs or molten
 * glass while their activated Ring of Charos is in the bank. The first click is cancelled with a chat message;
 * clicking again soon after goes ahead. Nothing is sent to the game.
 */
@Singleton
public class PerkGuard
{
	private static final Pattern SHOP_SELL = Pattern.compile("^Sell \\d+$");
	/** A second click within this long goes ahead. */
	private static final long OVERRIDE_MILLIS = 10_000;
	/** NPCs who pay more with an activated Ring of Charos, and the shop data they're in. */
	private static final Map<String, String> CHAROS_TRADERS = Map.of("Baraek", "Baraek", "Fritz", "Fritz the Glassblower");

	private final Client client;
	private final ItemManager itemManager;
	private final AssetManagerConfig config;

	@Setter
	private volatile ShopCatalog shops;
	/** The open shop, from the shop window's title. */
	@Setter
	private volatile Supplier<Shop> openShop = () -> null;
	/** Karamja gloves tier the player has earned (0 for none). */
	@Setter
	private volatile int glovesTier;
	/** Whether the player owns an activated Ring of Charos. */
	@Setter
	private volatile boolean charos;

	private String lastBlocked;
	private long lastBlockedAt;

	@Inject
	PerkGuard(Client client, ItemManager itemManager, AssetManagerConfig config)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.config = config;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!config.wearShopPerks())
		{
			return;
		}
		String option = Text.removeTags(event.getMenuOption());
		String target = Text.removeTags(event.getMenuTarget());
		String warning = null;
		if (SHOP_SELL.matcher(option).matches() && event.getParam1() == InterfaceID.Shopside.ITEMS)
		{
			warning = glovesWarning(event.getItemId());
		}
		else if ("Talk-to".equals(option) && CHAROS_TRADERS.containsKey(target))
		{
			warning = charosWarning(CHAROS_TRADERS.get(target));
		}
		if (warning == null)
		{
			return;
		}
		// Clicking the same thing again soon after means they want to go ahead anyway
		String what = option + "|" + target;
		long now = System.currentTimeMillis();
		if (what.equals(lastBlocked) && now - lastBlockedAt < OVERRIDE_MILLIS)
		{
			lastBlocked = null;
			return;
		}
		lastBlocked = what;
		lastBlockedAt = now;
		event.consume();
		chat(warning + " Click again to go ahead anyway.");
	}

	private String glovesWarning(int itemId)
	{
		Shop shop = openShop.get();
		if (shop == null || shop.getGlovesTier() == null || itemId <= 0)
		{
			return null;
		}
		int needed = shop.getGlovesTier();
		if (glovesTier < needed || wornGlovesTier() >= needed)
		{
			return null;
		}
		String name = itemManager.getItemComposition(itemManager.canonicalize(itemId)).getName();
		Shop.Item item = shop.getItems().get(name.toLowerCase());
		Integer with = item != null ? item.getG() : shop.isGeneral() ? shop.getGlovesBuyMultiplier() : null;
		if (with == null)
		{
			return null;
		}
		int without = item != null && item.getM() != null ? item.getM() : shop.getBuyMultiplier();
		return "Put on your Karamja gloves " + (needed >= 3 ? "3 or 4" : "") + " first: " + shop.getName() + " pays "
			+ with / 10 + "% for " + name + " with them, " + without / 10 + "% without.";
	}

	private String charosWarning(String shopName)
	{
		if (!charos || isWorn(ItemID.RING_OF_CHAROS_UNLOCKED) || shops == null)
		{
			return null;
		}
		Shop shop = shops.findByName(shopName);
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (shop == null || inv == null)
		{
			return null;
		}
		for (Item i : inv.getItems())
		{
			if (i.getId() <= 0)
			{
				continue;
			}
			String name = itemManager.getItemComposition(itemManager.canonicalize(i.getId())).getName();
			Shop.Item item = shop.getItems().get(name.toLowerCase());
			if (item != null && (item.getCp() != null || item.getCm() != null))
			{
				return "Put on your Ring of Charos (a) first: " + shopName + " pays more for " + name + " with it.";
			}
		}
		return null;
	}

	/** 1 for Karamja gloves 1 or 2, 3 for 3 or 4, 0 for none. */
	private int wornGlovesTier()
	{
		if (isWorn(ItemID.ATJUN_GLOVES_HARD) || isWorn(ItemID.ATJUN_GLOVES_ELITE))
		{
			return 3;
		}
		return isWorn(ItemID.ATJUN_GLOVES_EASY) || isWorn(ItemID.ATJUN_GLOVES_MED) ? 1 : 0;
	}

	private boolean isWorn(int itemId)
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		return worn != null && worn.contains(itemId);
	}

	private void chat(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Asset Manager: ").append(ChatColorType.NORMAL).append(message).build(), null);
	}
}

package com.assetmanager.shop;

import lombok.Value;

/** When selling to a shop is worth it, from the player's settings. */
@Value
public class SellRules
{
	/** Each sale must beat the next best way to cash out (GE or alching) by this much. */
	int minGainPerItem;
	/** The most worlds to hop at one shop, or ShopCatalog.NO_WORLD_LIMIT. */
	int maxWorlds;
	/**
	 * A shop is only suggested if everything to sell there gains at least this much for each world visited: hopping
	 * takes time, and alching or the GE doesn't need it.
	 */
	int minGainPerWorld;
}

package com.assetmanager.shop;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Data;
import net.runelite.api.coords.WorldPoint;

/**
 * A shop that trades items for coins, as stored in shops.json (generated by tools/update_shop_data.py).
 * Rates are in tenths of a percent: a buyMultiplier of 600 means the shop pays 60% of the item's value.
 * Each item of stock below normal raises both prices by delta; each item above normal lowers them.
 */
@Data
public class Shop
{
	/**
	 * What a player needs to buy from a shop (or a particular item in it), from tools/shop_requirements.json.
	 * Skills, quests and diaries use RuneLite's enum names ("HUNTER", "THE_SLUG_MENACE", "KARAMJA_EASY").
	 */
	@Data
	public static class Requirements
	{
		/** Minimum real level in each skill. */
		private Map<String, Integer> skills = Collections.emptyMap();
		/** Quests that must be finished. */
		private List<String> quests = Collections.emptyList();
		/** Quests that must at least be started. */
		private List<String> started = Collections.emptyList();
		/** Achievement diaries that must be finished, as AREA_TIER. */
		private List<String> diaries = Collections.emptyList();
		private int combat;
		private int questPoints;
		/** Requirements the plugin can't check, in plain English. */
		private List<String> other = Collections.emptyList();
	}

	@Data
	public static class Item
	{
		/** The shop's normal stock, or -1 if it never runs out. */
		private int s;
		/** Buy rate for this item if it differs from the shop's. */
		private Integer m;
		/** Sell rate for this item if it differs from the shop's. */
		private Integer sm;
		/** Change in rate per item of stock above/below normal, if it differs from the shop's. */
		private Integer d;
		/** Buy rate with Karamja gloves, if they help here. */
		private Integer g;
		/** Sell rate with Karamja gloves, if they help here. */
		private Integer gs;
		/** Coins paid per item by traders with a fixed price (like Baraek), instead of a % of value. */
		private Integer p;
		/** Fixed price with an activated Ring of Charos. */
		private Integer cp;
		/** Buy rate with an activated Ring of Charos. */
		private Integer cm;
		/** Ticks for the stock to move one back towards normal, if known. */
		private Integer r;
		/** The item's id, for tradeable items. */
		private Integer id;
		/** What the shop charges at normal stock, when it's a set price rather than the usual % of value. */
		private Integer sp;
		/** A deal for several at once, as [how many, coins], when it's cheaper than one at a time (Wyson's 2 woad leaves for 20). */
		private int[] b;
		/** Requirements for this item on top of the shop's. */
		private Requirements req;
		/** The shop sells this but won't buy it. */
		private boolean nb;
		/** The shop buys this but doesn't sell it. */
		private boolean ns;

		public boolean isInfinite()
		{
			return s < 0;
		}
	}

	private String name;
	private String location;
	/** What kind of shop it is, from the wiki ("General store", "Farming shop"); null if unknown. */
	private String type;
	/**
	 * The shops paying exactly the same as this one share a group, named for the kind of shop ("General store"): any
	 * of them will do. Set by ShopCatalog; not part of the data file.
	 */
	private transient String group;
	private boolean members;
	/** In the Wilderness, where the player can be attacked by other players. */
	private boolean wilderness;
	/** General stores buy any tradeable item; other shops only buy what they stock. */
	private boolean general;
	/** What the shop pays, or 0 if it doesn't buy anything. */
	private int buyMultiplier;
	/** What the shop charges at its normal stock. */
	private int sellMultiplier;
	private int delta;
	/** Karamja gloves tier that improves this shop's rates (1 or 3), or null. */
	private Integer glovesTier;
	/** General store rate for unstocked items with Karamja gloves. */
	private Integer glovesBuyMultiplier;
	/** Map coordinates [x, y] of each branch of the shop; empty if unknown. */
	private int[][] at = new int[0][];
	/**
	 * The NPC to talk to for the shop's items, when there's no Trade option (a pub's bartender); null for a normal shop.
	 * Some of these sell only one per conversation.
	 */
	private String talk;
	/** What a player needs to use the shop, or null if nothing. */
	private Requirements req;
	/** Stocked items, by lower-case name. */
	private Map<String, Item> items = Collections.emptyMap();

	/** Underground areas are this far north of the surface above them. */
	private static final int UNDERGROUND_OFFSET = 6400;

	/**
	 * Roughly how far the nearest branch is from a point, in tiles, as the crow flies (so teleports aren't
	 * considered). Underground spots count as the surface above them. Integer.MAX_VALUE if unknown.
	 */
	public int distanceTo(WorldPoint from)
	{
		if (from == null || at == null)
		{
			return Integer.MAX_VALUE;
		}
		int best = Integer.MAX_VALUE;
		for (int[] p : at)
		{
			if (p != null && p.length >= 2)
			{
				int dx = p[0] - from.getX();
				int dy = surfaceY(p[1]) - surfaceY(from.getY());
				best = Math.min(best, (int) Math.sqrt((double) dx * dx + (double) dy * dy));
			}
		}
		return best;
	}

	/** The branch nearest to a point (or the first, if {@code from} is null), on the surface map; null if unknown. */
	public WorldPoint nearestPoint(WorldPoint from)
	{
		WorldPoint best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (int[] p : at == null ? new int[0][] : at)
		{
			if (p == null || p.length < 2)
			{
				continue;
			}
			WorldPoint wp = new WorldPoint(p[0], surfaceY(p[1]), 0);
			int d = from == null ? 0 : (int) Math.hypot(wp.getX() - from.getX(), wp.getY() - surfaceY(from.getY()));
			if (best == null || d < bestDistance)
			{
				best = wp;
				bestDistance = d;
			}
		}
		return best;
	}

	/** The group this shop belongs to: its kind ("General store") if others pay the same, otherwise its own name. */
	public String getGroup()
	{
		return group != null ? group : name;
	}

	private static int surfaceY(int y)
	{
		return y >= UNDERGROUND_OFFSET ? y - UNDERGROUND_OFFSET : y;
	}
}

package com.assetmanager.shop;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Predicate;
import lombok.Getter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Every shop that buys items for coins, and the best price one would pay for an item.
 * <p>
 * A shop pays {@code value * rate}, where the rate drops by {@code delta} for each item it holds above its
 * normal stock, down to a minimum of 10%. Prices assume the shop is at its normal stock and that the player
 * hops to a fresh world (where the price is back to normal) once selling another would no longer be worth it.
 */
@Slf4j
public class ShopCatalog
{
	/** Shops never pay less than 10% of an item's value. */
	static final int MIN_RATE = 100;
	/** maxWorlds for a player happy to hop as many worlds as it takes, over as many sessions as it takes. */
	public static final int NO_WORLD_LIMIT = 0;
	/** Standing this close to a shop counts as being at it. */
	static final int AT_SHOP_TILES = 20;

	@Getter
	private final String generated;
	private final List<Shop> shops;

	/** Shops that list each item (by lowercased name), and general stores, which buy any tradeable item. */
	private final Map<String, List<Shop>> listing = new HashMap<>();
	private final List<Shop> generalStores = new ArrayList<>();
	private final Map<Shop, Integer> order = new IdentityHashMap<>();

	public ShopCatalog(List<Shop> shops, String generated)
	{
		this.shops = shops;
		this.generated = generated;
		for (Shop shop : shops)
		{
			// Gson reads maps as sorted trees, which are slow to look up in; this is looked up in a lot
			shop.setItems(new HashMap<>(shop.getItems()));
			order.put(shop, order.size());
			if (shop.isGeneral())
			{
				generalStores.add(shop);
			}
			for (String item : shop.getItems().keySet())
			{
				listing.computeIfAbsent(item, k -> new ArrayList<>()).add(shop);
			}
		}
		groupShops(shops);
	}

	/**
	 * Groups the shops that pay exactly the same: the same kind of shop with the same rates, buying the same items on
	 * the same terms (general stores buy anything, so only items with terms of their own count). Each group is named
	 * for its kind of shop, like "General store"; a shop like no other keeps its own name.
	 */
	private void groupShops(List<Shop> shops)
	{
		Map<String, List<Shop>> bySignature = new LinkedHashMap<>();
		for (Shop shop : shops)
		{
			if (shop.getBuyMultiplier() > 0 && shop.getType() != null)
			{
				bySignature.computeIfAbsent(signature(shop), k -> new ArrayList<>()).add(shop);
			}
		}
		// Kinds of shop with more than one group (general stores at 40% and at 55%, say), largest first
		Map<String, List<List<Shop>>> byType = new HashMap<>();
		for (List<Shop> group : bySignature.values())
		{
			if (group.size() > 1)
			{
				byType.computeIfAbsent(group.get(0).getType(), k -> new ArrayList<>()).add(group);
			}
		}
		Set<String> taken = new HashSet<>();
		for (List<List<Shop>> groups : byType.values())
		{
			groups.sort(Comparator.comparingInt((List<Shop> g) -> g.size()).reversed());
			Shop main = groups.get(0).get(0);
			for (int i = 0; i < groups.size(); i++)
			{
				List<Shop> group = groups.get(i);
				Shop first = group.get(0);
				String label = first.getType();
				if (i > 0)
				{
					// Tell it apart from the main group by its rates, or else (or if another group has those rates too)
					// by where its shops are
					String byRates = label + " (" + percent(first.getBuyMultiplier()) + ", " + percent(first.getDelta()) + " less each)";
					boolean sameRates = first.getBuyMultiplier() == main.getBuyMultiplier() && first.getDelta() == main.getDelta();
					label = sameRates || taken.contains(byRates) ? label + " (" + places(group) + ")" : byRates;
				}
				String unique = label;
				for (int n = 2; !taken.add(unique); n++)
				{
					unique = label + " " + n;
				}
				for (Shop shop : group)
				{
					shop.setGroup(unique);
				}
			}
		}
	}

	private static String signature(Shop shop)
	{
		StringBuilder sb = new StringBuilder()
			.append(shop.getType()).append('|').append(shop.getBuyMultiplier()).append('|').append(shop.getDelta())
			.append('|').append(shop.getGlovesTier()).append('|').append(shop.getGlovesBuyMultiplier())
			.append('|').append(shop.isWilderness()).append('|').append(shop.isGeneral());
		new TreeMap<>(shop.getItems()).forEach((name, item) ->
		{
			String terms = item.getM() + "," + item.getD() + "," + item.isNb() + "," + item.getP() + "," + item.getG()
				+ "," + item.getCm() + "," + item.getCp();
			// General stores buy anything, so only items with terms of their own tell them apart
			if (!shop.isGeneral() || !"null,null,false,null,null,null,null".equals(terms))
			{
				sb.append('|').append(name).append('=').append(terms);
			}
		});
		return sb.toString();
	}

	/** "Kastori, Hosidius" or "Kastori, Hosidius, ..." */
	private static String places(List<Shop> group)
	{
		List<String> names = new ArrayList<>();
		for (Shop s : group)
		{
			String place = s.getLocation() == null || s.getLocation().isEmpty() ? s.getName() : s.getLocation();
			if (!names.contains(place))
			{
				names.add(place);
			}
		}
		return names.size() <= 2 ? String.join(", ", names) : names.get(0) + ", " + names.get(1) + ", ...";
	}

	/** 400 tenths of a percent -> "40%", 3 -> "0.3%". */
	private static String percent(int tenths)
	{
		return tenths % 10 == 0 ? tenths / 10 + "%" : tenths / 10 + "." + Math.abs(tenths % 10) + "%";
	}

	/** Every shop, in the catalog's order. */
	public List<Shop> getShops()
	{
		return Collections.unmodifiableList(shops);
	}

	/** The shops in a group (or just the one shop, by its name), in the catalog's order. */
	public List<Shop> groupMembers(String group)
	{
		List<Shop> out = new ArrayList<>();
		for (Shop shop : shops)
		{
			if (shop.getGroup().equals(group))
			{
				out.add(shop);
			}
		}
		return out;
	}

	/** The shop in a group closest to {@code from}, or null if there's none; members shops only on a members world. */
	public Shop nearestInGroup(String group, WorldPoint from, boolean freeWorld)
	{
		return groupMembers(group).stream().filter(s -> !freeWorld || !s.isMembers()).min(Comparator.comparingInt(s -> s.distanceTo(from))).orElse(null);
	}

	/** The shops that might buy an item, in the catalog's order: those listing it, and general stores. */
	private List<Shop> candidates(String key)
	{
		List<Shop> listed = listing.getOrDefault(key, Collections.emptyList());
		List<Shop> out = new ArrayList<>(listed.size() + generalStores.size());
		out.addAll(listed);
		for (Shop s : generalStores)
		{
			if (!s.getItems().containsKey(key))
			{
				out.add(s);
			}
		}
		out.sort(Comparator.comparingInt(order::get));
		return out;
	}

	private static class Data
	{
		String generated;
		List<Shop> shops;
	}

	public static ShopCatalog load(Gson gson)
	{
		try (InputStream in = ShopCatalog.class.getResourceAsStream("/com/assetmanager/shops.json");
			Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			Data data = gson.fromJson(reader, Data.class);
			log.debug("Loaded {} shops (wiki data from {})", data.shops.size(), data.generated);
			return new ShopCatalog(data.shops, data.generated);
		}
		catch (Exception e)
		{
			log.warn("Unable to load shop data", e);
			return new ShopCatalog(Collections.emptyList(), null);
		}
	}

	/** Finds a shop by the name shown on its window, ignoring case and punctuation. Null if unknown. */
	public Shop findByName(String displayName)
	{
		String want = normalize(displayName);
		for (Shop shop : shops)
		{
			if (normalize(shop.getName()).equals(want))
			{
				return shop;
			}
		}
		return null;
	}

	static String normalize(String name)
	{
		return name == null ? "" : name.toLowerCase().replaceAll("[^a-z0-9]", "");
	}

	/**
	 * The shop paying the most for a whole stack of an item, or null if no shop buys it.
	 * <p>
	 * On each world the player sells while each sale pays at least {@code alternativeUnit + minGainPerItem}, then
	 * hops to a fresh world where the price is back to normal. A stack goes to a shop whole or not at all: the offer's
	 * quantity is 0 if even the first sale doesn't beat the alternative, or it needs more than {@code maxWorlds}
	 * worlds. Shops are compared by what they gain over the alternative. Hopping is quick, and every stack on a trip
	 * sells on each world at once, so hops aren't counted against a shop.
	 *
	 * @param alternativeUnit coins for one from the next best way to cash out (GE or alching), or 0 for none
	 * @param skipShops       names of shops not to consider
	 */
	public ShopOffer bestOffer(String name, int storeValue, int quantity, boolean tradeable, ShopPerks perks,
		long alternativeUnit, SellRules rules, Set<String> skipShops)
	{
		return bestOffer(name, storeValue, quantity, tradeable, perks, alternativeUnit, rules,
			shop -> !skipShops.contains(shop.getName()) && !skipShops.contains(shop.getGroup()));
	}

	/** As above, out of only the shops {@code usable} accepts. */
	public ShopOffer bestOffer(String name, int storeValue, int quantity, boolean tradeable, ShopPerks perks,
		long alternativeUnit, SellRules rules, Predicate<Shop> usable)
	{
		return pick(offers(name, storeValue, quantity, tradeable, perks, alternativeUnit, rules, usable),
			alternativeUnit * quantity, perks.getLocation(), perks.getPreferredShops());
	}

	/**
	 * What each of the {@code usable} shops would pay for a whole stack, as {@link #bestOffer}; an offer's quantity is 0
	 * where the stack isn't worth selling. Empty if no shop buys it.
	 */
	public List<ShopOffer> offers(String name, int storeValue, int quantity, boolean tradeable, ShopPerks perks,
		long alternativeUnit, SellRules rules, Predicate<Shop> usable)
	{
		if (storeValue <= 0 || quantity <= 0)
		{
			return Collections.emptyList();
		}
		long minUnit = alternativeUnit + Math.max(1, rules.getMinGainPerItem());
		String key = name.toLowerCase();
		List<ShopOffer> offers = new ArrayList<>();
		// Many shops (most general stores) pay the same rates, so each distinct rate is worked out once
		Map<Long, ShopOffer> byRate = new HashMap<>();
		for (Shop shop : candidates(key))
		{
			if (perks.isAvoidWilderness() && shop.isWilderness() || perks.isFreeWorld() && shop.isMembers() || !usable.test(shop))
			{
				continue;
			}
			Rate r = rateFor(shop, key, tradeable, perks);
			if (r == null)
			{
				continue;
			}
			ShopOffer offer;
			if (r.getFixedPrice() != null)
			{
				int each = r.getFixedPrice();
				// A fixed price never drops, so everything sells on one world
				offer = new ShopOffer(shop, each >= minUnit ? quantity : 0, each, (long) each * quantity, 0, false, quantity, 1, true,
					r.isCharos(), 0);
			}
			else
			{
				long rateKey = ((long) r.getRate() << 32) | (r.getDelta() & 0xFFFFFFFFL);
				ShopOffer same = byRate.get(rateKey);
				offer = same != null && same.isUsesKaramjaGloves() == r.isGloves() && same.isUsesCharos() == r.isCharos()
					? same.withShop(shop)
					: rateOffer(shop, r, storeValue, quantity, minUnit, rules.getMaxWorlds());
				byRate.putIfAbsent(rateKey, offer);
			}
			offers.add(offer);
		}
		return offers;
	}

	/** As above, with no shops skipped. */
	public ShopOffer bestOffer(String name, int storeValue, int quantity, boolean tradeable, ShopPerks perks,
		long alternativeUnit, int minGainPerItem, int maxWorlds)
	{
		return bestOffer(name, storeValue, quantity, tradeable, perks, alternativeUnit, new SellRules(minGainPerItem, maxWorlds, 0),
			Collections.emptySet());
	}

	/**
	 * The best offer. Shops gaining exactly as much count as paying the same; shops that always pay the same are grouped
	 * (see groupShops), but others can tie for an item too. Gains are compared rather than what the shops pay. Of
	 * those paying the same, the one the player is standing at wins; then one already suggested, so the suggestion
	 * doesn't change on the way there; then the closest. A shop paying even a little less never wins by being closer.
	 */
	static ShopOffer pick(List<ShopOffer> offers, long alternativeTotal, WorldPoint from,
		Set<String> preferred)
	{
		long top = offers.stream().mapToLong(o -> score(o, alternativeTotal)).max().orElse(Long.MIN_VALUE);
		List<ShopOffer> same = new ArrayList<>();
		for (ShopOffer o : offers)
		{
			long s = score(o, alternativeTotal);
			if (s == top)
			{
				same.add(o);
			}
		}
		if (same.isEmpty())
		{
			return null;
		}
		Comparator<ShopOffer> byDistance = Comparator.comparingInt(o -> o.getShop().distanceTo(from));
		ShopOffer closest = same.stream().min(byDistance).get();
		if (closest.getShop().distanceTo(from) > AT_SHOP_TILES)
		{
			closest = same.stream().filter(o -> preferred.contains(o.getShop().getGroup())).min(byDistance).orElse(closest);
		}
		return closest.withEqualShops(same.size() - 1);
	}

	/**
	 * How good an offer is: offers worth using by what they gain over the alternative; the rest below them all, by
	 * their first price, for display.
	 */
	static long score(ShopOffer o, long alternativeTotal)
	{
		return o.getQuantity() == 0 ? -1 - Long.MAX_VALUE / 2 + o.getFirstUnit() : o.getTotal() - alternativeTotal;
	}

	/** What a shop pays for an item, at its normal stock. */
	@Value
	public static class Rate
	{
		/** Tenths of a percent of the item's value; unused for a fixed price. */
		int rate;
		/** Change in rate per item held above normal stock. */
		int delta;
		/** The shop's normal stock of the item: 0 for an item a general store doesn't stock. */
		int normalStock;
		/** Coins per item for traders paying a fixed price, or null. */
		Integer fixedPrice;
		boolean gloves;
		boolean charos;
	}

	/**
	 * What a shop pays for an item, with the player's perks; null if it doesn't buy it.
	 *
	 * @param name the item's name, lowercased
	 */
	public static Rate rateFor(Shop shop, String name, boolean tradeable, ShopPerks perks)
	{
		Shop.Item item = shop.getItems().get(name);
		if (shop.getBuyMultiplier() <= 0 || item != null && item.isNb() || item == null && !(shop.isGeneral() && tradeable))
		{
			return null;
		}
		int normal = item == null ? 0 : Math.max(0, item.getS());
		if (item != null && item.getP() != null)
		{
			boolean charos = perks.isCharos() && item.getCp() != null;
			return new Rate(0, 0, normal, charos ? item.getCp() : item.getP(), false, charos);
		}
		boolean gloves = shop.getGlovesTier() != null && perks.getGlovesTier() >= shop.getGlovesTier();
		int rate;
		int delta;
		if (item != null)
		{
			rate = item.getM() != null ? item.getM() : shop.getBuyMultiplier();
			delta = item.getD() != null ? item.getD() : shop.getDelta();
			if (gloves && item.getG() != null)
			{
				rate = item.getG();
			}
			else
			{
				gloves = false;
			}
		}
		else
		{
			rate = shop.getBuyMultiplier();
			delta = shop.getDelta();
			if (gloves && shop.getGlovesBuyMultiplier() != null)
			{
				rate = shop.getGlovesBuyMultiplier();
			}
			else
			{
				gloves = false;
			}
		}
		boolean charos = perks.isCharos() && item != null && item.getCm() != null;
		if (charos)
		{
			rate = item.getCm();
		}
		return new Rate(rate, delta, normal, null, gloves, charos);
	}

	/**
	 * How many to sell to a shop now, with {@code stock} of the item already in it, before the next sale would pay less
	 * than {@code minUnit}. Other players' sales count: a shop already holding extra pays less.
	 */
	public static int sellNow(int value, Rate r, int stock, long minUnit, int have)
	{
		if (r.getFixedPrice() != null)
		{
			return r.getFixedPrice() >= minUnit ? have : 0;
		}
		return perWorld(value, r.getRate() - r.getDelta() * (stock - r.getNormalStock()), r.getDelta(), minUnit, have);
	}

	private static ShopOffer rateOffer(Shop shop, Rate r, int storeValue, int quantity, long minUnit, int maxWorlds)
	{
		int rate = r.getRate();
		int delta = r.getDelta();
		boolean gloves = r.isGloves();
		boolean charos = r.isCharos();

		int perWorld = perWorld(storeValue, rate, delta, minUnit, quantity);
		if (perWorld == 0)
		{
			// Not even the first sale beats the alternative: priced on one world, for comparison only
			return new ShopOffer(shop, 0, price(storeValue, rate), totalFor(storeValue, quantity, rate, delta), rate, gloves,
				quantity, 1, false, charos, 0);
		}
		int worlds = (quantity + perWorld - 1) / perWorld;
		long total = (long) (quantity / perWorld) * totalFor(storeValue, perWorld, rate, delta)
			+ totalFor(storeValue, quantity % perWorld, rate, delta);
		boolean tooManyWorlds = maxWorlds != NO_WORLD_LIMIT && worlds > maxWorlds;
		return new ShopOffer(shop, tooManyWorlds ? 0 : quantity, price(storeValue, rate), total, rate, gloves, perWorld, worlds,
			false, charos, 0);
	}

	/**
	 * How many to sell on one world before the next sale would pay less than {@code minUnit}: 0 if even the first
	 * doesn't, or all of them if the price never drops that far.
	 */
	static int perWorld(int value, int rate, int delta, long minUnit, int quantity)
	{
		if (price(value, rate) < minUnit)
		{
			return 0;
		}
		if (delta <= 0 || price(value, MIN_RATE) >= minUnit)
		{
			return quantity;
		}
		// The price reaches the floor within (rate - MIN_RATE) / delta sales, and the floor is too low, so this ends
		int n = 1;
		while (n < quantity && price(value, rate - delta * n) >= minUnit)
		{
			n++;
		}
		return n;
	}

	static long price(int value, int rate)
	{
		return (long) value * Math.max(MIN_RATE, rate) / 1000;
	}

	/** Coins for selling {@code quantity} items one after another on one world, as the rate drops by delta per item. */
	static long totalFor(int value, int quantity, int rate, int delta)
	{
		long total = 0;
		int sold = 0;
		while (sold < quantity && delta > 0 && rate - delta * sold > MIN_RATE)
		{
			total += price(value, rate - delta * sold);
			sold++;
		}
		// Whatever's left sells at a constant rate (either no drop, or the 10% floor).
		int rest = quantity - sold;
		total += (long) rest * price(value, delta > 0 ? MIN_RATE : rate);
		return total;
	}
}

package com.assetmanager.shop;

import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Helps the player find a shop, like the clue scroll plugin does for clues: centres the world map on it when the map
 * is opened, and points the hint arrow at it until the player gets there. Nothing is clicked or opened for them.
 */
@Singleton
public class ShopFinder
{
	/** Close enough to count as there: the arrow's job is done. */
	private static final int ARRIVED_TILES = 8;

	private final Client client;
	private final ClientThread clientThread;

	/** The shop being found, or null. */
	@Getter
	private volatile String shop;
	private volatile WorldPoint target;
	/** Called on the client thread with the shop when the player arrives. */
	@Setter
	private Consumer<String> onArrived = s -> {};

	@Inject
	ShopFinder(Client client, ClientThread clientThread)
	{
		this.client = client;
		this.clientThread = clientThread;
	}

	/** Starts finding a shop at {@code at}. Client thread. */
	public void find(String name, WorldPoint at)
	{
		clear();
		shop = name;
		target = at;
		centreMap();
		pointArrow();
	}

	/** Stops finding the shop, and takes the hint arrow away if it's still ours. Client thread. */
	public void clear()
	{
		WorldPoint t = target;
		if (t != null && client.hasHintArrow() && t.equals(client.getHintArrowPoint()))
		{
			client.clearHintArrow();
		}
		shop = null;
		target = null;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.WORLDMAP && target != null)
		{
			// The map sets its own position as it opens, so centre it just after
			clientThread.invokeLater(this::centreMap);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		WorldPoint t = target;
		if (t == null || client.getLocalPlayer() == null)
		{
			return;
		}
		WorldPoint here = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
		if (here != null && here.getPlane() == t.getPlane() && here.distanceTo2D(t) <= ARRIVED_TILES)
		{
			String arrived = shop;
			clear();
			onArrived.accept(arrived);
			return;
		}
		// Something else (a quest, say) may have used the arrow meanwhile; take it back once it's free
		pointArrow();
	}

	private void centreMap()
	{
		WorldMap map = client.getWorldMap();
		WorldPoint t = target;
		if (map != null && t != null)
		{
			map.setWorldMapPositionTarget(t);
		}
	}

	private void pointArrow()
	{
		WorldPoint t = target;
		if (t != null && !client.hasHintArrow())
		{
			client.setHintArrow(t);
		}
	}
}

package com.assetmanager.shop;

import com.assetmanager.dest.Destination;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

/**
 * Marks the shops Asset Manager suggests on the world map; hover one for what to sell there, click it to centre on it.
 * The shop being found sticks to the edge of the map, pointing the way, while it's off screen.
 */
@Singleton
public class ShopMapMarkers
{
	private static final int ICON_SIZE = 15;

	private final WorldMapPointManager worldMapPointManager;
	private final List<WorldMapPoint> points = new ArrayList<>();
	private volatile BufferedImage icon;
	private List<String> shown = new ArrayList<>();
	/** The shop being found, if any. */
	private String focused;
	private List<Destination> lastShops = new ArrayList<>();
	private WorldPoint lastFrom;

	@Inject
	ShopMapMarkers(WorldMapPointManager worldMapPointManager, SpriteManager spriteManager)
	{
		this.worldMapPointManager = worldMapPointManager;
		spriteManager.getSpriteAsync(SpriteID.Mapfunction.GENERAL_STORE, 0,
			img -> icon = img == null ? null : ImageUtil.resizeImage(img, ICON_SIZE, ICON_SIZE));
	}

	/** Shows these shops, at the branch nearest {@code from}; an empty list clears them. */
	public void update(List<Destination> shops, WorldPoint from)
	{
		lastShops = shops;
		lastFrom = from;
		BufferedImage img = icon;
		List<String> wanted = new ArrayList<>();
		List<WorldMapPoint> next = new ArrayList<>();
		for (Destination d : shops)
		{
			WorldPoint at = d.getShop() == null ? null : d.getShop().nearestPoint(from);
			if (at == null || img == null)
			{
				continue;
			}
			String tooltip = d.getName() + ": " + d.getCount() + " item" + (d.getCount() == 1 ? "" : "s")
				+ (d.getGain() > 0 ? ", +" + QuantityFormatter.quantityToStackSize(d.getGain()) + " gp" : "");
			boolean finding = d.getName().equals(focused);
			wanted.add(tooltip + "@" + at + (finding ? " finding" : ""));
			next.add(WorldMapPoint.builder()
				.worldPoint(at)
				.image(img)
				.name(d.getName())
				.tooltip(tooltip)
				.jumpOnClick(true)
				.snapToEdge(finding)
				.build());
		}
		// Only touch the map when something changed
		if (Objects.equals(wanted, shown))
		{
			return;
		}
		clear();
		points.addAll(next);
		points.forEach(worldMapPointManager::add);
		shown = wanted;
	}

	/** Which shop is being found (its marker sticks to the map's edge), or null. */
	public void setFocused(String shop)
	{
		focused = shop;
		update(lastShops, lastFrom);
	}

	public void clear()
	{
		points.forEach(worldMapPointManager::remove);
		points.clear();
		shown = new ArrayList<>();
	}
}

package com.assetmanager.shop;

import lombok.Value;
import lombok.With;

/**
 * What a shop would pay for a whole stack of an item. The player sells on each world while each sale beats the next
 * best way to cash out (GE or alching), then hops to a fresh world.
 */
@Value
public class ShopOffer
{
	@With
	Shop shop;
	/** The whole stack if it's worth selling here, otherwise 0. */
	int quantity;
	/** Coins for the first item sold. */
	long firstUnit;
	/** Coins for the whole stack, before the cost of hopping. */
	long total;
	/** The rate paid for the first item, in tenths of a percent. */
	int rate;
	boolean usesKaramjaGloves;
	/** How many to sell on each world before hopping. */
	int perWorld;
	/** Worlds to sell the whole stack on (1 if the price doesn't drop, or doesn't drop enough to matter). */
	int worlds;
	/** A trader paying a set number of coins (usually through dialogue) rather than a shop %. */
	boolean fixedPrice;
	/** The price needs an activated Ring of Charos. */
	boolean usesCharos;
	/** Other shops that would pay about the same; this one is the closest of them. */
	@With
	int equalShops;
}

package com.assetmanager.shop;

import java.util.Collections;
import java.util.Set;
import lombok.AllArgsConstructor;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/** What the player has, or is willing to do, that changes which shops they can use and what they pay. */
@Value
@AllArgsConstructor
public class ShopPerks
{
	public static final ShopPerks NONE = new ShopPerks(0, false);

	/** Karamja gloves tier (0 for none); gloves 2 and 4 give the same shop prices as 1 and 3. */
	int glovesTier;
	/** Owns an activated Ring of Charos, which gets better prices from Baraek and Fritz the Glassblower. */
	boolean charos;
	/** Leave out shops in the Wilderness. */
	boolean avoidWilderness;
	/** Where the player is, to pick the closest of shops paying the same; null if unknown. */
	WorldPoint location;
	/**
	 * Shops already suggested (or being found). Of shops paying the same, these are kept, so the suggestion doesn't
	 * switch to another as the player walks towards it.
	 */
	Set<String> preferredShops;
	/** On a free-to-play world, where members shops can't be used. */
	boolean freeWorld;

	public ShopPerks(int glovesTier, boolean charos, boolean avoidWilderness, WorldPoint location, Set<String> preferredShops)
	{
		this(glovesTier, charos, avoidWilderness, location, preferredShops, false);
	}

	public ShopPerks(int glovesTier, boolean charos, boolean avoidWilderness, WorldPoint location)
	{
		this(glovesTier, charos, avoidWilderness, location, Collections.emptySet());
	}

	public ShopPerks(int glovesTier, boolean charos)
	{
		this(glovesTier, charos, false);
	}

	public ShopPerks(int glovesTier, boolean charos, boolean avoidWilderness)
	{
		this(glovesTier, charos, avoidWilderness, null);
	}
}

package com.assetmanager.shop;

import com.assetmanager.keep.Holdings;
import com.assetmanager.keep.KeepRules;
import com.assetmanager.value.ItemValuator;
import com.assetmanager.value.ItemValues;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * In a shop, labels each item in the player's inventory with how many to sell on this world: as many as each still
 * pays more than the GE or alching, given what the shop already holds (including what other players have sold it).
 * When that's none but a fresh world would buy some, it says to hop.
 */
@Singleton
public class ShopSellOverlay extends WidgetItemOverlay
{
	private static final Color SELL = new Color(0x4CAF50);
	private static final Color HOP = new Color(0xFF9800);

	/** What the counts depend on, from the last recalculation. */
	@Value
	public static class Context
	{
		ShopPerks perks;
		int minGainPerItem;
		int natureRuneCost;
		boolean canUseGe;
		KeepRules keepRules;
		Holdings holdings;
	}

	private final Client client;
	private final ItemManager itemManager;
	private final ItemValuator itemValuator;

	@Setter
	private volatile Context context;
	@Setter
	private Supplier<Shop> openShop = () -> null;

	@Inject
	ShopSellOverlay(Client client, ItemManager itemManager, ItemValuator itemValuator)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.itemValuator = itemValuator;
		showOnInterfaces(InterfaceID.Shopside.ITEMS >>> 16);
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		Context ctx = context;
		Shop shop = openShop.get();
		if (ctx == null || shop == null || widgetItem.getWidget().getId() != InterfaceID.Shopside.ITEMS)
		{
			return;
		}
		int id = itemManager.canonicalize(itemId);
		if (id == ItemID.COINS)
		{
			return;
		}
		ItemValues v = itemValuator.get(id);
		ShopCatalog.Rate rate = ShopCatalog.rateFor(shop, v.getName().toLowerCase(), v.isTradeable(), ctx.getPerks());
		if (rate == null)
		{
			return;
		}
		KeepRules rules = ctx.getKeepRules();
		int have = Math.min(widgetItem.getQuantity(), rules.has(id) ? ctx.getHoldings().spare(Holdings.Place.INVENTORY, id, rules)
			: widgetItem.getQuantity());
		if (have <= 0)
		{
			return;
		}
		long alt = Math.max(ctx.isCanUseGe() ? v.getGeNetSell() : 0, v.getHighAlchNet(ctx.getNatureRuneCost()));
		long minUnit = alt + Math.max(1, ctx.getMinGainPerItem());
		int now = ShopCatalog.sellNow(v.getStorePrice(), rate, stock(id), minUnit, have);
		String text;
		Color color;
		if (now > 0)
		{
			text = now >= have ? "sell all" : "sell " + now;
			color = SELL;
		}
		else if (ShopCatalog.sellNow(v.getStorePrice(), rate, rate.getNormalStock(), minUnit, have) > 0)
		{
			text = "hop";
			color = HOP;
		}
		else
		{
			return;
		}
		Rectangle b = widgetItem.getCanvasBounds();
		g.setFont(FontManager.getRunescapeSmallFont());
		int y = b.y + b.height;
		g.setColor(Color.BLACK);
		g.drawString(text, b.x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, b.x, y);
	}

	/** How many of an item the open shop holds. */
	private int stock(int canonicalId)
	{
		Widget items = client.getWidget(InterfaceID.Shopmain.ITEMS);
		if (items == null || items.getDynamicChildren() == null)
		{
			return 0;
		}
		for (Widget w : items.getDynamicChildren())
		{
			if (w.getItemId() > 0 && !w.isHidden() && itemManager.canonicalize(w.getItemId()) == canonicalId)
			{
				return w.getItemQuantity();
			}
		}
		return 0;
	}
}

package com.assetmanager.shop;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Which shops the player has seen overstocked, on which worlds, and when each is back to normal.
 * <p>
 * A shop's stock moves one item back towards normal every so many ticks (its restock time, from the wiki), so an
 * item 3 over its normal stock with a 12,000 tick restock is back to normal within 6 hours. When in that cycle the
 * next one goes isn't shown, so until it's known the timer assumes a whole cycle (the worst case). Once the player
 * sees the stock drop by one without buying it, that's the end of a cycle, and the timer for that item on that world
 * is exact from then on. Only what the player has seen is known: there's no way to see a shop on another world
 * without going there.
 * <p>
 * When the player opens a shop, whatever overstock they didn't leave there themselves was left by others. Once an
 * item is found overstocked by others on {@link #BUSY_WORLDS} worlds, other players are likely selling it on every
 * world, so it's busy until those worlds have restocked.
 */
public class ShopStock
{
	public static final long TICK_MILLIS = 600;
	/** Worlds an item has to be found overstocked by others on to call it busy everywhere. */
	public static final int BUSY_WORLDS = 2;
	/** How long a learned restock cycle is trusted; worlds restart with weekly game updates. */
	static final long CYCLE_KEPT_MILLIS = 7L * 24 * 3_600_000;

	@Value
	public static class Seen
	{
		String shop;
		/** Lowercased item name, as in the shop data. */
		String item;
		int world;
		int restockTicks;
		/** How far over its normal stock the item was when last seen, and when. */
		int overstock;
		long at;
		/** How much of that was left by other players: the overstock found when the player opened the shop. */
		int others;
		long othersAt;
		/** When the player saw a restock cycle end for this item on this world, or 0 if they haven't. */
		long cycleAt;

		/** Whether the timer is exact rather than the worst case. */
		public boolean isExact()
		{
			return cycleAt > 0;
		}

		private long interval()
		{
			return restockTicks * TICK_MILLIS;
		}

		/** When the first item goes after {@code t}: a whole cycle later if the cycle isn't known. */
		private long firstDropAfter(long t)
		{
			if (cycleAt <= 0)
			{
				return t + interval();
			}
			return cycleAt + (Math.floorDiv(t - cycleAt, interval()) + 1) * interval();
		}

		/** When the stock is back to normal. */
		public long getNormalAt()
		{
			return overstock == 0 ? at : firstDropAfter(at) + (overstock - 1) * interval();
		}

		/** When the stock left by others has gone. */
		public long getOthersGoneAt()
		{
			return others == 0 ? othersAt : firstDropAfter(othersAt) + (others - 1) * interval();
		}

		/** How far over normal the stock is by {@code now}. */
		int overstockAt(long now)
		{
			long first = firstDropAfter(at);
			return now < first ? overstock : (int) Math.max(0, overstock - ((now - first) / interval() + 1));
		}
	}

	/** Shop items others are selling on every world. */
	@Value
	public static class Busy
	{
		String shop;
		String item;
		/** Worlds the player found it overstocked on by others. */
		int worlds;
		/** When fewer than BUSY_WORLDS of them are still overstocked. */
		long until;
	}

	private final Map<String, Seen> seen = new HashMap<>();
	/** When a restock cycle was seen ending, by shop, item and world; kept after the stock is back to normal. */
	private final Map<String, Long> cycles = new HashMap<>();

	public ShopStock()
	{
	}

	public ShopStock(Collection<Seen> saved, Map<String, Long> savedCycles, long now)
	{
		for (Seen s : saved)
		{
			seen.put(key(s.getShop(), s.getItem(), s.getWorld()), s);
		}
		cycles.putAll(savedCycles);
		prune(now);
	}

	private static String key(String shop, String item, int world)
	{
		return shop + "|" + item + "|" + world;
	}

	/**
	 * Records an item's stock in an open shop.
	 *
	 * @param opened true for the first look after opening the shop on this world, when any overstock the player
	 *               didn't leave there themselves was left by others
	 * @param bought whether the player just bought this item, which also lowers the stock
	 * @return whether anything changed
	 */
	public boolean observe(String shop, String item, int world, int stock, int normalStock, int restockTicks, boolean opened,
		boolean bought, long now)
	{
		if (normalStock < 0 || restockTicks <= 0)
		{
			return false;
		}
		String key = key(shop, item, world);
		Seen old = seen.get(key);
		int over = Math.max(0, stock - normalStock);
		boolean cycleSeen = false;
		if (!opened && !bought && old != null && old.getOverstock() - over == 1)
		{
			// One went while the player watched: a restock cycle just ended
			cycles.put(key, now);
			cycleSeen = true;
		}
		long cycleAt = cycles.getOrDefault(key, 0L);
		int others;
		long othersAt;
		if (old == null)
		{
			others = opened ? over : 0;
			othersAt = now;
		}
		else if (opened)
		{
			// What's left of the player's own sales from last time is theirs; the rest is new from others
			int own = Math.max(0, old.overstockAt(now) - Math.max(0, old.getOthers() - elapsed(old.getOthersAt(), now, restockTicks)));
			others = Math.max(0, over - own);
			othersAt = now;
		}
		else
		{
			others = old.getOthers();
			othersAt = old.getOthersAt();
		}
		if (over == 0)
		{
			return seen.remove(key) != null || cycleSeen;
		}
		if (old != null && old.getOverstock() == over && old.getOthers() == others && old.getCycleAt() == cycleAt
			&& old.overstockAt(now) == over)
		{
			return false;
		}
		seen.put(key, new Seen(shop, item, world, restockTicks, over, now, others, othersAt, cycleAt));
		return true;
	}

	private static int elapsed(long since, long now, int restockTicks)
	{
		return (int) ((now - since) / (restockTicks * TICK_MILLIS));
	}

	/** Drops what's back to normal and cycles too old to trust; returns whether anything was dropped. */
	public boolean prune(long now)
	{
		boolean cyclesDropped = cycles.values().removeIf(t -> now - t > CYCLE_KEPT_MILLIS);
		return seen.values().removeIf(s -> s.getNormalAt() <= now) | cyclesDropped;
	}

	/** Everything still overstocked on worlds the player has seen, soonest back to normal first. */
	public List<Seen> overstocked(String shop, long now)
	{
		List<Seen> out = new ArrayList<>();
		for (Seen s : seen.values())
		{
			if (s.getShop().equals(shop) && s.getNormalAt() > now)
			{
				out.add(s);
			}
		}
		out.sort(Comparator.comparingLong(Seen::getNormalAt));
		return out;
	}

	/** Shop items found overstocked by others on several worlds, which likely aren't worth a trip until they restock. */
	public List<Busy> busy(long now)
	{
		Map<String, List<Long>> gone = new HashMap<>();
		for (Seen s : seen.values())
		{
			if (s.getOthers() > 0 && s.getOthersGoneAt() > now)
			{
				gone.computeIfAbsent(s.getShop() + "|" + s.getItem(), k -> new ArrayList<>()).add(s.getOthersGoneAt());
			}
		}
		List<Busy> out = new ArrayList<>();
		gone.forEach((key, times) ->
		{
			if (times.size() >= BUSY_WORLDS)
			{
				times.sort(Collections.reverseOrder());
				String[] parts = key.split("\\|", 2);
				out.add(new Busy(parts[0], parts[1], times.size(), times.get(BUSY_WORLDS - 1)));
			}
		});
		out.sort(Comparator.comparing(Busy::getShop).thenComparing(Busy::getItem));
		return out;
	}

	public Collection<Seen> all()
	{
		return Collections.unmodifiableCollection(seen.values());
	}

	public Map<String, Long> cycles()
	{
		return Collections.unmodifiableMap(cycles);
	}
}

package com.assetmanager.shop;

import com.assetmanager.AssetManagerConfig;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Reads the stock of the open shop each tick and keeps {@link ShopStock} up to date, saved per RuneScape profile so
 * the timers survive logging out. Only reads what the shop window shows.
 */
@Slf4j
@Singleton
public class ShopStockTracker
{
	private static final String KEY = "shopStock";
	private static final String KEY_CYCLES = "shopRestockCycles";

	private final Client client;
	private final ItemManager itemManager;
	private final ConfigManager configManager;
	private final Gson gson;

	@Setter
	private Supplier<Shop> openShop = () -> null;
	/** Called on the client thread when which shops are overstocked, or busy, changes. */
	@Setter
	private Runnable onChange = () -> {};
	/** Saved at most this often while a shop is open, and when it closes. */
	private static final int SAVE_TICKS = 50;

	private volatile ShopStock stock = new ShopStock();
	/** The shop and world being looked at, to tell when the player opens a shop afresh. */
	private String visit;
	private boolean unsaved;
	private int ticksSinceSave;
	/** Which shop items are overstocked on which worlds, and which are busy, as of the last change reported. */
	private Object lastShape;
	/** The player's inventory last tick, to tell a purchase from a restock. */
	private Map<Integer, Integer> lastInventory = Collections.emptyMap();

	@Inject
	ShopStockTracker(Client client, ItemManager itemManager, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.configManager = configManager;
		this.gson = gson;
	}

	public ShopStock get()
	{
		return stock;
	}

	public void load()
	{
		String json = configManager.getRSProfileConfiguration(AssetManagerConfig.GROUP, KEY);
		List<ShopStock.Seen> saved = Collections.emptyList();
		if (json != null)
		{
			try
			{
				List<ShopStock.Seen> parsed = gson.fromJson(json, new TypeToken<List<ShopStock.Seen>>()
				{
				}.getType());
				if (parsed != null)
				{
					saved = parsed;
				}
			}
			catch (JsonParseException e)
			{
				log.debug("Ignoring unreadable shop stock", e);
			}
		}
		Map<String, Long> cycles = Collections.emptyMap();
		String cyclesJson = configManager.getRSProfileConfiguration(AssetManagerConfig.GROUP, KEY_CYCLES);
		if (cyclesJson != null)
		{
			try
			{
				Map<String, Long> parsed = gson.fromJson(cyclesJson, new TypeToken<Map<String, Long>>()
				{
				}.getType());
				if (parsed != null)
				{
					cycles = parsed;
				}
			}
			catch (JsonParseException e)
			{
				log.debug("Ignoring unreadable restock cycles", e);
			}
		}
		stock = new ShopStock(saved, cycles, System.currentTimeMillis());
		visit = null;
	}

	private void save()
	{
		unsaved = false;
		ticksSinceSave = 0;
		configManager.setRSProfileConfiguration(AssetManagerConfig.GROUP, KEY, gson.toJson(new ArrayList<>(stock.all())));
		configManager.setRSProfileConfiguration(AssetManagerConfig.GROUP, KEY_CYCLES, gson.toJson(new HashMap<>(stock.cycles())));
	}

	private Map<Integer, Integer> inventory()
	{
		Map<Integer, Integer> counts = new HashMap<>();
		ItemContainer inv = client.getItemContainer(InventoryID.INV);
		if (inv != null)
		{
			for (Item i : inv.getItems())
			{
				if (i.getId() > 0)
				{
					counts.merge(itemManager.canonicalize(i.getId()), i.getQuantity(), Integer::sum);
				}
			}
		}
		return counts;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		long now = System.currentTimeMillis();
		ShopStock s = stock;
		boolean changed = s.prune(now);

		Widget items = client.getWidget(InterfaceID.Shopmain.ITEMS);
		Shop shop = openShop.get();
		if (shop == null || items == null || items.isHidden() || items.getDynamicChildren() == null)
		{
			visit = null;
			lastInventory = Collections.emptyMap();
			if (unsaved)
			{
				save();
			}
		}
		else
		{
			String here = shop.getName() + "|" + client.getWorld();
			boolean opened = !here.equals(visit);
			visit = here;
			Map<Integer, Integer> inventory = inventory();
			for (Widget w : items.getDynamicChildren())
			{
				if (w.getItemId() <= 0 || w.isHidden())
				{
					continue;
				}
				String name = itemManager.getItemComposition(w.getItemId()).getName().toLowerCase();
				Shop.Item entry = shop.getItems().get(name);
				if (entry != null && entry.getR() != null)
				{
					int id = itemManager.canonicalize(w.getItemId());
					boolean bought = inventory.getOrDefault(id, 0) > lastInventory.getOrDefault(id, 0);
					changed |= s.observe(shop.getName(), name, client.getWorld(), w.getItemQuantity(), entry.getS(), entry.getR(),
						opened, bought, now);
				}
			}
			lastInventory = inventory;
		}
		if (changed)
		{
			unsaved = true;
			// Stock counts change every sale; only what the plan depends on needs a recalculation
			Object shape = shape(s, now);
			if (!shape.equals(lastShape))
			{
				lastShape = shape;
				onChange.run();
			}
		}
		if (unsaved && ++ticksSinceSave >= SAVE_TICKS)
		{
			save();
		}
	}

	private static Object shape(ShopStock s, long now)
	{
		Set<String> keys = new HashSet<>();
		for (ShopStock.Seen seen : s.all())
		{
			keys.add(seen.getShop() + "|" + seen.getItem() + "|" + seen.getWorld());
		}
		Set<String> busy = new HashSet<>();
		for (ShopStock.Busy b : s.busy(now))
		{
			busy.add(b.getShop() + "|" + b.getItem());
		}
		return Arrays.asList(keys, busy);
	}
}

package com.assetmanager.shop;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;

/** Wording for shop restock times. */
public final class ShopTimes
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofLocalizedTime(FormatStyle.SHORT);
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE");

	private ShopTimes()
	{
	}

	/** "6h 0m", "12m", or "under a minute". */
	public static String duration(long millis)
	{
		long minutes = (millis + 59_999) / 60_000;
		if (minutes <= 1)
		{
			return millis <= 60_000 ? "under a minute" : "1m";
		}
		return minutes >= 60 ? minutes / 60 + "h " + minutes % 60 + "m" : minutes + "m";
	}

	/** A clock time, with the day if it isn't today: "9:40 PM", "Thu 3:15 AM". */
	public static String clock(long epochMillis)
	{
		ZonedDateTime t = Instant.ofEpochMilli(epochMillis).atZone(ZoneId.systemDefault());
		String time = t.format(TIME);
		return t.toLocalDate().equals(LocalDate.now()) ? time : t.format(DAY) + " " + time;
	}

	/** "rune plateskirt" as shown in game: "Rune plateskirt". */
	public static String itemName(String lowercased)
	{
		return lowercased.isEmpty() ? lowercased : Character.toUpperCase(lowercased.charAt(0)) + lowercased.substring(1);
	}
}

