	private void selectTab(Tab t)
	{
		if (t == tab)
		{
			return;
		}
		scrollPositions[tab.ordinal()] = scroll.getVerticalScrollBar().getValue();
		tab = t;
		update(lastState, warnDeaths);
		int position = scrollPositions[t.ordinal()];
		// Restore after the new content has been laid out, or the scroll bar's range is still the old tab's
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	public void update(PanelState state, int warnDeaths)
	{
		this.lastState = state;
		this.warnDeaths = warnDeaths;
		content.removeAll();
		boolean flipping = tab == Tab.FLIPPING && state != null;
		if (state != null)
		{
			fillDests(state);
		}
		destRow.setVisible(flipping && destChoices.size() > 1);
		sortRow.setVisible(flipping);
		// Patience only matters for the GE
		patienceRow.setVisible(flipping && state.getAccountMode().canUseGrandExchange());

		if (state == null)
		{
			addRow(text(tab == Tab.LIQUIDATE ? "Log in to see your death costs." : "Log in to see shop deals.", Color.LIGHT_GRAY));
		}
		else if (tab == Tab.LIQUIDATE)
		{
			if (state.getAccountMode().canUseCoffer())
			{
				addCofferSection(state);
			}
			else
			{
				addRow(text("Ultimate ironmen can't use Death's coffer.", Color.LIGHT_GRAY));
			}
			addRiskSection(state);
			addDestinationsSection(state);
			addKeptSection(state);
		}
		else
		{
			addFlipsSection(state);
		}

		content.revalidate();
		content.repaint();
	}

	// --- Sections ---

	private void addCofferSection(PanelState state)
	{
		if (!header("Death's coffer"))
		{
			return;
		}
		if (state.isCofferKnown())
		{
			JLabel balance = new JLabel(QuantityFormatter.formatNumber(state.getCofferBalance()) + " gp");
			balance.setFont(FontManager.getRunescapeBoldFont());
			balance.setForeground(Color.WHITE);
			addRow(balance);
			addRow(text("From " + state.getCofferSource() + ", " + ago(state.getCofferUpdatedAt()), MUTED));
		}
		else
		{
			addRow(text("Balance unknown. Open the coffer at Death's Office, or set it below.", WARN));
		}

		long deaths = state.getDeathsCovered();
		DeathCostEstimate est = state.getEstimate();
		if (deaths >= 0 && est != null)
		{
			String covered = deaths == Long.MAX_VALUE ? "Dying is free in your current gear"
				: "Covers <b>" + deaths + "</b> death" + (deaths == 1 ? "" : "s") + " at " + gp(est.getScenarioFee()) + " each";
			addRow(text(covered, deaths < warnDeaths ? BAD : GOOD));
		}

		addGap(4);
		addRow(valueRow("Target", gp(state.getCofferTarget()), Color.WHITE));
		addRow(text(targetBasis(state), MUTED));
		CofferPlan plan = state.getPlan();
		if (plan != null)
		{
			if (plan.getShortfall() <= 0)
			{
				addRow(text("Your coffer meets the target.", GOOD));
			}
			else
			{
				addRow(valueRow("Short by", gp(plan.getShortfall()), WARN));
				if (!plan.getSteps().isEmpty())
				{
					addRow(text("Sacrifice the items under Death's coffer below"
						+ (plan.getCoinsToDeposit() > 0 ? ", then deposit " + gp(plan.getCoinsToDeposit()) : "") + ".", MUTED));
				}
				else if (plan.getCoinsToDeposit() > 0)
				{
					addRow(text("Deposit " + gp(plan.getCoinsToDeposit()) + " to reach it.", MUTED));
				}
				if (plan.getRemainingShortfall() > 0)
				{
					addRow(text("Still short " + gp(plan.getRemainingShortfall()) + " after that.", BAD));
				}
			}
		}

		JButton set = smallButton("Set balance", "Enter your coffer balance by hand");
		set.addActionListener(e -> promptBalance());
		addGap(4);
		addRow(set);
	}

	private void addRiskSection(PanelState state)
	{
		if (!header("If you die now"))
		{
			return;
		}
		DeathCostEstimate est = state.getEstimate();
		if (est == null)
		{
			addRow(text("Waiting for inventory and equipment...", MUTED));
			return;
		}

		String status = "Keeping " + est.getKeepCount() + " item" + (est.getKeepCount() == 1 ? "" : "s")
			+ (state.isSkulled() ? " · <font color='#F44336'>skulled</font>" : "")
			+ (state.isProtectItem() ? " · Protect Item" : "")
			+ (est.isIronDiscount() ? " · iron 50% off" : "");
		addRow(text(status, Color.LIGHT_GRAY));
		addRow(valueRow("To reclaim", gp(est.getValueAtRisk()), Color.WHITE));
		DeathScenario sc = est.getScenario();
		if (sc != DeathScenario.GRAVESTONE && sc != DeathScenario.DEATHS_OFFICE)
		{
			// At a boss with its own retrieval service, that's what a death costs
			addRow(valueRow(sc.getDisplayName() + " retrieval", gp(est.getScenarioFee()), feeColor(est.getScenarioFee())));
			addRow(text("You're at " + sc.getDisplayName() + ", so items go to its retrieval service.", MUTED));
		}
		else
		{
			addRow(valueRow("Gravestone fee", gp(est.getGravestoneFee()), feeColor(est.getGravestoneFee())));
			addRow(valueRow("If the grave expires", gp(est.getDeathsOfficeFee()), feeColor(est.getDeathsOfficeFee())));
		}
	}

	private void addDestinationsSection(PanelState state)
	{
		if (!header("Your spare items"))
		{
			return;
		}
		Destinations dests = state.getDestinations();
		if (dests == null)
		{
			addRow(text("Open your bank once so it can be scanned.", WARN));
			return;
		}
		addRow(text("Click one to see its items in your bank, most valuable first.", MUTED));
		addGap(2);

		boolean ge = state.getAccountMode().canUseGrandExchange();
		destinationRow(dests.get(Destination.Kind.ALL), state);
		if (state.getAccountMode().canUseCoffer())
		{
			destinationRow(dests.get(Destination.Kind.COFFER), state);
		}
		if (ge)
		{
			destinationRow(dests.get(Destination.Kind.ALCH), state);
			destinationRow(dests.get(Destination.Kind.GE), state);
		}

		subheader("Shops");
		ShopPerks perks = state.getPerks();
		addRow(wildernessToggle(perks.isAvoidWilderness()));
		List<Destination> shops = dests.getShops();
		if (shops.isEmpty())
		{
			addRow(text("No shop pays more than " + (ge ? "the GE or alching" : "alching") + " for your spare items.", MUTED));
		}
		for (Destination shop : shops)
		{
			destinationRow(shop, state);
		}
		if (!shops.isEmpty())
		{
			addRow(text("These shops are marked on your world map.", MUTED));
		}
		for (ShopStock.Busy b : state.getBusyShops())
		{
			addRow(wrapped("Not suggesting " + b.getShop() + " for " + b.getItem()
				+ " until about " + ShopTimes.clock(b.getUntil()) + ": others overstocked it on " + b.getWorlds()
				+ " worlds you checked.", DETAIL_WIDTH, WARN));
		}
		addRow(text("Karamja gloves: " + (perks.getGlovesTier() >= 3 ? "3 or 4" : perks.getGlovesTier() >= 1 ? "1 or 2" : "none")
			+ " · Ring of Charos (a): " + (perks.isCharos() ? "yes" : "no"), MUTED));

		subheader("Other");
		destinationRow(dests.get(Destination.Kind.KEPT), state);
	}

	/** Lists the places the account can cash out, when they change, with the one in use selected. */
	private void fillDests(PanelState state)
	{
		List<Flip.Dest> can = Flips.destinations(state.getAccountMode());
		if (pickedDest != null && (state.getFlipDest() == pickedDest || !can.contains(pickedDest)))
		{
			pickedDest = null;
		}
		// Until the flips catch up with the player's pick, a refresh shouldn't put the old choice back
		Flip.Dest show = pickedDest != null ? pickedDest : state.getFlipDest();
		if (can.equals(destChoices) && show == destBox.getSelectedItem())
		{
			return;
		}
		fillingDests = true;
		destBox.removeAllItems();
		can.forEach(destBox::addItem);
		destBox.setSelectedItem(show);
		fillingDests = false;
		destChoices = can;
	}

	private static JLabel controlLabel(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(Color.LIGHT_GRAY);
		l.setPreferredSize(new Dimension(52, l.getPreferredSize().height));
		return l;
	}

	private void addFlipsSection(PanelState state)
	{
		addGap(6);
		if (!state.isFlipsEnabled())
		{
			addRow(text("Turn on Show flips in the settings to list things worth buying in one place and cashing out in another.",
				Color.LIGHT_GRAY));
			return;
		}
		List<String> notes = new ArrayList<>();
		Flip.Dest flipDest = state.getFlipDest();
		if (state.getAccountMode().canUseGrandExchange() && flipDest != Flip.Dest.GE && !state.isGeFlips())
		{
			notes.add("<font color='#FF9800'>" + (flipDest == Flip.Dest.SHOP ? "Selling to shops is for what you buy on the GE, so it"
				: "Including what you could buy on the GE") + " needs Live GE prices on in the settings (if they're on, prices are"
				+ " still loading).</font>");
		}
		if (flipDest == Flip.Dest.GE)
		{
			notes.add("Things to buy from shops and sell on the GE.");
		}
		List<FlipRun> flips = state.getFlips();
		if (state.getFlipCoins() <= 0)
		{
			addRow(text("Carry some coins to see flips. They only spend the coins in your inventory, so take out as much as you"
				+ " want to flip with.", Color.LIGHT_GRAY));
		}
		else if (flips.isEmpty())
		{
			addRow(text("Nothing is worth flipping right now with the " + gp(state.getFlipCoins()) + " in your inventory.",
				Color.LIGHT_GRAY));
		}
		else
		{
			FlipSort sort = state.getFlipSort();
			addRow(text((sort == FlipSort.RETURN ? "Best return first" : sort == FlipSort.PROFIT ? "Most profitable first"
				: "Most an hour first") + ", spending up to the " + gp(state.getFlipCoins()) + " in your inventory and using"
				+ " shops whose requirements you meet. Each is one go: a shop visit with everything worth it there, or one round"
				+ " of GE offers." + (sort == FlipSort.GP_PER_HOUR ? " Times are rough: hops, trips, conversations, alchs and the"
				+ " GE's wait." : ""), MUTED));
		}
		for (String note : notes)
		{
			addRow(text(note, MUTED));
		}
		addGap(4);
		flips.forEach(f -> flipRow(f, state.getFlipSort()));
	}

	/** One go: where, what it makes, what to buy and how long it takes, and a Find button for a shop. */
	private void flipRow(FlipRun run, FlipSort sort)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));

		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setOpaque(false);
		String route = run.getSource().getLabel() + " &rarr; " + run.getDest().getLabel()
			+ (run.getFlips().size() > 1 ? " &middot; " + run.getFlips().size() + " items" : "");
		top.add(wrapped(capitalise(run.getName()) + "<br><font color='#FF9800'>" + route + "</font>", NAME_WIDTH, Color.WHITE),
			BorderLayout.CENTER);
		JPanel east = new JPanel();
		east.setLayout(new BoxLayout(east, BoxLayout.Y_AXIS));
		east.setOpaque(false);
		// What it's sorted by goes first, in green
		JLabel profit = new JLabel("+" + gp(run.getProfit()));
		profit.setToolTipText("What one go makes, " + gp(run.getCost()) + " spent");
		JLabel hourly = new JLabel("+" + QuantityFormatter.quantityToStackSize(Math.round(run.getGpPerHour())) + "/hr");
		hourly.setToolTipText("About what it makes an hour, at about " + FlipTime.describe(run.getSeconds()) + " a go");
		JLabel ret = new JLabel("+" + percent(run.getReturnPercent()));
		ret.setToolTipText("Return: what it makes for each coin spent, " + gp(run.getCost()) + " in all");
		JLabel first = sort == FlipSort.RETURN ? ret : sort == FlipSort.PROFIT ? profit : hourly;
		JLabel second = sort == FlipSort.PROFIT ? hourly : profit;
		for (JLabel l : new JLabel[]{first, second})
		{
			l.setFont(FontManager.getRunescapeSmallFont());
			l.setForeground(l == first ? GOOD : MUTED);
			l.setAlignmentX(Component.RIGHT_ALIGNMENT);
			east.add(l);
		}
		Shop shop = run.getShop();
		if (shop != null)
		{
			boolean finding = shop.getName().equals(findingShop);
			JButton find = smallButton(finding ? "Stop" : "Find",
				finding ? "Stop pointing the way to this shop" : "Centre the world map on this shop and point the hint arrow at it");
			find.setAlignmentX(Component.RIGHT_ALIGNMENT);
			find.addActionListener(e -> onFindShop.accept(shop));
			east.add(Box.createVerticalStrut(2));
			east.add(find);
		}
		top.add(east, BorderLayout.EAST);
		row.add(top, BorderLayout.CENTER);
		row.add(wrapped(runDetail(run), DETAIL_WIDTH, MUTED), BorderLayout.SOUTH);
		addRow(row);
	}

	private static String runDetail(FlipRun run)
	{
		StringBuilder d = new StringBuilder();
		Shop shop = run.getShop();
		String others = run.getEqualShops() > 0 ? " (or any of " + run.getEqualShops() + " others the same)" : "";
		String hop = run.getWorlds() > 1 ? ", a few on each of " + run.getWorlds() + " worlds" : "";
		if (run.getSource() == Flip.Source.SHOP)
		{
			d.append("Buy at ").append(where(shop)).append(others).append(hop).append(':');
		}
		else if (run.getDest() == Flip.Dest.SHOP)
		{
			d.append("Buy on the GE, then sell to ").append(where(shop)).append(others).append(hop);
			ShopOffer o = run.getFlips().get(0).getSellOffer();
			if (o.isUsesKaramjaGloves())
			{
				d.append(", wearing Karamja gloves");
			}
			if (o.isUsesCharos())
			{
				d.append(", wearing your Ring of Charos (a)");
			}
			d.append(':');
		}
		else
		{
			d.append("Buy on the GE:");
		}
		Set<String> unchecked = new LinkedHashSet<>();
		for (Flip f : run.getFlips())
		{
			d.append("<br>&middot; ").append(QuantityFormatter.formatNumber(f.getQuantity())).append(' ').append(f.getItem())
				.append(": ").append(gp(f.getFirstCost())).append(f.isPriceRises() ? " up" : "").append(" &rarr; ")
				.append(gp(f.getFirstValue())).append(f.getSellOffer() != null && f.getSellOffer().getWorlds() > 1 ? " down" : "")
				.append(" each, +").append(gp(f.getProfit())).append(" (").append(f.getLimit().getDescription());
			if (f.getGeTrades() != Long.MAX_VALUE)
			{
				d.append("; ").append(QuantityFormatter.formatNumber(f.getGeTrades())).append(" trade in that time");
			}
			d.append(')');
			Shop.Item item = f.getBuyShop() == null ? null : f.getBuyShop().getItems().get(f.getItem());
			int[] bundle = item == null ? null : item.getB();
			if (bundle != null && bundle.length == 2)
			{
				d.append(". Offer ").append(gp(bundle[1])).append(" for ").append(bundle[0]).append(" to get that price");
			}
			unchecked.addAll(f.getUnchecked());
		}
		d.append("<br>");
		switch (run.getDest())
		{
			case GE:
				d.append("Then sell them on the GE (prices after tax).");
				break;
			case COFFER:
				d.append("Then put them in Death's coffer.");
				break;
			case ALCH:
				d.append("Then alch them (after the nature rune).");
				break;
			case SHOP:
				d.append(shop.getTalk() != null ? shop.getTalk() + " only takes unnoted ones, so it's an inventory a trip."
					: "The shop takes noted ones.");
				break;
		}
		if (run.getSource() == Flip.Source.SHOP && shop.getTalk() != null)
		{
			d.append(" Bought by talking to ").append(shop.getTalk()).append(", sometimes one at a time.");
		}
		List<String> parts = new ArrayList<>();
		if (shop != null || run.getDest() == Flip.Dest.COFFER)
		{
			parts.add("a trip");
		}
		if (run.getWorlds() > 1)
		{
			parts.add(run.getWorlds() - 1 + " hops");
		}
		if (shop != null && shop.getTalk() != null && run.getSource() == Flip.Source.SHOP)
		{
			parts.add("talking");
		}
		if (run.getDest() == Flip.Dest.ALCH)
		{
			parts.add("alching");
		}
		if (run.getSource() == Flip.Source.GE || run.getDest() == Flip.Dest.GE)
		{
			parts.add("the GE's wait");
		}
		d.append(" About ").append(FlipTime.describe(run.getSeconds())).append(" a go (").append(String.join(", ", parts))
			.append(").");
		if (!unchecked.isEmpty())
		{
			d.append(" <font color='#FF9800'>Also needs: ").append(String.join("; ", unchecked)).append(".</font>");
		}
		return d.toString();
	}

	private static String where(Shop shop)
	{
		return shop.getName() + (shop.getLocation() == null || shop.getLocation().isEmpty() ? "" : " (" + shop.getLocation() + ")");
	}

	/** 23.4 -> "23%", 0.42 -> "0.4%", 1234 -> "1,234%" */
	private static String percent(double p)
	{
		return p < 10 ? String.format("%.1f%%", p) : QuantityFormatter.formatNumber(Math.round(p)) + "%";
	}

	/** "bagged willow tree" -> "Bagged willow tree" */
	private static String capitalise(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/** One destination: name and value, a detail line, and a click to show its items in the bank. */
	private void destinationRow(Destination d, PanelState state)
	{
		if (d == null)
		{
			return;
		}
		boolean empty = d.getCount() == 0;
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 6, 4, 6));

		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setOpaque(false);
		top.add(wrapped(d.getName(), NAME_WIDTH, empty ? MUTED : Color.WHITE), BorderLayout.CENTER);
		if (!empty)
		{
			JLabel value = new JLabel(gp(d.getValue()));
			value.setFont(FontManager.getRunescapeSmallFont());
			value.setForeground(Color.WHITE);
			value.setVerticalAlignment(JLabel.TOP);
			value.setAlignmentX(Component.RIGHT_ALIGNMENT);
			JPanel east = new JPanel();
			east.setLayout(new BoxLayout(east, BoxLayout.Y_AXIS));
			east.setOpaque(false);
			east.add(value);
			if (d.getKind() == Destination.Kind.SHOP && d.getShop() != null)
			{
				boolean finding = d.getName().equals(findingShop);
				JButton find = smallButton(finding ? "Stop" : "Find",
					finding ? "Stop pointing the way to this shop"
						: "Centre the world map on this shop and point the hint arrow at it");
				find.setAlignmentX(Component.RIGHT_ALIGNMENT);
				find.addActionListener(e -> onFind.accept(d));
				east.add(Box.createVerticalStrut(2));
				east.add(find);
			}
			if (d.getKind() == Destination.Kind.GE)
			{
				JButton order = geOrderButton(state);
				order.setAlignmentX(Component.RIGHT_ALIGNMENT);
				east.add(Box.createVerticalStrut(2));
				east.add(order);
			}
			top.add(east, BorderLayout.EAST);
		}
		row.add(top, BorderLayout.CENTER);
		row.add(wrapped(empty ? emptyText(d) : detail(d, state), DETAIL_WIDTH, MUTED), BorderLayout.SOUTH);

		if (!empty)
		{
			row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			row.setToolTipText("Show " + (d.getKind() == Destination.Kind.SHOP ? "what to sell to " + d.getName()
				: "these items") + " in your bank");
			row.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					onShowInBank.accept(d);
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
				}
			});
		}
		addRow(row);
	}

	/** The same setting as "Avoid Wilderness shops" in the plugin's settings, here so players see they can turn them off. */
	private JCheckBox wildernessToggle(boolean avoid)
	{
		JCheckBox box = new JCheckBox("Avoid Wilderness shops", avoid);
		box.setFont(FontManager.getRunescapeSmallFont());
		box.setForeground(Color.LIGHT_GRAY);
		box.setOpaque(false);
		box.setFocusPainted(false);
		box.setBorder(new EmptyBorder(1, 0, 1, 0));
		box.setToolTipText("Never suggest selling to shops in the Wilderness, like Bandit Duty Free, where other players can"
			+ " attack you. Ferox Enclave is a safe zone and still counts. Also in the plugin's settings.");
		box.addActionListener(e -> onAvoidWilderness.accept(box.isSelected()));
		return box;
	}

	/** Switches the GE bank view between most valuable and quickest to sell first. */
	private JButton geOrderButton(PanelState state)
	{
		boolean quickest = state.getGeOrder() == GeOrder.QUICKEST;
		GeOrder next = quickest ? GeOrder.VALUE : GeOrder.QUICKEST;
		JButton b = smallButton(state.getGeOrder().getLabel(), quickest
			? "Shown quickest to sell first, to free the most bank spaces: click to show the most valuable first"
			: "Shown most valuable first: click to show what sells quickest first, to free the most bank spaces");
		if (!quickest && !state.isGeVolumes())
		{
			// Without trade volumes there's nothing to order by
			b.setEnabled(false);
			b.setToolTipText("Turn on Live GE prices in the settings to order these by how quickly they sell");
		}
		b.addActionListener(e -> onGeOrder.accept(next));
		return b;
	}

	private static String detail(Destination d, PanelState state)
	{
		List<String> parts = new ArrayList<>();
		boolean group = d.getKind() == Destination.Kind.SHOP && !d.getName().equals(d.getShop().getName());
		if (group)
		{
			parts.add("nearest: " + d.getShop().getName());
		}
		else if (d.getKind() == Destination.Kind.SHOP && d.getShop().getLocation() != null && !d.getShop().getLocation().isEmpty())
		{
			parts.add(d.getShop().getLocation());
		}
		parts.add(items(d.getCount()));
		String vs = state.getAccountMode().canUseGrandExchange() ? "the GE or alching" : "alching";
		switch (d.getKind())
		{
			case ALL:
				break;
			case COFFER:
				parts.add(state.getPlan() != null && state.getPlan().getShortfall() > 0 && !state.getPlan().getSteps().isEmpty()
					? "reaches your target" : "worth more there");
				break;
			case ALCH:
				vs = "the GE";
				break;
			case GE:
				parts.add("after tax");
				if (state.getGeOrder() == GeOrder.QUICKEST)
				{
					parts.add(state.isGeVolumes() ? "quickest to sell first" : "quickest to sell first once live prices load");
				}
				break;
			case KEPT:
				parts.add("in your bank");
				break;
			default:
				if (d.isNeedsGloves())
				{
					parts.add("wear Karamja gloves");
				}
				if (d.isNeedsCharos())
				{
					parts.add("wear Ring of Charos (a)");
				}
				if (d.getWorlds() > 1)
				{
					parts.add("hop " + d.getWorlds() + " worlds");
				}
				if (d.getEqualShops() > 0)
				{
					parts.add((group ? "any of " : "closest of ") + (d.getEqualShops() + 1) + " paying the same");
				}
				Long restocked = state.getRestockedBy().get(d.getShop().getName());
				if (restocked != null)
				{
					parts.add("worlds you saw overstocked are back to normal by " + ShopTimes.clock(restocked));
				}
		}
		d.getElsewhere().forEach((place, n) -> parts.add(n + " in " + (place == Holdings.Place.INVENTORY ? "your inventory" : "your " + place.getDisplayName())));
		if (d.getGain() > 0)
		{
			parts.add("<font color='" + GOOD_HTML + "'>+" + gp(d.getGain()) + "</font> vs "
				+ (d.getKind() == Destination.Kind.ALL ? "the next best way" : d.getKind() == Destination.Kind.COFFER ? "selling" : vs));
		}
		return String.join(" · ", parts);
	}

	private static String emptyText(Destination d)
	{
		switch (d.getKind())
		{
			case COFFER:
				return "Nothing needed right now";
			case KEPT:
				return "Right-click a bank item and choose Keep";
			default:
				return "Nothing right now";
		}
	}

	private void addKeptSection(PanelState state)
	{
		if (!header(SECTION_KEPT))
		{
			return;
		}
		if (state.getKeptItems().isEmpty())
		{
			addRow(text("Right-click an item in your bank and choose Keep to set how many to leave alone.", MUTED));
			return;
		}
		for (PanelState.KeptItem k : state.getKeptItems())
		{
			String what = k.getKeep() == KeepRules.KEEP_ALL ? "keep all" : "keep " + QuantityFormatter.formatNumber(k.getKeep());
			String have = k.getOwned() < 0 ? null : "you have " + QuantityFormatter.formatNumber(k.getOwned());
			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			row.setBorder(new EmptyBorder(3, 6, 3, 6));
			JPanel top = new JPanel(new BorderLayout(4, 0));
			top.setOpaque(false);
			top.add(wrapped(k.getName(), NAME_WIDTH, Color.WHITE), BorderLayout.CENTER);
			JLabel v = new JLabel(what);
			v.setFont(FontManager.getRunescapeSmallFont());
			v.setForeground(Color.LIGHT_GRAY);
			v.setVerticalAlignment(JLabel.TOP);
			top.add(v, BorderLayout.EAST);
			row.add(top, BorderLayout.CENTER);

			JButton edit = smallButton("Edit", "Change how many to keep");
			edit.addActionListener(e -> promptKeep(k));
			JButton remove = smallButton("×", "Stop keeping this item");
			remove.addActionListener(e -> onKeepChange.accept(k.getItemId(), 0));
			JPanel bottom = new JPanel();
			bottom.setLayout(new BoxLayout(bottom, BoxLayout.X_AXIS));
			bottom.setOpaque(false);
			if (have != null)
			{
				JLabel h = new JLabel(have);
				h.setFont(FontManager.getRunescapeSmallFont());
				h.setForeground(MUTED);
				bottom.add(h);
			}
			bottom.add(Box.createHorizontalGlue());
			bottom.add(edit);
			bottom.add(Box.createHorizontalStrut(4));
			bottom.add(remove);
			row.add(bottom, BorderLayout.SOUTH);
			addRow(row);
		}
	}

	private static String targetBasis(PanelState state)
	{
		DeathCostEstimate est = state.getEstimate();
		long perDeath = Math.max(est == null ? 0 : est.getScenarioFee(), state.getPeakFee());
		long fromDeaths = perDeath * state.getTargetDeaths();
		if (fromDeaths >= state.getMinCofferTarget() && perDeath > 0)
		{
			boolean fromPeak = est == null || state.getPeakFee() > est.getScenarioFee();
			return state.getTargetDeaths() + " deaths × " + gp(perDeath)
				+ (fromPeak ? " (your priciest setup in 14 days)" : "");
		}
		return "Your minimum target. Gear up once to plan for your real setup.";
	}

	// --- Dialogs ---

	private void promptKeep(PanelState.KeptItem k)
	{
		String current = k.getKeep() == KeepRules.KEEP_ALL ? "all" : String.valueOf(k.getKeep());
		Object input = JOptionPane.showInputDialog(this, "How many " + k.getName() + " should Asset Manager leave alone?\n(a number like 5 or 10k, \"all\", or 0 to stop keeping it)",
			"Keep " + k.getName(), JOptionPane.PLAIN_MESSAGE, null, null, current);
		if (input == null)
		{
			return;
		}
		Integer keep = KeepRules.parseInput(input.toString());
		if (keep == null)
		{
			JOptionPane.showMessageDialog(this, "Enter a number (like 5 or 10k) or \"all\".", "Keep " + k.getName(), JOptionPane.ERROR_MESSAGE);
			return;
		}
		onKeepChange.accept(k.getItemId(), keep);
	}

	private void promptBalance()
	{
		String input = JOptionPane.showInputDialog(this, "Death's coffer balance (e.g. 2500000 or 2.5m):", "Set coffer balance", JOptionPane.PLAIN_MESSAGE);
		if (input == null || input.trim().isEmpty())
		{
			return;
		}
		try
		{
			onManualBalance.accept(QuantityFormatter.parseQuantity(input.trim()));
		}
		catch (ParseException e)
		{
			JOptionPane.showMessageDialog(this, "That isn't a number.", "Set coffer balance", JOptionPane.ERROR_MESSAGE);
		}
	}

	// --- Building blocks ---

	/**
	 * Adds a section header that collapses the section when clicked.
	 *
	 * @return whether the section is expanded and its contents should be added
	 */
	private boolean header(String name)
	{
		boolean open = !collapsed.contains(name);
		JLabel l = new JLabel((open ? "▾ " : "▸ ") + name);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(ColorScheme.BRAND_ORANGE);
		l.setBorder(BorderFactory.createEmptyBorder(10, 0, 3, 0));
		l.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		l.setToolTipText(open ? "Click to collapse" : "Click to expand");
		l.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (!collapsed.remove(name))
				{
					collapsed.add(name);
				}
				update(lastState, warnDeaths);
			}
		});
		addRow(l);
		return open;
	}

	/** A small label grouping rows within a section. */
	private void subheader(String name)
	{
		JLabel l = new JLabel(name);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(Color.LIGHT_GRAY);
		l.setBorder(BorderFactory.createEmptyBorder(6, 0, 2, 0));
		addRow(l);
	}

	/** A label and a value on one line. */
	private static JPanel valueRow(String label, String value, Color valueColor)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));
		JLabel l = new JLabel(label);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(Color.LIGHT_GRAY);
		JLabel v = new JLabel(value);
		v.setFont(FontManager.getRunescapeSmallFont());
		v.setForeground(valueColor);
		row.add(l, BorderLayout.CENTER);
		row.add(v, BorderLayout.EAST);
		return row;
	}

	private static JLabel text(String html, Color color)
	{
		JLabel l = wrapped(html, TEXT_WIDTH, color);
		l.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		return l;
	}

	private static JLabel wrapped(String html, int width, Color color)
	{
		JLabel l = new JLabel("<html><div style='width:" + width + "px'>" + html + "</div></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		return l;
	}

	private static JButton smallButton(String label, String tooltip)
	{
		JButton b = new JButton(label);
		b.setToolTipText(tooltip);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setMargin(new Insets(0, 4, 0, 4));
		b.setFocusPainted(false);
		return b;
	}

	private void addGap(int px)
	{
		addRow((JComponent) Box.createVerticalStrut(px));
	}

	private void addRow(JComponent c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(c);
		if (c instanceof JPanel && ((JPanel) c).isOpaque())
		{
			// Space between rows
			JComponent gap = (JComponent) Box.createVerticalStrut(2);
			gap.setAlignmentX(Component.LEFT_ALIGNMENT);
			content.add(gap);
		}
	}

	private static Color feeColor(long fee)
	{
		return fee == 0 ? GOOD : Color.WHITE;
	}

	private static String items(int n)
	{
		return n + " item" + (n == 1 ? "" : "s");
	}

	private static String gp(long v)
	{
		return QuantityFormatter.quantityToStackSize(v) + " gp";
	}

	private static String ago(Instant t)
	{
		if (t == null)
		{
			return "unknown time";
		}
		long mins = Duration.between(t, Instant.now()).toMinutes();
		if (mins < 1)
		{
			return "just now";
		}
		if (mins < 60)
		{
			return mins + " min ago";
		}
		if (mins < 60 * 48)
		{
			return (mins / 60) + " h ago";
		}
		return (mins / 60 / 24) + " days ago";
	}

	/** Keeps content as wide as the scroll pane's viewport, so nothing can push it into sideways scrolling. */
	private static class WidthTrackingPanel extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.assetmanager.ui;

import java.awt.Color;
import java.awt.image.BufferedImage;
import lombok.Setter;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.util.QuantityFormatter;

/** Shows how many deaths the coffer covers in the current gear. */
public class CofferInfoBox extends InfoBox
{
	@Setter
	private PanelState state;
	@Setter
	private int warnDeaths;

	public CofferInfoBox(BufferedImage image, Plugin plugin)
	{
		super(image, plugin);
	}

	@Override
	public String getText()
	{
		long deaths = state == null ? -1 : state.getDeathsCovered();
		if (deaths < 0)
		{
			return "?";
		}
		return deaths == Long.MAX_VALUE ? "Free" : String.valueOf(deaths);
	}

	@Override
	public Color getTextColor()
	{
		long deaths = state == null ? -1 : state.getDeathsCovered();
		if (deaths < 0)
		{
			return Color.GRAY;
		}
		return deaths < warnDeaths ? Color.RED : Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		if (state == null || !state.isCofferKnown())
		{
			return "Death's coffer balance unknown</br>Check your coffer at Death's Office or set it in the Asset Manager panel";
		}
		String tip = "Death's coffer: " + QuantityFormatter.formatNumber(state.getCofferBalance()) + " gp";
		if (state.getEstimate() != null)
		{
			tip += "</br>Cost per death (" + state.getEstimate().getScenario() + "): "
				+ QuantityFormatter.formatNumber(state.getEstimate().getScenarioFee()) + " gp";
		}
		return tip;
	}

	@Override
	public boolean render()
	{
		return state != null && state.getAccountMode().canUseCoffer();
	}
}

package com.assetmanager.ui;

import com.assetmanager.AccountMode;
import com.assetmanager.coffer.CofferPlan;
import com.assetmanager.death.DeathCostEstimate;
import com.assetmanager.dest.Destinations;
import com.assetmanager.dest.GeOrder;
import com.assetmanager.flip.Flip;
import com.assetmanager.flip.FlipRun;
import com.assetmanager.flip.FlipSort;
import com.assetmanager.shop.ShopPerks;
import com.assetmanager.shop.ShopStock;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import lombok.Value;

/** Everything the side panel shows, calculated on the client thread and handed to the EDT. */
@Value
public class PanelState
{
	@Value
	public static class KeptItem
	{
		int itemId;
		String name;
		/** How many to keep, or KeepRules.KEEP_ALL. */
		int keep;
		/** How many the player has (worn, carried, banked and in the seed vault), or -1 if the bank hasn't been seen. */
		int owned;
	}

	AccountMode accountMode;
	long cofferBalance;
	boolean cofferKnown;
	String cofferSource;
	Instant cofferUpdatedAt;
	boolean skulled;
	boolean protectItem;
	/** Null when not logged in. */
	DeathCostEstimate estimate;
	/** Null until the bank has been opened once. */
	CofferPlan plan;
	/** Coffer balance the top-up plan aims for. */
	long cofferTarget;
	/** Most expensive death cost seen for the planned scenario in the last 14 days. */
	long peakFee;
	long minCofferTarget;
	List<KeptItem> keptItems;
	/** Karamja gloves, Ring of Charos and Wilderness choice used for shop suggestions. */
	ShopPerks perks;
	long bankCoins;
	int targetDeaths;
	/** Where spare items should go; null until the bank has been opened once. */
	Destinations destinations;
	/** When the worlds the player has seen each shop overstocked on are back to normal, by shop name. */
	Map<String, Long> restockedBy;
	/** Shop items others have overstocked on several worlds, which aren't suggested until they restock. */
	List<ShopStock.Busy> busyShops;
	/** The best flips, best first by flipSort; empty if none, turned off or not worked out yet. */
	List<FlipRun> flips;
	/** Whether flips are turned on in the settings. */
	boolean flipsEnabled;
	/** Whether GE-bought flips are included: the account can use the GE and live prices are on and loaded. */
	boolean geFlips;
	/** Where the flips cash out: the player's choice, if their account can. */
	Flip.Dest flipDest;
	/** How the flips are ordered. */
	FlipSort flipSort;
	/** Coins in the inventory, which is what the flips spend. */
	long flipCoins;
	/** How the Grand Exchange bank view is ordered. */
	GeOrder geOrder;
	/** Whether GE trade volumes are loaded (live prices on), which ordering by quickest to sell needs. */
	boolean geVolumes;

	/** Deaths the coffer covers at the selected scenario; -1 if unknown, Long.MAX_VALUE if free. */
	public long getDeathsCovered()
	{
		if (!cofferKnown || estimate == null)
		{
			return -1;
		}
		long fee = estimate.getScenarioFee();
		return fee <= 0 ? Long.MAX_VALUE : cofferBalance / fee;
	}
}

package com.assetmanager.ui;

import com.assetmanager.AccountMode;
import com.assetmanager.AssetManagerConfig;
import com.assetmanager.keep.Holdings;
import com.assetmanager.keep.KeepRules;
import com.assetmanager.shop.SellRules;
import com.assetmanager.shop.ShopCatalog;
import com.assetmanager.shop.ShopOffer;
import com.assetmanager.shop.ShopPerks;
import com.assetmanager.value.ItemValuator;
import com.assetmanager.value.ItemValues;
import java.awt.Color;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.QuantityFormatter;

/**
 * When hovering an item in the bank or inventory, shows what it's worth each way side by side:
 * GE (after tax), high alch (after the nature rune), Death's coffer and the best shop. The best way to
 * cash it out is highlighted, and the coffer is highlighted if it beats that.
 */
@Singleton
public class PriceTooltip
{
	private static final Color BEST = new Color(0x4CAF50);
	private static final Color NORMAL = new Color(0xEEEEEE);
	private static final Color MUTED = new Color(0x9E9E9E);
	private static final int WIDTH = 190;
	/** RuneLite's usual overlay color, but solid so tooltips are readable over busy interfaces. */
	public static final Color SOLID_BACKGROUND = ColorUtil.colorWithAlpha(ComponentConstants.STANDARD_BACKGROUND_COLOR, 255);

	/** What the tooltip needs from the plugin's latest calculation. */
	@Value
	public static class Context
	{
		AccountMode mode;
		int natureRuneCost;
		ShopPerks perks;
		SellRules sellRules;
		/** Shops each item isn't going to, because the trip wasn't worth it for that stack. */
		Map<Integer, Set<String>> skippedShops;
		/** Items planned to go to a shop. */
		Set<Integer> toShop;
		ShopCatalog shops;
		KeepRules keepRules;
		Holdings holdings;
	}

	private final Client client;
	private final TooltipManager tooltipManager;
	private final ItemValuator itemValuator;
	private final AssetManagerConfig config;
	private final ItemManager itemManager;

	private volatile Context context;
	/** Built tooltips by item id and quantity; cleared whenever the context changes. */
	private final Map<Long, PanelComponent> cache = new HashMap<>();

	@Inject
	PriceTooltip(Client client, TooltipManager tooltipManager, ItemValuator itemValuator, AssetManagerConfig config, ItemManager itemManager)
	{
		this.itemManager = itemManager;
		this.client = client;
		this.tooltipManager = tooltipManager;
		this.itemValuator = itemValuator;
		this.config = config;
	}

	public void setContext(Context context)
	{
		this.context = context;
		cache.clear();
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		Context ctx = context;
		if (ctx == null || !config.priceTooltip() || client.isMenuOpen())
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}
		MenuEntry entry = entries[entries.length - 1];
		int component = entry.getParam1();
		if (component != InterfaceID.Bankmain.ITEMS && component != InterfaceID.Bankside.ITEMS
			&& component != InterfaceID.Inventory.ITEMS && component >>> 16 != InterfaceID.SEED_VAULT)
		{
			return;
		}
		Widget w = entry.getWidget();
		if (w == null || w.getItemId() <= 0 || w.getItemId() == ItemID.COINS)
		{
			return;
		}
		// Placeholders have a quantity of 0; show single-item values for them
		int stack = Math.max(1, w.getItemQuantity());
		int qty = stack;
		int id = itemManager.canonicalize(w.getItemId());
		if (ctx.getKeepRules().has(id))
		{
			// Only the spare ones; a stack that's all being kept gets no tooltip
			int spare = ctx.getHoldings().spare(SuggestionOverlay.place(component), id, ctx.getKeepRules());
			if (spare == 0 && w.getItemQuantity() > 0)
			{
				return;
			}
			qty = Math.max(1, Math.min(stack, spare));
		}
		int shown = qty;
		long key = ((long) w.getItemId() << 32) | ((long) shown << 1) | (shown < stack ? 1 : 0);
		PanelComponent panel = cache.computeIfAbsent(key, k -> build(ctx, w.getItemId(), shown, shown < stack));
		if (panel != null)
		{
			tooltipManager.add(new Tooltip(panel));
		}
	}

	/** @param spareOnly whether {@code qty} is only the spare part of the stack */
	private PanelComponent build(Context ctx, int itemId, int qty, boolean spareOnly)
	{
		ItemValues v = itemValuator.get(itemId);
		boolean ge = ctx.getMode().canUseGrandExchange() && v.isTradeable();
		long geUnit = ge ? v.getGeNetSell() : 0;
		long haUnit = v.getHighAlchNet(ctx.getNatureRuneCost());
		long dcUnit = ctx.getMode().canUseCoffer() ? v.getCofferValue() : 0;
		long altUnit = Math.max(geUnit, haUnit);
		ShopOffer shop = ctx.getShops() == null ? null
			: ctx.getShops().bestOffer(v.getName(), v.getStorePrice(), qty, v.isTradeable(), ctx.getPerks(), altUnit,
				ctx.getSellRules(), ctx.getSkippedShops().getOrDefault(v.getItemId(), Collections.emptySet()));
		// Only counts when this stack is on a shop trip worth making
		boolean shopWorthIt = shop != null && shop.getQuantity() > 0 && ctx.getToShop().contains(v.getItemId());
		long shopTotal = shopWorthIt ? shop.getTotal() : 0;

		long bestCash = Math.max(Math.max(geUnit * qty, haUnit * qty), shopTotal);

		PanelComponent panel = new PanelComponent();
		panel.setBackgroundColor(SOLID_BACKGROUND);
		panel.setPreferredSize(new Dimension(WIDTH, 0));
		panel.getChildren().add(TitleComponent.builder()
			.text((spareOnly ? QuantityFormatter.formatNumber(qty) + " spare " : qty > 1 ? QuantityFormatter.formatNumber(qty) + " x " : "")
				+ v.getName())
			.color(NORMAL)
			.build());
		if (qty > 1)
		{
			panel.getChildren().add(LineComponent.builder().left("Worth for the whole stack:").leftColor(MUTED).build());
		}

		List<LineComponent> rows = new ArrayList<>();
		rows.add(ge
			? priceLine("GE", geUnit, geUnit * qty, qty, geUnit * qty == bestCash && bestCash > 0)
			: line("GE", ctx.getMode().canUseGrandExchange() ? "untradeable" : "ironman", MUTED, MUTED));
		rows.add(priceLine("High alch", haUnit, haUnit * qty, qty, haUnit * qty == bestCash && bestCash > 0));
		if (ctx.getMode().canUseCoffer())
		{
			rows.add(dcUnit > 0
				? priceLine("Coffer", dcUnit, dcUnit * qty, qty, dcUnit * qty > bestCash)
				: line("Coffer", v.isTradeable() ? "under 10k" : "untradeable", MUTED, MUTED));
		}
		if (shopWorthIt)
		{
			rows.add(priceLine("Shop", shop.getFirstUnit(), shopTotal, qty, shopTotal == bestCash));
		}
		else if (shop != null && shop.getFirstUnit() > 0)
		{
			rows.add(line("Shop", QuantityFormatter.formatNumber(shop.getFirstUnit()) + " each", MUTED, MUTED));
		}
		else
		{
			rows.add(line("Shop", "none buy it", MUTED, MUTED));
		}
		panel.getChildren().addAll(rows);
		if (ge && v.getWikiPrice() > 0)
		{
			panel.getChildren().add(LineComponent.builder()
				.left("GE: " + QuantityFormatter.formatNumber(v.getWikiPrice()) + " each before tax, " + itemValuator.getGePriceDescription())
				.leftColor(MUTED)
				.build());
		}

		if (shop != null && (shopWorthIt || shop.getFirstUnit() > 0))
		{
			String group = shop.getShop().getGroup();
			String where = (group.equals(shop.getShop().getName()) ? group : group + ", nearest " + shop.getShop().getName())
				+ (shop.isUsesKaramjaGloves() ? " (gloves)" : "")
				+ (shop.isUsesCharos() ? " (Ring of Charos)" : "")
				+ (shop.isFixedPrice() ? " (fixed price)" : "")
				+ (shop.getEqualShops() > 0 ? " (closest of " + (shop.getEqualShops() + 1) + " paying the same)" : "");
			if (shopWorthIt && shop.getWorlds() > 1)
			{
				where += ", " + shop.getPerWorld() + " per world on " + shop.getWorlds() + " worlds";
			}
			if (!shopWorthIt)
			{
				where += shop.getQuantity() > 0 ? ": not worth the trip or the hops" : " doesn't beat " + (geUnit >= haUnit ? "the GE" : "alching");
			}
			panel.getChildren().add(LineComponent.builder().left(where).leftColor(MUTED).build());
		}
		int keep = ctx.getKeepRules().get(v.getItemId());
		if (keep != 0)
		{
			panel.getChildren().add(LineComponent.builder()
				.left(keep == KeepRules.KEEP_ALL ? "Keeping all" : "Keeping " + QuantityFormatter.formatNumber(keep))
				.leftColor(MUTED)
				.build());
		}
		return panel;
	}

	private static LineComponent priceLine(String label, long unit, long total, int qty, boolean best)
	{
		Color c = best ? BEST : NORMAL;
		return line(label, QuantityFormatter.formatNumber(qty > 1 ? total : unit), c, c);
	}

	private static LineComponent line(String label, String value, Color labelColor, Color valueColor)
	{
		return LineComponent.builder().left(label).leftColor(labelColor).right(value).rightColor(valueColor).build();
	}
}

package com.assetmanager.ui;

import com.assetmanager.AssetManagerConfig;
import com.assetmanager.Suggestions;
import com.assetmanager.bank.BankViews;
import com.assetmanager.dest.Destination;
import com.assetmanager.keep.Holdings;
import com.assetmanager.keep.KeepRules;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ImageUtil;

/**
 * Draws a small coffer, alchemy, shop or GE icon in the corner of items Asset Manager has a suggestion for, in the
 * bank, inventory and seed vault. A stack that's all being kept (say the one rune platebody you keep, in your
 * inventory) gets no icon. While an Asset Manager bank view is open, items with a keep rule show how many are kept.
 */
@Singleton
public class SuggestionOverlay extends WidgetItemOverlay
{
	private static final int ICON_SIZE = 12;
	private static final Color KEEP_COLOR = new Color(0xFF9800);

	private final ItemManager itemManager;
	private final AssetManagerConfig config;
	private final BankViews bankViews;
	private final BufferedImage cofferIcon;
	private volatile Image alchIcon;
	private volatile Image shopIcon;
	private volatile Image geIcon;

	@Setter
	private volatile Suggestions suggestions = Suggestions.NONE;
	@Setter
	private volatile KeepRules keepRules = new KeepRules();
	@Setter
	private volatile Holdings holdings = Holdings.NONE;

	@Inject
	SuggestionOverlay(ItemManager itemManager, SpriteManager spriteManager, AssetManagerConfig config, BankViews bankViews)
	{
		this.itemManager = itemManager;
		this.config = config;
		this.bankViews = bankViews;
		cofferIcon = ImageUtil.resizeImage(ImageUtil.loadImageResource(getClass(), "/com/assetmanager/icon.png"), ICON_SIZE, ICON_SIZE);
		spriteManager.getSpriteAsync(SpriteID.Magicon.HIGH_LEVEL_ALCHEMY, 0,
			img -> alchIcon = img == null ? null : ImageUtil.resizeImage(img, ICON_SIZE, ICON_SIZE));
		spriteManager.getSpriteAsync(SpriteID.Mapfunction.GENERAL_STORE, 0,
			img -> shopIcon = img == null ? null : ImageUtil.resizeImage(img, ICON_SIZE, ICON_SIZE));
		spriteManager.getSpriteAsync(SpriteID.Mapfunction.GRAND_EXCHANGE, 0,
			img -> geIcon = img == null ? null : ImageUtil.resizeImage(img, ICON_SIZE, ICON_SIZE));
		showOnBank();
		showOnInventory();
		showOnInterfaces(InterfaceID.SEED_VAULT);
	}

	/** Where an item widget's stack is. */
	static Holdings.Place place(int widgetId)
	{
		if (widgetId == InterfaceID.Bankmain.ITEMS)
		{
			return Holdings.Place.BANK;
		}
		return widgetId >>> 16 == InterfaceID.SEED_VAULT ? Holdings.Place.SEED_VAULT : Holdings.Place.INVENTORY;
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		int id = itemManager.canonicalize(itemId);
		Rectangle b = widgetItem.getCanvasBounds();
		KeepRules rules = keepRules;
		Holdings.Place place = place(widgetItem.getWidget().getId());
		// Nothing spare here: the kept ones get no icon
		Image icon = rules.has(id) && holdings.spare(place, id, rules) == 0 ? null
			: icon(iconKind(suggestions, id, place == Holdings.Place.BANK ? bankViews.showingKind() : null));
		if (icon != null)
		{
			// Top-right corner, clear of the quantity text in the top-left.
			g.drawImage(icon, b.x + b.width - ICON_SIZE, b.y, null);
		}

		int keep = rules.get(id);
		if (keep != 0 && widgetItem.getWidget().getId() == InterfaceID.Bankmain.ITEMS && bankViews.isShowing())
		{
			String text = keep == KeepRules.KEEP_ALL ? "keep all" : "keep " + keep;
			g.setFont(FontManager.getRunescapeSmallFont());
			int y = b.y + b.height;
			g.setColor(Color.BLACK);
			g.drawString(text, b.x + 1, y + 1);
			g.setColor(KEEP_COLOR);
			g.drawString(text, b.x, y);
		}
	}

	/** Which icon an item gets: its suggestion, or in a bank view for one destination, only that one. */
	static Suggestions.Kind iconKind(Suggestions s, int id, Destination.Kind view)
	{
		if (view != null)
		{
			switch (view)
			{
				case COFFER:
					return s.getCoffer().contains(id) ? Suggestions.Kind.COFFER : null;
				case ALCH:
					return s.getAlch().contains(id) ? Suggestions.Kind.ALCH : null;
				case GE:
					return s.getGe().contains(id) ? Suggestions.Kind.GE : null;
				case SHOP:
					return s.getShop().contains(id) ? Suggestions.Kind.SHOP : null;
				default:
			}
		}
		return s.getIcon(id);
	}

	private Image icon(Suggestions.Kind kind)
	{
		if (kind == null)
		{
			return null;
		}
		switch (kind)
		{
			case COFFER:
				return config.cofferIcons() ? cofferIcon : null;
			case ALCH:
				return config.alchIcons() ? alchIcon : null;
			case SHOP:
				return config.shopIcons() ? shopIcon : null;
			default:
				return config.geIcons() ? geIcon : null;
		}
	}
}

package com.assetmanager.value;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** Which live Grand Exchange price to value items at when selling. */
@Getter
@RequiredArgsConstructor
public enum GePrice
{
	/** The price buyers have been paying: what you'll usually get by listing and waiting a little. */
	MARKET("List at market price", "live market price"),
	MIDPOINT("Midpoint", "live midpoint price"),
	/** The price sellers have been accepting: what you'll get by selling right away. */
	INSTANT("Sell instantly", "live instant-sell price");

	/**
	 * When buyers pay more than this many times what sellers accept, the item barely trades and the buy price
	 * is likely a one-off, so the sell price is used instead.
	 */
	static final int MAX_SPREAD = 2;

	private final String displayName;
	/** How the price is described in tooltips. */
	private final String description;

	/**
	 * @param high the recent instant-buy price, or 0 if unknown
	 * @param low  the recent instant-sell price, or 0 if unknown
	 * @return the price to use, or 0 if neither is known
	 */
	public int pick(int high, int low)
	{
		if (high <= 0 || low <= 0)
		{
			return Math.max(high, low);
		}
		if ((long) high > (long) low * MAX_SPREAD)
		{
			return low;
		}
		switch (this)
		{
			case MARKET:
				return high;
			case MIDPOINT:
				return (int) (((long) high + low) / 2);
			default:
				return low;
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.assetmanager.value;

import com.assetmanager.AssetManagerConfig;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

/**
 * Looks up item values from RuneLite's price data, or live OSRS Wiki prices when enabled.
 * Must be called on the client thread.
 */
@Singleton
public class ItemValuator
{
	private final ItemManager itemManager;
	private final LivePrices livePrices;
	private final AssetManagerConfig config;
	private final Map<Integer, ItemValues> cache = new HashMap<>();

	@Inject
	ItemValuator(ItemManager itemManager, LivePrices livePrices, AssetManagerConfig config)
	{
		this.itemManager = itemManager;
		this.livePrices = livePrices;
		this.config = config;
	}

	/** Prices move slowly; clear this periodically so long sessions pick up new data. */
	public void clearCache()
	{
		cache.clear();
	}

	public ItemValues get(int itemId)
	{
		int canonical = itemManager.canonicalize(itemId);
		return cache.computeIfAbsent(canonical, this::lookup);
	}

	/** What a nature rune costs to buy: the live instant-buy price if known. */
	public int getNatureRuneCost()
	{
		int live = livePrices.instantBuy(ItemID.NATURERUNE);
		return live > 0 ? live : get(ItemID.NATURERUNE).getWikiPrice();
	}

	/** Where GE sale prices come from, for tooltips. */
	public String getGePriceDescription()
	{
		return livePrices.isAvailable() ? config.gePrice().getDescription() : "RuneLite's 30-min average price";
	}

	private ItemValues lookup(int itemId)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		int guide = toInt(itemManager.getItemPriceWithSource(itemId, false));
		// Live price if enabled, otherwise RuneLite's average of recent trades
		int wiki = livePrices.sellPrice(itemId, config.gePrice());
		if (wiki <= 0)
		{
			wiki = toInt(itemManager.getItemPriceWithSource(itemId, true));
		}
		if (wiki <= 0)
		{
			wiki = guide;
		}
		return new ItemValues(itemId, comp.getName(), guide, wiki, comp.getHaPrice(), comp.getPrice(), comp.isTradeable());
	}

	/** Newer RuneLite versions return prices as a long; no single item is worth more than max cash. */
	private static int toInt(long price)
	{
		return (int) Math.min(price, Integer.MAX_VALUE);
	}
}

package com.assetmanager.value;

import java.util.Set;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

/**
 * Snapshot of everything we know about the worth of a single unit of an item.
 * All prices are per unit, in coins.
 */
@Value
public class ItemValues
{
	/** Death's coffer only accepts items whose guide price is at least this much. */
	public static final int COFFER_MIN_GUIDE_PRICE = 10_000;
	/** Grand Exchange sale tax, in percent. */
	public static final int GE_TAX_PERCENT = 2;
	/** Maximum GE tax charged on a single item. */
	public static final long GE_TAX_CAP = 5_000_000;
	/** Items sold for less than this each aren't taxed. */
	public static final int GE_TAX_FREE_BELOW = 50;

	/** Tradeable items Death's coffer turns down anyway: "You cannot trade that item to Death." */
	private static final Set<Integer> COFFER_REFUSES = Set.of(ItemID.OSRS_BOND, ItemID.BOUGHT_OSRS_BOND, ItemID.OSRS_BOND_UNTRADEABLE);

	int itemId;
	String name;
	/** Jagex's official Grand Exchange guide price. Used by Death's coffer and death fees. */
	int guidePrice;
	/** What one sells for on the GE before tax: the live price if enabled, else RuneLite's average, else the guide price. */
	int wikiPrice;
	int haPrice;
	/** The item's store value, which shops base their prices on. */
	int storePrice;
	boolean tradeable;

	/** Coins added to the coffer when one unit is sacrificed: 105% of the guide price, or 0 if not accepted. */
	public long getCofferValue()
	{
		if (!tradeable || !cofferAccepts(itemId, guidePrice))
		{
			return 0;
		}
		return (long) guidePrice * 105 / 100;
	}

	/** Whether Death's coffer takes a tradeable item with this guide price. Old school bonds it never does. */
	public static boolean cofferAccepts(int itemId, long guidePrice)
	{
		return guidePrice >= COFFER_MIN_GUIDE_PRICE && !COFFER_REFUSES.contains(itemId);
	}

	/** Coins received from selling one unit on the GE at the real price, after tax. */
	public long getGeNetSell()
	{
		if (!tradeable || wikiPrice <= 0)
		{
			return 0;
		}
		return afterTax(wikiPrice);
	}

	/** Coins received for one item sold on the GE at this price, after tax. */
	public static long afterTax(long price)
	{
		long tax = price < GE_TAX_FREE_BELOW ? 0 : Math.min(price * GE_TAX_PERCENT / 100, GE_TAX_CAP);
		return price - tax;
	}

	/** Coins from casting High Level Alchemy on one unit, after paying for the nature rune. */
	public long getHighAlchNet(int natureRuneCost)
	{
		return Math.max(0, haPrice - natureRuneCost);
	}

	/**
	 * The value the game uses to pick which items are kept on death: the higher of the
	 * GE guide price and the alchemy value.
	 */
	public long getProtectionValue()
	{
		return Math.max(guidePrice, haPrice);
	}
}

package com.assetmanager.value;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Optional real-time Grand Exchange prices from the OSRS Wiki (prices.runescape.wiki), refreshed every
 * 5 minutes while enabled. RuneLite's own prices are a single average refreshed every 30 minutes; these give
 * the separate buy and sell prices and how much actually trades.
 */
@Slf4j
@Singleton
public class LivePrices
{
	private static final String BASE = "https://prices.runescape.wiki/api/v1/osrs/";
	// The wiki asks for a descriptive User-Agent
	private static final String USER_AGENT = "Asset Manager RuneLite plugin";
	private static final long REFRESH_MINUTES = 5;
	/** The last day's trading changes slowly, so it's fetched less often. */
	private static final long DAY_REFRESH_MILLIS = TimeUnit.HOURS.toMillis(1);
	/** Item names, values and buy limits hardly ever change: once a day. */
	private static final long MAPPING_REFRESH_MILLIS = TimeUnit.DAYS.toMillis(1);

	/** What the wiki knows about an item that isn't a price. */
	@Value
	public static class Info
	{
		String name;
		/** The item's store value. */
		int value;
		int highAlch;
		/** GE buy limit per 4 hours, or 0 if unknown. */
		int limit;
		/**
		 * Whether it can be alched. Items that can't (event rewards and the like) often have a store value only so
		 * they're protected on death, and shops won't buy them.
		 */
		boolean alchable;
		/** Whether it's a members item. */
		boolean members;
	}

	@Value
	public static class Price
	{
		/** Recent instant-buy price (what buyers pay), or 0 if none traded recently. */
		int high;
		/** Recent instant-sell price (what sellers get), or 0 if none traded recently. */
		int low;
	}

	@Value
	public static class Volume
	{
		/** Items bought at the instant-buy price in the last hour. */
		int high;
		/** Items sold at the instant-sell price in the last hour. */
		int low;
		/** Average instant-buy price over the last hour, or 0 if none. */
		int avgHigh;
		/** Average instant-sell price over the last hour, or 0 if none. */
		int avgLow;
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final ScheduledExecutorService executor;

	private volatile Map<Integer, Price> prices = Collections.emptyMap();
	private volatile Map<Integer, Volume> volumes = Collections.emptyMap();
	/** Items traded in the last day, by id; null until loaded. */
	private volatile Map<Integer, Long> dayVolumes;
	private volatile long dayFetchedAt;
	private volatile Map<Integer, Info> mapping = Collections.emptyMap();
	private volatile long mappingFetchedAt;
	private ScheduledFuture<?> task;
	private Runnable onUpdate = () -> {};

	@Inject
	LivePrices(OkHttpClient http, Gson gson, ScheduledExecutorService executor)
	{
		this.http = http;
		this.gson = gson;
		this.executor = executor;
	}

	public void setOnUpdate(Runnable onUpdate)
	{
		this.onUpdate = onUpdate;
	}

	public synchronized void start()
	{
		if (task == null)
		{
			task = executor.scheduleWithFixedDelay(this::refresh, 0, REFRESH_MINUTES, TimeUnit.MINUTES);
		}
	}

	public synchronized void stop()
	{
		if (task != null)
		{
			task.cancel(false);
			task = null;
		}
		prices = Collections.emptyMap();
		volumes = Collections.emptyMap();
		dayVolumes = null;
		dayFetchedAt = 0;
		mapping = Collections.emptyMap();
		mappingFetchedAt = 0;
	}

	public boolean isAvailable()
	{
		return !prices.isEmpty();
	}

	/**
	 * The recent price to sell at, or 0 if unknown. The latest trade on each side can be a one-off, so the
	 * lower of it and the last hour's average is used, and the buy side is ignored if nobody bought in the last
	 * hour.
	 */
	public int sellPrice(int itemId, GePrice mode)
	{
		Price p = prices.get(itemId);
		if (p == null)
		{
			return 0;
		}
		Volume hour = volumes.get(itemId);
		int high = p.getHigh();
		int low = p.getLow();
		if (hour != null)
		{
			high = hour.getHigh() == 0 ? 0 : lower(high, hour.getAvgHigh());
			low = lower(low, hour.getAvgLow());
		}
		return mode.pick(high, low);
	}

	/**
	 * What buying one costs, waiting as long as the player will, or 0 if the price can't be relied on: nothing traded
	 * in the last hour, or the spread is so wide that the item barely trades. The latest trade on each side can be a
	 * one-off, so the higher of it and the last hour's average is used.
	 */
	public int buyPrice(int itemId, Patience patience)
	{
		Price p = prices.get(itemId);
		Volume hour = volumes.get(itemId);
		if (p == null || hour == null || hour.getHigh() + hour.getLow() == 0)
		{
			return 0;
		}
		int high = Math.max(p.getHigh(), hour.getAvgHigh());
		int low = Math.max(p.getLow(), hour.getAvgLow());
		if (high <= 0 || low <= 0 || (long) high > (long) low * GePrice.MAX_SPREAD)
		{
			return 0;
		}
		switch (patience.getPrice())
		{
			case INSTANT:
				// Paying what buyers have been paying fills right away
				return high;
			case MIDPOINT:
				return (int) (((long) high + low + 1) / 2);
			default:
				// Offering what sellers have been accepting fills in time
				return Math.max(low, Math.min(high, low + 1));
		}
	}

	/** The items with live prices. */
	public Collection<Integer> items()
	{
		return prices.keySet();
	}

	/** Names, values and buy limits by id; empty until loaded. */
	public Info info(int itemId)
	{
		return mapping.get(itemId);
	}

	/** The lower of two prices, ignoring unknown (0) ones. */
	private static int lower(int a, int b)
	{
		return a <= 0 ? b : b <= 0 ? a : Math.min(a, b);
	}

	/** The recent instant-buy price, or 0 if unknown. */
	public int instantBuy(int itemId)
	{
		Price p = prices.get(itemId);
		return p == null ? 0 : p.getHigh();
	}

	/** Items traded in the last hour, or null if unknown. */
	public Volume volume(int itemId)
	{
		return volumes.get(itemId);
	}

	/**
	 * About how many of an item trade on the GE an hour, averaged over the last day so a busy or quiet hour doesn't
	 * skew it; from the last hour alone until the day's figures have loaded. Items missing from the wiki's figures
	 * didn't trade at all. -1 if unknown (live prices off or not loaded yet).
	 */
	public long tradesPerHour(int itemId)
	{
		return tradesPerHour(volumes.get(itemId), !volumes.isEmpty(), dayVolumes, itemId);
	}

	/** Whether trade volumes have loaded, so {@link #tradesPerHour} knows. */
	public boolean hasVolumes()
	{
		return dayVolumes != null || !volumes.isEmpty();
	}

	static long tradesPerHour(Volume hour, boolean hourLoaded, Map<Integer, Long> day, int itemId)
	{
		if (day != null)
		{
			return day.getOrDefault(itemId, 0L) / 24;
		}
		if (!hourLoaded)
		{
			return -1;
		}
		return hour == null ? 0 : (long) hour.getHigh() + hour.getLow();
	}

	private void refresh()
	{
		fetch("latest", data ->
		{
			Map<Integer, Price> map = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : data.entrySet())
			{
				JsonObject o = e.getValue().getAsJsonObject();
				int high = intOf(o, "high");
				int low = intOf(o, "low");
				if (high > 0 || low > 0)
				{
					map.put(Integer.parseInt(e.getKey()), new Price(high, low));
				}
			}
			prices = map;
			log.debug("Loaded {} live prices", map.size());
			onUpdate.run();
		});
		fetch("1h", data ->
		{
			Map<Integer, Volume> map = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : data.entrySet())
			{
				JsonObject o = e.getValue().getAsJsonObject();
				map.put(Integer.parseInt(e.getKey()), new Volume(intOf(o, "highPriceVolume"), intOf(o, "lowPriceVolume"),
					intOf(o, "avgHighPrice"), intOf(o, "avgLowPrice")));
			}
			volumes = map;
		});
		if (System.currentTimeMillis() - mappingFetchedAt >= MAPPING_REFRESH_MILLIS)
		{
			fetchMapping();
		}
		if (System.currentTimeMillis() - dayFetchedAt >= DAY_REFRESH_MILLIS)
		{
			fetch("24h", data ->
			{
				Map<Integer, Long> map = new HashMap<>();
				for (Map.Entry<String, JsonElement> e : data.entrySet())
				{
					JsonObject o = e.getValue().getAsJsonObject();
					map.put(Integer.parseInt(e.getKey()), (long) intOf(o, "highPriceVolume") + intOf(o, "lowPriceVolume"));
				}
				dayVolumes = map;
				dayFetchedAt = System.currentTimeMillis();
				onUpdate.run();
			});
		}
	}

	private void fetchMapping()
	{
		Request request = new Request.Builder().url(BASE + "mapping").header("User-Agent", USER_AGENT).build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Live price request failed: mapping", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						log.debug("Live price request failed: mapping {}", response.code());
						return;
					}
					Map<Integer, Info> map = new HashMap<>();
					for (JsonElement e : gson.fromJson(body.charStream(), JsonArray.class))
					{
						JsonObject o = e.getAsJsonObject();
						if (o.has("id") && o.has("name"))
						{
							map.put(o.get("id").getAsInt(), new Info(o.get("name").getAsString(), intOf(o, "value"),
								intOf(o, "highalch"), intOf(o, "limit"), o.has("highalch"),
								o.has("members") && o.get("members").getAsBoolean()));
						}
					}
					mapping = map;
					mappingFetchedAt = System.currentTimeMillis();
					onUpdate.run();
				}
				catch (RuntimeException e)
				{
					log.debug("Unreadable live price response: mapping", e);
				}
			}
		});
	}

	private void fetch(String endpoint, Consumer<JsonObject> onData)
	{
		Request request = new Request.Builder().url(BASE + endpoint).header("User-Agent", USER_AGENT).build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Live price request failed: {}", endpoint, e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						log.debug("Live price request failed: {} {}", endpoint, response.code());
						return;
					}
					JsonObject json = gson.fromJson(body.charStream(), JsonObject.class);
					onData.accept(json.getAsJsonObject("data"));
				}
				catch (RuntimeException e)
				{
					log.debug("Unreadable live price response: {}", endpoint, e);
				}
			}
		});
	}

	private static int intOf(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsInt() : 0;
	}
}

package com.assetmanager.value;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * How long the player is willing to wait for Grand Exchange offers to fill when flipping. The quicker, the worse the
 * prices: an instant buy pays what sellers are asking, a patient one waits at what sellers have been accepting. More
 * patience also lets more trade, up to the buy limit.
 */
@Getter
@RequiredArgsConstructor
public enum Patience
{
	INSTANT("Instantly", 0.25, GePrice.INSTANT),
	HOUR("Within an hour", 1, GePrice.MIDPOINT),
	FEW_HOURS("A few hours", 4, GePrice.MARKET),
	OVERNIGHT("Overnight", 12, GePrice.MARKET);

	private final String displayName;
	/** Hours of GE trading the player waits for. */
	private final double hours;
	/**
	 * Where in the spread offers go: INSTANT buys at what buyers have been paying and sells at what sellers accept;
	 * MARKET the other way round, waiting for the better price.
	 */
	private final GePrice price;

	/** How many of an item trade on the GE in this time, from how many trade an hour; -1 if unknown. */
	public long tradesIn(long perHour)
	{
		return perHour < 0 ? -1 : (long) Math.floor(perHour * hours);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.assetmanager.value;

import com.assetmanager.shop.SellRules;
import com.assetmanager.shop.ShopCatalog;
import com.assetmanager.shop.ShopOffer;
import com.assetmanager.shop.ShopPerks;
import com.assetmanager.shop.ShopTrip;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Works out the best way to cash out each spare stack: high alching, the GE, or a shop. Each stack goes one way.
 * <p>
 * In order:
 * <ol>
 * <li>A shop, if each sale beats the GE and alching by the minimum per item, and the trip gains at least the minimum
 * for each world it visits. On each world the player sells every stack for that shop, then hops to a fresh world, so
 * a big stack that only wins by a little isn't worth all the hopping it needs and is alched or sold on the GE instead.
 * Each world gains about the same, so a stack worth hopping for stays worth it as it's sold.</li>
 * <li>Alching, if it beats the GE by the minimum per item.</li>
 * <li>The GE, for stacks worth at least the minimum sale there.</li>
 * <li>Alching anyway, for small stacks that alch for more than they'd sell for on the GE.</li>
 * </ol>
 * Ironmen alch by default, so for them only shops that beat alching are suggested.
 */
public final class SaleAdvisor
{
	/** Rounds of moving stacks off trips that aren't worth it; each round can shift them to other shops or fewer worlds. */
	private static final int MAX_ROUNDS = 50;

	@Value
	public static class Result
	{
		public static final Result NONE = new Result(Collections.emptyList(), Collections.emptyMap(), Collections.emptyMap());

		/** Most valuable first. */
		List<SaleSuggestion> sales;
		/** Planned shop trips, by shop name. */
		Map<String, ShopTrip> trips;
		/** Shops each item isn't going to, because the trip wasn't worth it for that stack. */
		Map<Integer, Set<String>> skippedShops;
	}

	private SaleAdvisor()
	{
	}

	/**
	 * @param values         item values by canonical id
	 * @param spare          spare quantity per item id, after keep rules
	 * @param canUseGe       false for ironmen
	 * @param natureRuneCost cost of a nature rune, deducted from alch value
	 * @param minAlchGain    alch rather than sell on the GE when alching beats it by at least this much per item
	 * @param minGeSale      only suggest the GE for stacks worth at least this much there, after tax; smaller stacks
	 *                       that alch for more are alched
	 * @param shops          shop prices, or null to ignore shops
	 * @param perks          what the player has that affects shop prices
	 * @param rules          when selling to a shop is worth it
	 */
	public static Result suggest(Map<Integer, ItemValues> values, Map<Integer, Integer> spare, boolean canUseGe,
		int natureRuneCost, int minAlchGain, long minGeSale, ShopCatalog shops, ShopPerks perks, SellRules rules)
	{
		return suggest(values, spare, canUseGe, natureRuneCost, minAlchGain, minGeSale, shops, perks, rules, Collections.emptyMap());
	}

	/**
	 * As above.
	 *
	 * @param avoid shops not to send each item to, such as those others have overstocked it at on every world
	 */
	public static Result suggest(Map<Integer, ItemValues> values, Map<Integer, Integer> spare, boolean canUseGe,
		int natureRuneCost, int minAlchGain, long minGeSale, ShopCatalog shops, ShopPerks perks, SellRules rules,
		Map<Integer, Set<String>> avoid)
	{
		Map<Integer, Set<String>> skip = new HashMap<>();
		avoid.forEach((id, names) -> skip.put(id, new HashSet<>(names)));
		// Each stack goes where it gains most; stacks on trips not worth making then move elsewhere, which can make
		// another trip worth it
		for (int round = 0; ; round++)
		{
			List<SaleSuggestion> out = evaluate(values, spare, canUseGe, natureRuneCost, minAlchGain, minGeSale, shops, perks, rules,
				skip);
			Map<String, List<SaleSuggestion>> byShop = new LinkedHashMap<>();
			for (SaleSuggestion x : out)
			{
				if (x.getType() == SaleSuggestion.Type.SHOP)
				{
					// A group of shops paying the same is one trip: any of them will do
					byShop.computeIfAbsent(x.getShopOffer().getShop().getGroup(), k -> new ArrayList<>()).add(x);
				}
			}

			boolean changed = false;
			Map<String, ShopTrip> trips = new HashMap<>();
			for (Map.Entry<String, List<SaleSuggestion>> e : byShop.entrySet())
			{
				ShopTrip trip = plan(e.getKey(), e.getValue());
				if (!worthIt(trip, rules))
				{
					// The stacks needing the most worlds are what make the hopping; without them the rest may be
					// worth a shorter trip. A one-world trip that isn't worth it loses everything.
					for (SaleSuggestion x : e.getValue())
					{
						if (x.getShopOffer().getWorlds() >= trip.getWorlds())
						{
							skip.computeIfAbsent(x.getValues().getItemId(), k -> new HashSet<>()).add(e.getKey());
						}
					}
					changed = true;
				}
				trips.put(e.getKey(), trip);
			}
			if (!changed || round >= MAX_ROUNDS)
			{
				out.sort(Comparator.comparingLong(SaleSuggestion::getTotal).reversed());
				return new Result(out, trips, skip);
			}
		}
	}

	/** A trip selling every stack: as many worlds as the stack needing the most, gaining what they all gain together. */
	static ShopTrip plan(String shop, List<SaleSuggestion> stacks)
	{
		int worlds = 1;
		long gain = 0;
		for (SaleSuggestion x : stacks)
		{
			worlds = Math.max(worlds, x.getShopOffer().getWorlds());
			gain += x.getGain();
		}
		return new ShopTrip(shop, worlds, gain);
	}

	/** Whether a trip gains at least the minimum for each world it visits. */
	static boolean worthIt(ShopTrip trip, SellRules rules)
	{
		return trip.getGain() >= (long) rules.getMinGainPerWorld() * trip.getWorlds();
	}

	private static List<SaleSuggestion> evaluate(Map<Integer, ItemValues> values, Map<Integer, Integer> spare, boolean canUseGe,
		int natureRuneCost, int minAlchGain, long minGeSale, ShopCatalog shops, ShopPerks perks, SellRules rules,
		Map<Integer, Set<String>> skip)
	{
		List<SaleSuggestion> out = new ArrayList<>();
		for (Map.Entry<Integer, ItemValues> e : values.entrySet())
		{
			ItemValues v = e.getValue();
			int qty = spare.getOrDefault(e.getKey(), 0);
			// Untradeables have no GE price to compare against, and are often needed (quest items, etc.).
			if (qty <= 0 || !v.isTradeable())
			{
				continue;
			}

			long geUnit = canUseGe ? v.getGeNetSell() : 0;
			long alchUnit = v.getHighAlchNet(natureRuneCost);
			long altUnit = Math.max(geUnit, alchUnit);
			long ge = geUnit * qty;
			long alch = alchUnit * qty;
			ShopOffer offer = shops == null ? null : shops.bestOffer(v.getName(), v.getStorePrice(), qty, true, perks, altUnit, rules,
				skip.getOrDefault(e.getKey(), Collections.emptySet()));

			// Often a shop only wins by the cost of a nature rune per item, which is why it's worth it
			if (offer != null && offer.getQuantity() > 0)
			{
				out.add(new SaleSuggestion(v, qty, SaleSuggestion.Type.SHOP, offer.getTotal(), altUnit * qty,
					geUnit >= alchUnit ? "GE sell" : "High alch", offer));
			}
			// Otherwise, for mains: alching when it's clearly better than the GE, then the GE for a stack worth selling
			// there, then alching any small stack that alchs for more
			else if (canUseGe && alch - ge >= (long) Math.max(1, minAlchGain) * qty)
			{
				out.add(new SaleSuggestion(v, qty, SaleSuggestion.Type.ALCH, alch, ge, "GE sell", null));
			}
			else if (canUseGe && ge > 0 && ge >= minGeSale)
			{
				// Alching may make a little more, but not enough to be worth the casts, so it isn't a loss
				out.add(new SaleSuggestion(v, qty, SaleSuggestion.Type.GE, ge, Math.min(alch, ge), "High alch", null));
			}
			else if (canUseGe && alch > ge)
			{
				out.add(new SaleSuggestion(v, qty, SaleSuggestion.Type.ALCH, alch, ge, "GE sell", null));
			}
		}
		return out;
	}
}

package com.assetmanager.value;

import com.assetmanager.shop.ShopOffer;
import lombok.Value;

/** A banked item and the best way to cash it out: high alching, a shop, or the GE. */
@Value
public class SaleSuggestion
{
	public enum Type
	{
		ALCH,
		SHOP,
		GE,
	}

	ItemValues values;
	/** Spare quantity, after the player's keep rules. */
	int quantity;
	Type type;
	/** Coins from the suggested option for the whole quantity. */
	long total;
	/** Coins from the next best option. */
	long alternativeTotal;
	/** e.g. "GE sell", "High alch" or "Shop". */
	String alternativeLabel;
	/** The shop to sell to, for SHOP suggestions. */
	ShopOffer shopOffer;

	public long getGain()
	{
		return total - alternativeTotal;
	}
}

