package com.assetmanager.keep;

import static org.junit.Assert.assertEquals;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class HoldingsTest
{
	private static final int PLATEBODY = 1127;

	private static Map<Integer, Integer> of(int id, int n)
	{
		return Collections.singletonMap(id, n);
	}

	@Test
	public void carriedOnesAreSpareFirst()
	{
		KeepRules rules = new KeepRules();
		rules.set(PLATEBODY, 1);
		// Keeping 1: a banked one is kept, so the one carried (to a shop, say) is spare, with 2 banked
		Holdings h = new Holdings().with(Holdings.Place.INVENTORY, of(PLATEBODY, 1)).with(Holdings.Place.BANK, of(PLATEBODY, 3));
		assertEquals(1, h.spare(Holdings.Place.INVENTORY, PLATEBODY, rules));
		assertEquals(2, h.spare(Holdings.Place.BANK, PLATEBODY, rules));
		assertEquals(3, (int) h.spare(rules).get(PLATEBODY));

		// With none in the bank, the carried one is the kept one
		h = new Holdings().with(Holdings.Place.INVENTORY, of(PLATEBODY, 1)).with(Holdings.Place.BANK, of(PLATEBODY, 0));
		assertEquals(0, h.spare(Holdings.Place.INVENTORY, PLATEBODY, rules));

		// Wearing one counts too, and worn items are never spare
		h = new Holdings().with(Holdings.Place.WORN, of(PLATEBODY, 1)).with(Holdings.Place.INVENTORY, of(PLATEBODY, 2));
		assertEquals(0, h.spare(Holdings.Place.WORN, PLATEBODY, rules));
		assertEquals(2, h.spare(Holdings.Place.INVENTORY, PLATEBODY, rules));
	}

	@Test
	public void seedVaultCountsAfterTheBank()
	{
		int seed = 5295;
		KeepRules rules = new KeepRules();
		rules.set(seed, 10);
		Holdings h = new Holdings().with(Holdings.Place.BANK, of(seed, 4)).with(Holdings.Place.SEED_VAULT, of(seed, 20));
		assertEquals(0, h.spare(Holdings.Place.BANK, seed, rules));
		assertEquals(14, h.spare(Holdings.Place.SEED_VAULT, seed, rules));

		// No rule: everything but what's worn is spare
		Map<Integer, Integer> spare = new Holdings().with(Holdings.Place.INVENTORY, new HashMap<>(of(seed, 3))).spare(new KeepRules());
		assertEquals(3, (int) spare.get(seed));
	}

	@Test
	public void keepAllMeansNothingSpare()
	{
		KeepRules rules = new KeepRules();
		rules.set(1704, KeepRules.KEEP_ALL);
		Holdings h = new Holdings().with(Holdings.Place.BANK, of(1704, 12));
		assertEquals(0, h.spare(Holdings.Place.BANK, 1704, rules));
		assertEquals(Collections.emptyMap(), h.spare(rules));
	}
}

package com.assetmanager.keep;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class KeepRulesTest
{
	@Test
	public void spareQuantities()
	{
		KeepRules r = new KeepRules();
		r.set(1127, 1);                    // keep one rune platebody for a clue
		r.set(1712, KeepRules.KEEP_ALL);   // collect glories
		assertEquals(4, r.spare(1127, 5));
		assertEquals(0, r.spare(1127, 1));
		assertEquals(0, r.spare(1712, 20));
		assertEquals(7, r.spare(999, 7));
	}

	@Test
	public void encodesAndDecodes()
	{
		KeepRules r = new KeepRules();
		r.set(1127, 1);
		r.set(1712, KeepRules.KEEP_ALL);
		KeepRules back = KeepRules.decode(r.encode());
		assertEquals(1, back.get(1127));
		assertEquals(KeepRules.KEEP_ALL, back.get(1712));
		assertEquals(0, KeepRules.decode("garbage,5:x,7:2").get(5));
		assertEquals(2, KeepRules.decode("garbage,5:x,7:2").get(7));
	}

	@Test
	public void parsesInput()
	{
		assertEquals(Integer.valueOf(3), KeepRules.parseInput(" 3 "));
		assertEquals(Integer.valueOf(1_000), KeepRules.parseInput("1,000"));
		assertEquals(Integer.valueOf(KeepRules.KEEP_ALL), KeepRules.parseInput("All"));
		assertEquals(Integer.valueOf(0), KeepRules.parseInput(""));
		assertNull(KeepRules.parseInput("lots"));
		assertNull(KeepRules.parseInput("-2"));
	}

	@Test
	public void zeroRemovesRule()
	{
		KeepRules r = new KeepRules();
		r.set(1127, 1);
		r.set(1127, 0);
		assertEquals(false, r.has(1127));
	}

	@Test
	public void canPartWithOnlyTheSpares()
	{
		KeepRules r = new KeepRules();
		r.set(1127, 1);
		r.set(1704, KeepRules.KEEP_ALL);
		// Keeping 1 rune platebody: with 1 owned none can go, with 4 owned three can
		assertEquals(0, r.canPart(1127, 1));
		assertEquals(3, r.canPart(1127, 4));
		// Keeping every glory
		assertEquals(0, r.canPart(1704, 20));
		// No rule
		assertEquals(5, r.canPart(4151, 5));
	}

	@Test
	public void parsesAmountsLikeTheGame()
	{
		assertEquals(Integer.valueOf(5), KeepRules.parseInput("5"));
		assertEquals(Integer.valueOf(10_000), KeepRules.parseInput("10k"));
		assertEquals(Integer.valueOf(10_000), KeepRules.parseInput("10K"));
		assertEquals(Integer.valueOf(1_500_000), KeepRules.parseInput("1.5m"));
		assertEquals(Integer.valueOf(2_000_000_000), KeepRules.parseInput("2b"));
		assertEquals(Integer.valueOf(1_000), KeepRules.parseInput("1,000"));
		assertEquals(Integer.valueOf(KeepRules.KEEP_ALL), KeepRules.parseInput("all"));
		assertEquals(Integer.valueOf(0), KeepRules.parseInput(""));
		// Not whole items, too many, or not a number
		assertEquals(null, KeepRules.parseInput("1.5"));
		assertEquals(null, KeepRules.parseInput("3b"));
		assertEquals(null, KeepRules.parseInput("lots"));
	}
}

package com.assetmanager.keep;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class VariantsTest
{
	private static final int PRAYER_4 = 2434;
	private static final int PRAYER_3 = 139;
	private static final int PRAYER_1 = 143;
	private static final int GLORY_6 = 11978;
	private static final int GLORY_1 = 1706;
	private static final int GLORY = 1704;
	private static final int GLORY_T4 = 10354;
	private static final int WHIP = 4151;

	private static Map<Integer, String> names()
	{
		Map<Integer, String> n = new HashMap<>();
		n.put(PRAYER_4, "Prayer potion(4)");
		n.put(PRAYER_3, "Prayer potion(3)");
		n.put(PRAYER_1, "Prayer potion(1)");
		n.put(GLORY_6, "Amulet of glory(6)");
		n.put(GLORY_1, "Amulet of glory(1)");
		n.put(GLORY, "Amulet of glory");
		n.put(GLORY_T4, "Amulet of glory(t4)");
		n.put(WHIP, "Abyssal whip");
		return n;
	}

	@Test
	public void groupsDosesAndCharges()
	{
		Map<Integer, List<Integer>> groups = Variants.group(names());
		assertEquals(Arrays.asList(PRAYER_4, PRAYER_3, PRAYER_1), groups.get(PRAYER_1));
		// Uncharged last
		assertEquals(Arrays.asList(GLORY_6, GLORY_1, GLORY), groups.get(GLORY));
		// Trimmed glories are their own thing, and so is anything with no variants
		assertFalse(groups.containsKey(GLORY_T4));
		assertFalse(groups.containsKey(WHIP));
		assertEquals("Amulet of glory(t)", Variants.base("Amulet of glory(t4)"));
	}

	@Test
	public void variantsShareOneRuleAndTheFullestAreKept()
	{
		KeepRules rules = new KeepRules();
		rules.setVariants(Variants.group(names()));
		// Keep 3 prayer potions, chosen from a (3)
		rules.set(PRAYER_3, 3);
		assertEquals(3, rules.get(PRAYER_1));
		assertEquals(1, rules.asMap().size());

		Map<Integer, Integer> bank = new HashMap<>();
		bank.put(PRAYER_4, 2);
		bank.put(PRAYER_3, 1);
		bank.put(PRAYER_1, 4);
		Map<Integer, Integer> inv = new HashMap<>();
		inv.put(PRAYER_3, 1);
		Holdings h = new Holdings().with(Holdings.Place.INVENTORY, inv).with(Holdings.Place.BANK, bank);
		// Kept: both (4)s, then the banked (3); the carried (3) and the (1)s are spare
		assertEquals(0, h.spare(Holdings.Place.BANK, PRAYER_4, rules));
		assertEquals(1, h.spare(Holdings.Place.INVENTORY, PRAYER_3, rules));
		assertEquals(0, h.spare(Holdings.Place.BANK, PRAYER_3, rules));
		assertEquals(4, h.spare(Holdings.Place.BANK, PRAYER_1, rules));
		assertEquals(8, h.total(PRAYER_1, rules));
		assertEquals(5, rules.canPart(PRAYER_1, 8));
	}

	@Test
	public void separateRulesForVariantsAreMerged()
	{
		KeepRules rules = new KeepRules();
		rules.set(GLORY_6, 1);
		rules.set(GLORY_1, 2);
		assertTrue(rules.setVariants(Variants.group(names())));
		assertEquals(1, rules.asMap().size());
		assertEquals(2, rules.get(GLORY));
	}
}

package com.assetmanager.shop;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class ShopCatalogTest
{
	private static Shop shop(String name, boolean general, int mult, int delta, Integer glovesTier, Integer glovesMult, Map<String, Shop.Item> items)
	{
		Shop s = new Shop();
		s.setName(name);
		s.setLocation("");
		s.setGeneral(general);
		s.setBuyMultiplier(mult);
		s.setDelta(delta);
		s.setGlovesTier(glovesTier);
		s.setGlovesBuyMultiplier(glovesMult);
		s.setItems(items);
		return s;
	}

	private static Shop.Item item(Integer gloves)
	{
		Shop.Item i = new Shop.Item();
		i.setG(gloves);
		return i;
	}

	@Test
	public void priceDropsAsShopFillsUpAndStopsAtTenPercent()
	{
		// 60% dropping 3% per item: 600, 570, ... 120, then 100 (the floor) for the rest
		assertEquals(600 + 570 + 540, ShopCatalog.totalFor(1000, 3, 600, 30));
		long all = ShopCatalog.totalFor(1000, 30, 600, 30);
		long expected = 0;
		for (int k = 0; k < 30; k++)
		{
			expected += Math.max(100, 600 - 30 * k);
		}
		assertEquals(expected, all);
		// No drop at all
		assertEquals(500L * 10_000, ShopCatalog.totalFor(1000, 10_000, 500, 0));
	}

	@Test
	public void hopWhenTheNextSaleNoLongerBeatsTheAlternative()
	{
		// 60% dropping 3% per item, vs 500 each elsewhere: 600, 570, 540, 510 beat it, 480 doesn't, so 4 per world
		assertEquals(4, ShopCatalog.perWorld(1000, 600, 30, 501, 100));
		ShopCatalog c = new ShopCatalog(Collections.singletonList(
			shop("General Store", true, 600, 30, null, null, Collections.emptyMap())), "test");
		ShopOffer o = c.bestOffer("Thing", 1000, 10, true, ShopPerks.NONE, 500, 1, 10);
		assertEquals(4, o.getPerWorld());
		assertEquals(3, o.getWorlds());
		assertEquals(2 * (600 + 570 + 540 + 510) + 600 + 570, o.getTotal());
		assertEquals(10, o.getQuantity());

		// The whole stack or nothing: hopping at most 2 worlds isn't enough for 10
		assertEquals(0, c.bestOffer("Thing", 1000, 10, true, ShopPerks.NONE, 500, 1, 2).getQuantity());

		// No limit: 100 at 4 per world is 25 worlds
		ShopOffer unlimited = c.bestOffer("Thing", 1000, 100, true, ShopPerks.NONE, 500, 1, ShopCatalog.NO_WORLD_LIMIT);
		assertEquals(100, unlimited.getQuantity());
		assertEquals(25, unlimited.getWorlds());

		// Not even the first sale beats 650 elsewhere
		assertEquals(0, c.bestOffer("Thing", 1000, 10, true, ShopPerks.NONE, 650, 1, 10).getQuantity());

		// Void Knight General Store: 40% dropping only 0.3%, so a stack of 20 sells on one world
		assertEquals(20, ShopCatalog.perWorld(1000, 400, 3, 301, 20));
	}

	@Test
	public void specialtyShopsOnlyBuyWhatTheyStock()
	{
		Map<String, Shop.Item> amulets = new HashMap<>();
		amulets.put("amulet of power", item(1000));
		ShopCatalog c = new ShopCatalog(Arrays.asList(
			shop("Davon's Amulet Store", false, 900, 20, 1, null, amulets),
			shop("General Store", true, 400, 30, null, null, Collections.emptyMap())), "test");

